package com.clanhq.verifier;

import com.clanhq.verifier.feature.ClanHQFeature;
import java.awt.BorderLayout;
import java.awt.CardLayout;
import java.awt.Color;
import java.awt.Component;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.GridLayout;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.io.IOException;
import java.io.InputStream;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import javax.swing.BorderFactory;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.JButton;
import javax.swing.ImageIcon;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.imageio.ImageIO;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.PluginPanel;

/** Top-level navigation for independent ClanHQ feature panels. */
final class ClanHQPanel extends PluginPanel
{
    private static final int ICON_SIZE = 20;
    private static final Color TRANSPARENT = new Color(0, 0, 0, 0);
    private final CardLayout cards = new CardLayout();
    private final JPanel cardPanel = new JPanel(cards);
    private final Map<String, JButton> navigation = new LinkedHashMap<>();

    ClanHQPanel(List<ClanHQFeature> features)
    {
        setLayout(new BorderLayout());
        setBackground(ColorScheme.DARK_GRAY_COLOR);

        JPanel header = new JPanel();
        header.setLayout(new BoxLayout(header, BoxLayout.Y_AXIS));
        header.setBackground(ColorScheme.DARK_GRAY_COLOR);
        header.setBorder(BorderFactory.createEmptyBorder(8, 8, 8, 8));

        JLabel title = new JLabel("ClanHQ");
        title.setAlignmentX(Component.LEFT_ALIGNMENT);
        header.add(title);
        header.add(Box.createRigidArea(new Dimension(0, 6)));

        JPanel buttons = new JPanel();
        buttons.setLayout(new GridLayout(1, Math.max(1, features.size()), 4, 0));
        buttons.setBackground(ColorScheme.DARK_GRAY_COLOR);
        buttons.setAlignmentX(Component.LEFT_ALIGNMENT);

        for (ClanHQFeature feature : features)
        {
            JButton button = new JButton(loadIcon(
                feature.getNavigationIconResource()));
            button.setPreferredSize(new Dimension(36, 32));
            button.setToolTipText(feature.getDisplayName() + " — "
                + feature.getDescription());
            button.getAccessibleContext().setAccessibleName(
                feature.getDisplayName());
            button.getAccessibleContext().setAccessibleDescription(
                feature.getDescription());
            button.setFocusable(false);
            applyInactiveBorder(button);
            button.addActionListener(event -> showFeature(feature.getId()));
            navigation.put(feature.getId(), button);
            buttons.add(button);
            cardPanel.add(feature.getPanel(), feature.getId());
        }

        header.add(buttons);
        cardPanel.setBackground(ColorScheme.DARK_GRAY_COLOR);
        add(header, BorderLayout.NORTH);
        add(cardPanel, BorderLayout.CENTER);

        if (!features.isEmpty())
        {
            showFeature(features.get(0).getId());
        }
        else
        {
            JLabel empty = new JLabel(
                "<html>Enable a ClanHQ feature in the plugin settings.</html>");
            empty.setBorder(BorderFactory.createEmptyBorder(10, 10, 10, 10));
            cardPanel.add(empty, "empty");
            cards.show(cardPanel, "empty");
        }
    }

    private void showFeature(String featureId)
    {
        cards.show(cardPanel, featureId);
        navigation.forEach((id, button) ->
        {
            button.setEnabled(true);
            if (id.equals(featureId))
            {
                applyActiveBorder(button);
            }
            else
            {
                applyInactiveBorder(button);
            }
        });
    }

    private static ImageIcon loadIcon(String resource)
    {
        try (InputStream stream =
            ClanHQPanel.class.getResourceAsStream(resource))
        {
            if (stream == null)
            {
                throw new IllegalStateException(
                    "Missing ClanHQ navigation icon: " + resource);
            }
            BufferedImage source = ImageIO.read(stream);
            if (source == null)
            {
                throw new IllegalStateException(
                    "Invalid ClanHQ navigation icon: " + resource);
            }
            BufferedImage scaled = new BufferedImage(
                ICON_SIZE,
                ICON_SIZE,
                BufferedImage.TYPE_INT_ARGB);
            Graphics2D graphics = scaled.createGraphics();
            graphics.setRenderingHint(
                RenderingHints.KEY_INTERPOLATION,
                RenderingHints.VALUE_INTERPOLATION_NEAREST_NEIGHBOR);
            graphics.drawImage(source, 0, 0, ICON_SIZE, ICON_SIZE, null);
            graphics.dispose();
            return new ImageIcon(scaled);
        }
        catch (IOException error)
        {
            throw new IllegalStateException(
                "Could not load ClanHQ navigation icon: " + resource,
                error);
        }
    }

    private static void applyActiveBorder(JButton button)
    {
        button.setBorder(BorderFactory.createCompoundBorder(
            BorderFactory.createMatteBorder(
                0, 0, 2, 0, ColorScheme.BRAND_ORANGE),
            BorderFactory.createEmptyBorder(2, 4, 0, 4)));
    }

    private static void applyInactiveBorder(JButton button)
    {
        button.setBorder(BorderFactory.createCompoundBorder(
            BorderFactory.createMatteBorder(0, 0, 2, 0, TRANSPARENT),
            BorderFactory.createEmptyBorder(2, 4, 0, 4)));
    }
}

package com.clanhq.verifier;

import java.awt.Color;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Range;

@ConfigGroup(ClanHQVerifierConfig.GROUP)
public interface ClanHQVerifierConfig extends Config
{
    String GROUP = "clanhqVerifier";

    enum DailyTasksDisplayMode
    {
        OVERLAY,
        INFO_BOXES
    }

    @ConfigSection(
        name = "Features",
        description = "ClanHQ tools available in the side panel",
        position = -1)
    String FEATURES_SECTION = "features";

    @ConfigItem(
        keyName = "eventsEnabled",
        name = "Events",
        description = "Join and display ClanHQ competitions",
        section = FEATURES_SECTION,
        position = 1)
    default boolean eventsEnabled()
    {
        return true;
    }

    @ConfigItem(
        keyName = "bingoEnabled",
        name = "Bingo",
        description = "Load the active Bingo board and submit eligible Loot Tracker events",
        section = FEATURES_SECTION,
        position = 2)
    default boolean bingoEnabled()
    {
        return false;
    }

    @ConfigItem(
        keyName = "dailyTasksEnabled",
        name = "Tasks",
        description = "View and claim ClanHQ currency daily tasks",
        section = FEATURES_SECTION,
        position = 3)
    default boolean dailyTasksEnabled()
    {
        return true;
    }

    @ConfigItem(
        keyName = "bingoScreenshotsEnabled",
        name = "Bingo screenshots",
        description = "Attach a watermarked gameplay screenshot to Bingo drops",
        section = FEATURES_SECTION,
        position = 4)
    default boolean bingoScreenshotsEnabled()
    {
        return false;
    }

    @ConfigSection(
        name = "Task overlay",
        description = "Customize the in-game daily task display",
        position = 0)
    String TASK_OVERLAY_SECTION = "taskOverlay";

    @ConfigItem(
        keyName = "dailyTasksOverlay",
        name = "Show overlay",
        description = "Show today's ClanHQ task progress in the game overlay",
        section = TASK_OVERLAY_SECTION,
        position = 0)
    default boolean dailyTasksOverlay()
    {
        return true;
    }

    @ConfigItem(
        keyName = "dailyTasksDisplayMode",
        name = "Display mode",
        description = "Choose between the compact task overlay and RuneLite info boxes",
        section = TASK_OVERLAY_SECTION,
        position = 1)
    default DailyTasksDisplayMode dailyTasksDisplayMode()
    {
        return DailyTasksDisplayMode.OVERLAY;
    }

    @Range(min = 0, max = 255)
    @ConfigItem(
        keyName = "dailyTasksOverlayOpacity",
        name = "Opacity",
        description = "Background opacity (0 is transparent, 255 is opaque)",
        section = TASK_OVERLAY_SECTION,
        position = 2)
    default int dailyTasksOverlayOpacity()
    {
        return 220;
    }

    @ConfigSection(
        name = "ClanHQ connection",
        description = "Where review evidence will be submitted",
        position = 1)
    String CONNECTION_SECTION = "connection";

    @ConfigSection(
        name = "Bingo",
        description = "Connect to the active ClanHQ Bingo event",
        position = 2)
    String BINGO_SECTION = "bingo";

    @ConfigItem(
        keyName = "bingoPasswordOverlay",
        name = "Display Overlay",
        description = "Show the Bingo event/challenge password overlay above your character",
        section = BINGO_SECTION,
        position = 0)
    default boolean bingoPasswordOverlay()
    {
        return false;
    }

    @ConfigItem(
        keyName = "bingoPasswordOverlayDateTime",
        name = "Date & Time",
        description = "Also show the current date and time in the password overlay",
        section = BINGO_SECTION,
        position = 1)
    default boolean bingoPasswordOverlayDateTime()
    {
        return false;
    }

    @ConfigItem(
        keyName = "bingoEventPassword",
        name = "Event Password",
        description = "Shown in the overlay unless your clan has set one for the active Bingo event",
        section = BINGO_SECTION,
        position = 2)
    default String bingoEventPassword()
    {
        return "";
    }

    @ConfigItem(
        keyName = "bingoChallengePassword",
        name = "Challenge Password",
        description = "Shown in the overlay unless your clan has set one for the active Bingo event",
        section = BINGO_SECTION,
        position = 3)
    default String bingoChallengePassword()
    {
        return "";
    }

    @ConfigItem(
        keyName = "bingoEventPasswordColor",
        name = "Event Password Color",
        description = "Colors below must be different",
        section = BINGO_SECTION,
        position = 4)
    default Color bingoEventPasswordColor()
    {
        return Color.GREEN;
    }

    @ConfigItem(
        keyName = "bingoChallengePasswordColor",
        name = "Challenge Password Color",
        description = "Colors below must be different",
        section = BINGO_SECTION,
        position = 5)
    default Color bingoChallengePasswordColor()
    {
        return Color.WHITE;
    }

    @ConfigItem(
        keyName = "apiBaseUrl",
        name = "ClanHQ API URL",
        description = "HTTPS destination supplied by your clan; localhost HTTP is allowed for development",
        section = CONNECTION_SECTION,
        position = 0)
    default String apiBaseUrl()
    {
        return "";
    }

    @ConfigItem(
        keyName = "installationToken",
        name = "Installation token",
        description = "Unique revocable token created automatically during pairing",
        section = CONNECTION_SECTION,
        secret = true,
        position = 1)
    default String installationToken()
    {
        return "";
    }

    @ConfigItem(
        keyName = "pairingCode",
        name = "Pairing code",
        description = "One-time code generated by /plugin pair in Discord",
        section = CONNECTION_SECTION,
        secret = true,
        position = 2)
    default String pairingCode()
    {
        return "";
    }

    @ConfigItem(
        keyName = "installationLabel",
        name = "Device name",
        description = "A recognizable name for this RuneLite installation",
        section = CONNECTION_SECTION,
        position = 3)
    default String installationLabel()
    {
        return "RuneLite";
    }

    @ConfigItem(
        keyName = "pendingInstallationToken",
        name = "Pending installation token",
        description = "Internal pairing retry state",
        section = CONNECTION_SECTION,
        hidden = true,
        secret = true,
        position = 4)
    default String pendingInstallationToken()
    {
        return "";
    }

}

package com.clanhq.verifier;

import com.clanhq.verifier.bingo.BingoFeature;
import com.clanhq.verifier.bingo.BingoPasswordOverlay;
import com.clanhq.verifier.bingo.service.BingoScreenshotService;
import com.clanhq.verifier.bingo.transport.BingoApiClient;
import com.clanhq.verifier.character.CharacterSyncApiClient;
import com.clanhq.verifier.character.CharacterSyncFeature;
import com.clanhq.verifier.daily.DailyTasksFeature;
import com.clanhq.verifier.daily.ActivityTelemetryDetector;
import com.clanhq.verifier.daily.transport.DailyTasksApiClient;
import com.clanhq.verifier.event.EventFeature;
import com.clanhq.verifier.event.transport.EventApiClient;
import com.clanhq.verifier.feature.ClanHQFeature;
import com.clanhq.verifier.overview.IdentityApiClient;
import com.clanhq.verifier.overview.OverviewFeature;
import com.clanhq.verifier.service.ApiDestinationService;
import com.clanhq.verifier.service.LocalPlayerSnapshotService;
import com.clanhq.verifier.service.SubmissionConsentService;
import com.clanhq.verifier.loot.ObservedDrop;
import com.google.inject.Provides;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Objects;
import java.util.concurrent.ScheduledExecutorService;
import javax.inject.Inject;
import javax.swing.SwingUtilities;
import net.runelite.api.Client;
import net.runelite.api.ChatMessageType;
import net.runelite.api.GameState;
import net.runelite.api.Skill;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.StatChanged;
import net.runelite.api.events.VarbitChanged;
import net.runelite.api.events.WidgetLoaded;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.SkillIconManager;
import net.runelite.client.game.SpriteManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.plugins.loottracker.LootReceived;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.DrawManager;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.ui.overlay.infobox.InfoBoxManager;
import net.runelite.client.util.ImageUtil;
import net.runelite.client.util.Text;
import okhttp3.OkHttpClient;

@PluginDescriptor(
    name = "ClanHQ",
    description = "Clan tools for character sync, events, Bingo, and daily tasks",
    tags = {"clan", "events", "bingo", "daily", "verification"})
// RuneLite 1.13 rejects @PluginDependency on a plugin that exposes no
// injectable services - LootTrackerPlugin doesn't, and this plugin never
// injected it, only subscribed to its LootReceived event below. Other
// plugin-hub authors hit the exact "Plugin dependency LootTrackerPlugin
// does not expose any services" failure this same way and the confirmed
// fix was simply dropping the annotation; @Subscribe onLootReceived below
// still fires without it.
public final class ClanHQVerifierPlugin extends Plugin
{
    @Inject private ClientThread clientThread;
    @Inject private Client client;
    @Inject private OkHttpClient httpClient;
    @Inject private DrawManager drawManager;
    @Inject private ScheduledExecutorService executor;
    @Inject private ClientToolbar clientToolbar;
    @Inject private OverlayManager overlayManager;
    @Inject private LocalPlayerSnapshotService snapshotService;
    @Inject private ApiDestinationService apiDestinationService;
    @Inject private SkillIconManager skillIconManager;
    @Inject private ClanHQVerifierConfig config;
    @Inject private ConfigManager configManager;
    @Inject private ItemManager itemManager;
    @Inject private InfoBoxManager infoBoxManager;
    @Inject private SpriteManager spriteManager;

    private ClanHQPanel shellPanel;
    private BingoFeature bingoFeature;
    private BingoPasswordOverlay bingoPasswordOverlay;
    private EventFeature eventFeature;
    private DailyTasksFeature dailyTasksFeature;
    private ActivityTelemetryDetector activityTelemetryDetector;
    private OverviewFeature overviewFeature;
    private volatile String loggedInRsn;
    private List<ClanHQFeature> features = Collections.emptyList();
    private NavigationButton navigationButton;

    @Provides
    ClanHQVerifierConfig provideConfig(ConfigManager manager)
    {
        return manager.getConfig(ClanHQVerifierConfig.class);
    }

    @Override
    protected void startUp()
    {
        rebuildFeatures();
    }

    @Override
    protected void shutDown()
    {
        disposeFeatures();
        shellPanel = null;
    }

    @Subscribe
    public void onConfigChanged(ConfigChanged event)
    {
        if (!ClanHQVerifierConfig.GROUP.equals(event.getGroup()))
        {
            return;
        }
        if ("bingoEnabled".equals(event.getKey())
            || "eventsEnabled".equals(event.getKey())
            || "dailyTasksEnabled".equals(event.getKey())
            || "dailyTasksOverlay".equals(event.getKey())
            || "dailyTasksDisplayMode".equals(event.getKey())
            || "bingoPasswordOverlay".equals(event.getKey()))
        {
            SwingUtilities.invokeLater(this::rebuildFeatures);
            return;
        }
        SwingUtilities.invokeLater(() ->
        {
            if (overviewFeature != null) { overviewFeature.refresh(); }
            if (bingoFeature != null) { bingoFeature.refreshManifest(); }
            if (eventFeature != null) { eventFeature.refresh(); }
            if (dailyTasksFeature != null) { dailyTasksFeature.refresh(); }
        });
    }

    private void rebuildFeatures()
    {
        disposeFeatures();
        List<ClanHQFeature> enabled = new ArrayList<>();
        overviewFeature = new OverviewFeature(
            new IdentityApiClient(httpClient, config, apiDestinationService),
            config,
            configManager,
            () -> dailyTasksFeature == null ? null : dailyTasksFeature.getSnapshot(),
            () -> bingoFeature == null ? null : bingoFeature.getManifest(),
            () -> loggedInRsn);
        SubmissionConsentService submissionConsent =
            new SubmissionConsentService(config, apiDestinationService);
        enabled.add(overviewFeature);
        CharacterSyncFeature characterSyncFeature = new CharacterSyncFeature(
            new CharacterSyncApiClient(
                httpClient, config, apiDestinationService),
            snapshotService,
            clientThread,
            submissionConsent);
        enabled.add(characterSyncFeature);
        if (config.eventsEnabled())
        {
            eventFeature = new EventFeature(new EventApiClient(
                httpClient, config, apiDestinationService), this::currentRsn);
            enabled.add(eventFeature);
        }
        if (config.bingoEnabled())
        {
            bingoFeature = new BingoFeature(
                new BingoApiClient(httpClient, config, apiDestinationService),
                new BingoScreenshotService(drawManager, executor),
                config::bingoScreenshotsEnabled,
                snapshotService,
                clientThread,
                submissionConsent,
                () -> { if (overviewFeature != null) overviewFeature.refreshSummary(); });
            enabled.add(bingoFeature);
            if (config.bingoPasswordOverlay())
            {
                bingoPasswordOverlay = new BingoPasswordOverlay(
                    () -> bingoFeature == null ? null : bingoFeature.getManifest(),
                    config::bingoEventPassword,
                    config::bingoChallengePassword,
                    config::bingoEventPasswordColor,
                    config::bingoChallengePasswordColor,
                    config::bingoPasswordOverlayDateTime);
                overlayManager.add(bingoPasswordOverlay);
            }
        }
        if (config.dailyTasksEnabled())
        {
            dailyTasksFeature = new DailyTasksFeature(
                new DailyTasksApiClient(
                    httpClient, config, apiDestinationService),
                config,
                configManager,
                skillIconManager,
                executor,
                () -> { if (overviewFeature != null) overviewFeature.refreshSummary(); },
                itemManager,
                this,
                infoBoxManager,
                spriteManager);
            activityTelemetryDetector = new ActivityTelemetryDetector(
                dailyTasksFeature, this::currentRsn);
            clientThread.invokeLater(this::resetActivityTelemetry);
            enabled.add(dailyTasksFeature);
            if (config.dailyTasksOverlay()
                && config.dailyTasksDisplayMode()
                    != ClanHQVerifierConfig.DailyTasksDisplayMode.INFO_BOXES)
            {
                overlayManager.add(dailyTasksFeature.getOverlay());
            }
        }
        features = enabled;
        shellPanel = new ClanHQPanel(enabled);
        features.forEach(ClanHQFeature::startUp);
        navigationButton = NavigationButton.builder()
            .tooltip("ClanHQ")
            .icon(createIcon())
            .panel(shellPanel)
            .build();
        clientToolbar.addNavigation(navigationButton);
    }

    private void disposeFeatures()
    {
        if (dailyTasksFeature != null)
        {
            overlayManager.remove(dailyTasksFeature.getOverlay());
        }
        if (bingoPasswordOverlay != null)
        {
            overlayManager.remove(bingoPasswordOverlay);
            bingoPasswordOverlay = null;
        }
        features.forEach(ClanHQFeature::shutDown);
        features = Collections.emptyList();
        overviewFeature = null;
        bingoFeature = null;
        eventFeature = null;
        dailyTasksFeature = null;
        activityTelemetryDetector = null;
        if (navigationButton != null)
        {
            clientToolbar.removeNavigation(navigationButton);
            navigationButton = null;
        }
    }

    @Subscribe
    public void onLootReceived(LootReceived event)
    {
        if (client.getLocalPlayer() == null) { return; }
        ObservedDrop observedDrop = new ObservedDrop(
            client.getLocalPlayer().getName(),
            event.getType().name(),
            event.getName(),
            event.getItems(),
            java.time.Instant.now());
        if (bingoFeature != null)
        {
            bingoFeature.onDrop(observedDrop);
        }
        if (eventFeature != null) { eventFeature.onLoot(event.getName()); }
        if (dailyTasksFeature != null)
        {
            dailyTasksFeature.observeDrop(observedDrop);
            dailyTasksFeature.observeLoot(event.getName());
        }
    }

    @Subscribe
    public void onStatChanged(StatChanged event)
    {
        if (eventFeature != null)
        {
            eventFeature.onSkillExperience(
                event.getSkill().getName(), event.getXp());
        }
        if (dailyTasksFeature != null)
        {
            dailyTasksFeature.observeSkillExperience(
                event.getSkill().getName(), event.getXp());
        }
        if (activityTelemetryDetector != null
            && event.getSkill() == Skill.AGILITY
            && client.getLocalPlayer() != null)
        {
            WorldPoint location = client.getLocalPlayer().getWorldLocation();
            activityTelemetryDetector.onAgilityExperience(
                event.getXp(), location.getRegionID(), location.getX(),
                location.getY(), location.getPlane());
        }
    }

    @Subscribe
    public void onChatMessage(ChatMessage event)
    {
        if (activityTelemetryDetector == null
            || (event.getType() != ChatMessageType.GAMEMESSAGE
                && event.getType() != ChatMessageType.SPAM
                && event.getType() != ChatMessageType.MESBOX
                && event.getType() != ChatMessageType.CONSOLE))
        {
            return;
        }
        activityTelemetryDetector.onChatMessage(
            Text.removeTags(event.getMessage()));
    }

    @Subscribe
    public void onWidgetLoaded(WidgetLoaded event)
    {
        if (activityTelemetryDetector != null
            && event.getGroupId() == InterfaceID.BARBASSAULT_WAVECOMPLETE)
        {
            activityTelemetryDetector.onBarbarianAssaultWaveCompleted();
        }
    }

    @Subscribe
    public void onVarbitChanged(VarbitChanged event)
    {
        if (activityTelemetryDetector == null)
        {
            return;
        }
        if (event.getVarbitId() == VarbitID.HOSIDIUS_TITHE_SCORE)
        {
            activityTelemetryDetector.onTitheSackAmount(event.getValue());
        }
        else if (event.getVarbitId()
            == VarbitID.COLLECTION_MINIGAMES_PEST_COMPLETED)
        {
            activityTelemetryDetector.onCompletionCounter(
                "pest_control_game", event.getValue());
        }
        else if (event.getVarbitId()
            == VarbitID.COLLECTION_OTHER_HUNTER_GUILD_COMPLETED)
        {
            activityTelemetryDetector.onCompletionCounter(
                "hunter_rumour", event.getValue());
        }
        else if (event.getVarbitId()
            == VarbitID.COLLECTION_MINIGAMES_TRAWLER_COMPLETED)
        {
            activityTelemetryDetector.onCompletionCounter(
                "fishing_trawler_game", event.getValue());
        }
        else if (event.getVarbitId()
            == VarbitID.COLLECTION_MINIGAMES_GIANTSFOUNDRY_COMPLETED)
        {
            activityTelemetryDetector.onCompletionCounter(
                "giants_foundry_commission", event.getValue());
        }
        else if (event.getVarbitId()
            == VarbitID.COLLECTION_MINIGAMES_CONSTRUCTIONCONTRACTS_COMPLETED)
        {
            activityTelemetryDetector.onCompletionCounter(
                "mahogany_homes_contract", event.getValue());
        }
        else if (event.getVarbitId()
            == VarbitID.VARLAMORE_WYRM_AGILITY_BASIC_PROGRESS)
        {
            activityTelemetryDetector.onWyrmAgilityProgress(
                false, event.getValue());
        }
        else if (event.getVarbitId()
            == VarbitID.VARLAMORE_WYRM_AGILITY_ADVANCED_PROGRESS)
        {
            activityTelemetryDetector.onWyrmAgilityProgress(
                true, event.getValue());
        }
    }

    @Subscribe
    public void onGameStateChanged(GameStateChanged event)
    {
        if (event.getGameState() != GameState.LOGGED_IN)
        {
            loggedInRsn = null;
            return;
        }
        loggedInRsn = currentRsn();
        resetActivityTelemetry();
        if (overviewFeature != null) { overviewFeature.refresh(); }
        if (eventFeature != null) { eventFeature.refresh(); }
        if (bingoFeature != null) { bingoFeature.refreshManifest(); }
    }

    /**
     * LOGGED_IN can arrive before RuneLite has populated the local player.
     * Recheck on ticks and refresh Overview only when the character changes.
     */
    @Subscribe
    public void onGameTick(GameTick event)
    {
        if (client.getGameState() != GameState.LOGGED_IN)
        {
            return;
        }
        String current = currentRsn();
        if (!Objects.equals(current, loggedInRsn))
        {
            loggedInRsn = current;
            if (overviewFeature != null)
            {
                overviewFeature.refresh();
            }
        }
    }

    private String currentRsn()
    {
        return client.getLocalPlayer() == null
            ? null : client.getLocalPlayer().getName();
    }

    private void resetActivityTelemetry()
    {
        ActivityTelemetryDetector detector = activityTelemetryDetector;
        if (detector == null || client.getGameState() != GameState.LOGGED_IN)
        {
            return;
        }
        detector.resetSession(
            client.getSkillExperience(Skill.AGILITY),
            client.getVarbitValue(VarbitID.HOSIDIUS_TITHE_SCORE),
            client.getVarbitValue(
                VarbitID.VARLAMORE_WYRM_AGILITY_BASIC_PROGRESS),
            client.getVarbitValue(
                VarbitID.VARLAMORE_WYRM_AGILITY_ADVANCED_PROGRESS));
        detector.resetCompletionCounter("pest_control_game",
            client.getVarbitValue(
                VarbitID.COLLECTION_MINIGAMES_PEST_COMPLETED));
        detector.resetCompletionCounter("hunter_rumour",
            client.getVarbitValue(
                VarbitID.COLLECTION_OTHER_HUNTER_GUILD_COMPLETED));
        detector.resetCompletionCounter("fishing_trawler_game",
            client.getVarbitValue(
                VarbitID.COLLECTION_MINIGAMES_TRAWLER_COMPLETED));
        detector.resetCompletionCounter("giants_foundry_commission",
            client.getVarbitValue(
                VarbitID.COLLECTION_MINIGAMES_GIANTSFOUNDRY_COMPLETED));
        detector.resetCompletionCounter("mahogany_homes_contract",
            client.getVarbitValue(
                VarbitID.COLLECTION_MINIGAMES_CONSTRUCTIONCONTRACTS_COMPLETED));
    }

    private static BufferedImage createIcon()
    {
        return ImageUtil.loadImageResource(
            ClanHQVerifierPlugin.class,
            "/com/clanhq/verifier/icons/overview.png");
    }
}

package com.clanhq.verifier.bingo;

import com.clanhq.verifier.bingo.model.BingoDrop;
import com.clanhq.verifier.bingo.model.BingoItem;
import com.clanhq.verifier.bingo.model.BingoManifest;
import com.clanhq.verifier.bingo.model.BingoCharacterSubmission;
import com.clanhq.verifier.bingo.transport.BingoApiClient;
import com.clanhq.verifier.bingo.service.BingoScreenshotService;
import com.clanhq.verifier.service.LocalPlayerSnapshotService;
import com.clanhq.verifier.service.SubmissionConsentService;
import com.clanhq.verifier.feature.ClanHQFeature;
import com.clanhq.verifier.loot.ObservedDrop;
import java.time.Instant;
import java.util.Collection;
import java.util.concurrent.CompletableFuture;
import java.util.function.BooleanSupplier;
import javax.swing.JComponent;
import javax.swing.SwingUtilities;
import net.runelite.client.game.ItemStack;
import net.runelite.client.callback.ClientThread;

public final class BingoFeature implements ClanHQFeature
{
    private final BingoApiClient apiClient;
    private final BingoPanel panel;
    private final BingoScreenshotService screenshotService;
    private final BooleanSupplier screenshotsEnabled;
    private final LocalPlayerSnapshotService snapshotService;
    private final ClientThread clientThread;
    private final SubmissionConsentService consentService;
    private final Runnable overviewChanged;
    private volatile BingoManifest manifest;
    private volatile boolean running;
    private volatile BingoCharacterSubmission pendingCharacterSubmission;

    public BingoFeature(
        BingoApiClient apiClient,
        BingoScreenshotService screenshotService,
        BooleanSupplier screenshotsEnabled,
        LocalPlayerSnapshotService snapshotService,
        ClientThread clientThread,
        SubmissionConsentService consentService,
        Runnable overviewChanged)
    {
        this.apiClient = apiClient;
        this.screenshotService = screenshotService;
        this.screenshotsEnabled = screenshotsEnabled;
        this.snapshotService = snapshotService;
        this.clientThread = clientThread;
        this.consentService = consentService;
        this.overviewChanged = overviewChanged;
        this.panel = new BingoPanel(this::refreshManifest);
    }

    @Override
    public String getId()
    {
        return "bingo";
    }

    @Override
    public String getDisplayName()
    {
        return "Bingo";
    }

    @Override
    public String getNavigationIconResource()
    {
        return "/com/clanhq/verifier/icons/bingo.png";
    }

    @Override
    public String getDescription()
    {
        return "Automatically submit eligible RuneLite loot to ClanHQ.";
    }

    @Override
    public JComponent getPanel()
    {
        return panel;
    }

    @Override
    public void startUp()
    {
        running = true;
        refreshManifest();
    }

    @Override
    public void shutDown()
    {
        running = false;
        manifest = null;
        pendingCharacterSubmission = null;
    }

    public void refreshManifest()
    {
        panel.setLoading();
        apiClient.fetchManifest().thenAccept(result ->
            SwingUtilities.invokeLater(() ->
            {
                if (!running)
                {
                    return;
                }
                result.getManifest().ifPresentOrElse(value ->
                {
                    if (manifest == null
                        || !manifest.getEventId().equals(value.getEventId()))
                    {
                        pendingCharacterSubmission = null;
                    }
                    manifest = value;
                    overviewChanged.run();
                    panel.showManifest(value);
                }, () ->
                {
                    manifest = null;
                    panel.showManifestError(result.getMessage(),
                        result.getSiteUrl().orElse(null));
                });
            }));
    }

    public void submitCharacter()
    {
        BingoManifest active = manifest;
        if (!running || active == null)
        {
            panel.showCharacterSubmission(false,
                "Load an active Bingo board first.");
            return;
        }
        if (!active.getCharacterCheck().canSubmit())
        {
            panel.showCharacterSubmission(false,
                "No additional character check is currently required.");
            return;
        }
        if (!consentService.confirm(
            panel, "Bingo " + active.getName()))
        {
            panel.showCharacterSubmissionCancelled();
            return;
        }
        panel.setCharacterSubmitting();
        BingoCharacterSubmission pending = pendingCharacterSubmission;
        if (pending != null)
        {
            deliverCharacter(pending);
            return;
        }
        clientThread.invokeLater(() ->
        {
            try
            {
                BingoCharacterSubmission captured =
                    new BingoCharacterSubmission(
                        active.getEventId(),
                        snapshotService.captureCompleteItemsEvidence());
                pendingCharacterSubmission = captured;
                deliverCharacter(captured);
            }
            catch (RuntimeException exception)
            {
                SwingUtilities.invokeLater(() -> panel.showCharacterSubmission(
                    false, exception.getMessage()));
            }
        });
    }

    private void deliverCharacter(BingoCharacterSubmission submission)
    {
        apiClient.submitCharacter(submission).thenAccept(result ->
            SwingUtilities.invokeLater(() ->
            {
                if (!running)
                {
                    return;
                }
                if (result.isSuccessful())
                {
                    pendingCharacterSubmission = null;
                    panel.showCharacterSubmission(true, result.getMessage());
                    refreshManifest();
                }
                else
                {
                    panel.showCharacterSubmission(false, result.getMessage());
                }
            }));
    }

    public void onLoot(String rsn, String sourceType, String sourceName,
        Collection<ItemStack> items)
    {
        onDrop(new ObservedDrop(rsn, sourceType, sourceName, items,
            Instant.now()));
    }

    public BingoManifest getManifest()
    {
        return manifest;
    }

    public void onDrop(ObservedDrop observedDrop)
    {
        BingoManifest active = manifest;
        if (!running || active == null || observedDrop == null
            || observedDrop.getPlayer() == null
            || observedDrop.getPlayer().trim().isEmpty())
        {
            return;
        }
        for (ItemStack observed : observedDrop.getItems())
        {
            BingoItem item = active.findItem(observed.getId()).orElse(null);
            if (item == null || observed.getQuantity() < item.getMinimumQuantity())
            {
                continue;
            }
            BingoDrop bingoDrop = new BingoDrop(
                active.getEventId(),
                observedDrop.getPlayer(),
                item,
                observed.getQuantity(),
                observedDrop.getSourceType(),
                observedDrop.getSourceName() == null ? "Unknown loot source"
                    : observedDrop.getSourceName(),
                observedDrop.getObservedAt());
            SwingUtilities.invokeLater(() -> panel.showDetected(
                item.getName(), bingoDrop.getQuantity(), bingoDrop.getSourceName()));
            CompletableFuture<byte[]> screenshot =
                screenshotsEnabled.getAsBoolean()
                    ? screenshotService.capture(bingoDrop, active.getName())
                        .handle((bytes, error) -> error == null ? bytes : null)
                    : CompletableFuture.completedFuture(null);
            screenshot.thenCompose(bytes -> apiClient.submit(bingoDrop, bytes))
                .thenAccept(result ->
                SwingUtilities.invokeLater(() ->
                {
                    if (running)
                    {
                        panel.showDelivery(item.getName(),
                            result.isSuccessful(), result.getMessage());
                    }
                }));
        }
    }
}

package com.clanhq.verifier.bingo;

import com.clanhq.verifier.bingo.model.BingoManifest;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Component;
import java.awt.Dimension;
import java.awt.Font;
import java.net.URI;
import javax.swing.BorderFactory;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.JButton;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JScrollPane;
import javax.swing.JTextArea;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.util.LinkBrowser;

final class BingoPanel extends JPanel
{
    private static final int WRAP_WIDTH = 190;
    private static final Color CARD_COLOR = new Color(39, 39, 43);
    private static final Color TITLE_COLOR = new Color(0x6FA8DC);
    private final JLabel titleLabel = new JLabel("Bingo Companion");
    private final JLabel eventLabel = new JLabel("No active Bingo");
    private final JLabel participationLabel = new JLabel("Not joined");
    private final JLabel teamLabel = new JLabel("Team: Unassigned");
    private final JLabel trackingLabel = new JLabel("Tracking: Inactive");
    private final JLabel statusLabel = new JLabel();
    private final JTextArea activity = new JTextArea();
    private final JButton refreshButton = new JButton("Refresh");
    private final JButton siteButton = new JButton("Bingo site ↗");
    private String siteUrl;

    BingoPanel(Runnable refreshAction)
    {
        setLayout(new BorderLayout());
        setBorder(BorderFactory.createEmptyBorder(8, 8, 8, 8));
        setBackground(ColorScheme.DARK_GRAY_COLOR);

        JPanel header = verticalPanel();
        JPanel titleRow = new JPanel(new BorderLayout(6, 0));
        titleRow.setBackground(ColorScheme.DARK_GRAY_COLOR);
        titleRow.setAlignmentX(Component.LEFT_ALIGNMENT);
        titleLabel.setFont(titleLabel.getFont().deriveFont(Font.BOLD, 16f));
        titleLabel.setForeground(TITLE_COLOR);
        titleRow.add(titleLabel, BorderLayout.CENTER);
        siteButton.setMargin(new java.awt.Insets(3, 6, 3, 6));
        siteButton.addActionListener(event -> openSite());
        titleRow.add(siteButton, BorderLayout.EAST);
        titleRow.setMaximumSize(new Dimension(Integer.MAX_VALUE,
            titleRow.getPreferredSize().height));
        header.add(titleRow);
        header.add(Box.createRigidArea(new Dimension(0, 5)));

        eventLabel.setFont(eventLabel.getFont().deriveFont(Font.BOLD));
        eventLabel.setAlignmentX(Component.LEFT_ALIGNMENT);
        header.add(eventLabel);
        header.add(Box.createRigidArea(new Dimension(0, 6)));
        statusLabel.setAlignmentX(Component.LEFT_ALIGNMENT);
        header.add(statusLabel);

        JPanel summary = new JPanel();
        summary.setLayout(new BoxLayout(summary, BoxLayout.Y_AXIS));
        summary.setBackground(CARD_COLOR);
        summary.setBorder(BorderFactory.createEmptyBorder(6, 6, 6, 6));
        summary.setAlignmentX(Component.LEFT_ALIGNMENT);
        participationLabel.setAlignmentX(Component.LEFT_ALIGNMENT);
        teamLabel.setAlignmentX(Component.LEFT_ALIGNMENT);
        trackingLabel.setAlignmentX(Component.LEFT_ALIGNMENT);
        summary.add(participationLabel);
        summary.add(Box.createRigidArea(new Dimension(0, 2)));
        summary.add(trackingLabel);
        summary.add(Box.createRigidArea(new Dimension(0, 2)));
        summary.add(teamLabel);
        summary.add(Box.createRigidArea(new Dimension(0, 4)));
        refreshButton.addActionListener(event -> refreshAction.run());
        refreshButton.setAlignmentX(Component.LEFT_ALIGNMENT);
        summary.add(refreshButton);
        summary.setMaximumSize(new Dimension(Integer.MAX_VALUE,
            summary.getPreferredSize().height));

        JPanel content = verticalPanel();
        content.add(summary);
        content.add(Box.createRigidArea(new Dimension(0, 7)));
        content.add(sectionLabel("Recent Activity"));
        activity.setEditable(false);
        activity.setLineWrap(true);
        activity.setWrapStyleWord(true);
        activity.setColumns(20);
        activity.setRows(4);
        activity.setBackground(ColorScheme.DARKER_GRAY_COLOR);
        activity.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
        activity.setBorder(BorderFactory.createEmptyBorder(6, 6, 6, 6));
        activity.setAlignmentX(Component.LEFT_ALIGNMENT);
        activity.setMaximumSize(new Dimension(Integer.MAX_VALUE,
            Integer.MAX_VALUE));
        activity.setText("No matching drops detected this session.");
        content.add(activity);
        content.add(Box.createRigidArea(new Dimension(0, 7)));

        JScrollPane scroll = new JScrollPane(content,
            JScrollPane.VERTICAL_SCROLLBAR_AS_NEEDED,
            JScrollPane.HORIZONTAL_SCROLLBAR_NEVER);
        scroll.setBorder(null);
        add(header, BorderLayout.NORTH);
        add(scroll, BorderLayout.CENTER);
        showStatus("Load the active Bingo event to begin.");
    }

    void setLoading()
    {
        refreshButton.setEnabled(false);
        showStatus("Loading the active Bingo event...");
    }

    void showManifest(BingoManifest manifest)
    {
        refreshButton.setEnabled(true);
        siteUrl = manifest.getSiteUrl();
        titleLabel.setText("Bingo Companion");
        eventLabel.setText("Bingo Status");
        participationLabel.setText(manifest.isJoined() ? "Joined" : "Not joined");
        teamLabel.setText("Team: "
            + (manifest.getTeamName() == null
                ? "Unassigned" : manifest.getTeamName()));
        trackingLabel.setText("Tracking: Active");
        showStatus("Ready to track eligible Bingo drops.");
    }

    void showManifestError(String message, String responseSiteUrl)
    {
        refreshButton.setEnabled(true);
        siteUrl = responseSiteUrl;
        eventLabel.setText("No active Bingo");
        participationLabel.setText("Not joined");
        teamLabel.setText("Team: Unassigned");
        trackingLabel.setText("Tracking: Inactive");
        showStatus(message);
    }

    void showParticipation(boolean joined, String teamName, String message)
    {
        participationLabel.setText(joined ? "Joined" : "Not joined");
        teamLabel.setText("Team: "
            + (teamName == null ? "Unassigned" : teamName));
        showStatus(message);
    }

    void showDetected(String itemName, int quantity, String source)
    {
        append("Detected " + quantity + " × " + itemName + " from "
            + source + "; submitting...");
    }

    void showDelivery(String itemName, boolean successful, String message)
    {
        append((successful ? "✓ Sent " : "✗ Failed ") + itemName
            + ": " + message);
    }

    void setCharacterSubmitting()
    {
        showStatus("Capturing and submitting the character snapshot...");
    }

    void showCharacterSubmission(boolean successful, String message)
    {
        showStatus((successful ? "Character submitted. " : "Submission failed. ")
            + message);
    }

    void resetCharacterSubmission()
    {
    }

    void showCharacterSubmissionCancelled()
    {
        showStatus("Character submission cancelled.");
    }

    private void openSite()
    {
        String configured = siteUrl;
        try
        {
            URI uri = URI.create(configured == null ? "" : configured.trim());
            String scheme = uri.getScheme();
            if (uri.getHost() == null
                || !("https".equalsIgnoreCase(scheme)
                    || "http".equalsIgnoreCase(scheme)))
            {
                throw new IllegalArgumentException();
            }
            LinkBrowser.browse(uri.toString());
            showStatus("Opened the Bingo website.");
        }
        catch (IllegalArgumentException exception)
        {
            showStatus("ClanHQ did not provide a valid Bingo site URL.");
        }
    }

    private void append(String message)
    {
        String existing = activity.getText();
        if (existing.startsWith("No matching drops"))
        {
            existing = "";
        }
        activity.setText(message + (existing.isEmpty() ? "" : "\n\n" + existing));
        activity.setCaretPosition(0);
    }

    private void showStatus(String message)
    {
        statusLabel.setText("<html><body style='width: " + WRAP_WIDTH
            + "px'>" + escapeHtml(message) + "</body></html>");
    }

    private static JLabel sectionLabel(String text)
    {
        JLabel label = new JLabel(text);
        label.setAlignmentX(Component.LEFT_ALIGNMENT);
        label.setForeground(ColorScheme.BRAND_ORANGE);
        label.setFont(label.getFont().deriveFont(Font.BOLD));
        return label;
    }

    private static String escapeHtml(String text)
    {
        return text.replace("&", "&amp;")
            .replace("<", "&lt;")
            .replace(">", "&gt;");
    }

    private static JPanel verticalPanel()
    {
        JPanel panel = new JPanel();
        panel.setLayout(new BoxLayout(panel, BoxLayout.Y_AXIS));
        panel.setBackground(ColorScheme.DARK_GRAY_COLOR);
        panel.setAlignmentX(Component.LEFT_ALIGNMENT);
        return panel;
    }
}

package com.clanhq.verifier.bingo;

import com.clanhq.verifier.bingo.model.BingoManifest;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Point;
import java.time.ZoneOffset;
import java.time.format.DateTimeFormatter;
import java.util.function.BooleanSupplier;
import java.util.function.Supplier;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.PanelComponent;

/**
 * Shows the active Bingo event's password lines, mirroring the standalone
 * Clan Events plugin: each player types their own Event/Challenge password
 * into the local config below, and those values show here. When the active
 * ClanHQ Bingo manifest carries a clan-wide password, it overrides the
 * local value for that line - see {@link BingoPasswordResolver}.
 */
public final class BingoPasswordOverlay extends OverlayPanel
{
    private static final DateTimeFormatter DATE_TIME_FORMAT =
        DateTimeFormatter.ofPattern("dd/MM/yyyy HH:mm 'UTC'");

    private final Supplier<BingoManifest> manifestSupplier;
    private final Supplier<String> localEventPasswordSupplier;
    private final Supplier<String> localChallengePasswordSupplier;
    private final Supplier<Color> eventPasswordColorSupplier;
    private final Supplier<Color> challengePasswordColorSupplier;
    private final BooleanSupplier dateTimeEnabledSupplier;

    public BingoPasswordOverlay(
        Supplier<BingoManifest> manifestSupplier,
        Supplier<String> localEventPasswordSupplier,
        Supplier<String> localChallengePasswordSupplier,
        Supplier<Color> eventPasswordColorSupplier,
        Supplier<Color> challengePasswordColorSupplier,
        BooleanSupplier dateTimeEnabledSupplier)
    {
        this.manifestSupplier = manifestSupplier;
        this.localEventPasswordSupplier = localEventPasswordSupplier;
        this.localChallengePasswordSupplier = localChallengePasswordSupplier;
        this.eventPasswordColorSupplier = eventPasswordColorSupplier;
        this.challengePasswordColorSupplier = challengePasswordColorSupplier;
        this.dateTimeEnabledSupplier = dateTimeEnabledSupplier;
        setPosition(OverlayPosition.TOP_LEFT);
        setMovable(true);
        setResizable(true);
    }

    @Override
    public Dimension render(Graphics2D graphics)
    {
        BingoManifest manifest = manifestSupplier.get();
        String eventPassword = BingoPasswordResolver.resolve(
            localEventPasswordSupplier.get(),
            manifest == null ? null : manifest.getEventPassword());
        String challengePassword = BingoPasswordResolver.resolve(
            localChallengePasswordSupplier.get(),
            manifest == null ? null : manifest.getChallengePassword());
        boolean showDateTime = dateTimeEnabledSupplier.getAsBoolean();

        if (eventPassword.isEmpty() && challengePassword.isEmpty()
            && !showDateTime)
        {
            return null;
        }

        PanelComponent panel = getPanelComponent();
        panel.setGap(new Point(0, 2));

        if (!eventPassword.isEmpty())
        {
            panel.getChildren().add(LineComponent.builder()
                .left(eventPassword)
                .leftColor(eventPasswordColorSupplier.get())
                .build());
        }
        if (!challengePassword.isEmpty())
        {
            panel.getChildren().add(LineComponent.builder()
                .left(challengePassword)
                .leftColor(challengePasswordColorSupplier.get())
                .build());
        }
        if (showDateTime)
        {
            panel.getChildren().add(LineComponent.builder()
                .left(DATE_TIME_FORMAT.format(
                    java.time.Instant.now().atZone(ZoneOffset.UTC)))
                .leftColor(Color.WHITE)
                .build());
        }
        return super.render(graphics);
    }
}

package com.clanhq.verifier.bingo;

/**
 * Resolves which value to show for each Bingo overlay password line.
 *
 * The ClanHQ Bingo manifest can optionally carry a clan-wide password set
 * by the event organizer; when it does, that value always wins. When the
 * manifest does not set one (the common case), each player falls back to
 * their own local RuneLite config value, typed in exactly the way the
 * standalone Clan Events plugin works today.
 */
public final class BingoPasswordResolver
{
    private BingoPasswordResolver()
    {
    }

    /**
     * @param localValue the player's own local config value, may be null
     * @param manifestValue the server-pushed value from the active Bingo
     *     manifest, may be null or absent
     * @return the value to display; never null, empty when neither source
     *     has one
     */
    public static String resolve(String localValue, String manifestValue)
    {
        String manifestTrimmed = manifestValue == null ? "" : manifestValue.trim();
        if (!manifestTrimmed.isEmpty())
        {
            return manifestTrimmed;
        }
        return localValue == null ? "" : localValue.trim();
    }
}

package com.clanhq.verifier.bingo.model;

public final class BingoCharacterCheckStatus
{
    private final String status;
    private final String nextPhase;
    private final int checkpointCount;
    private final String baselineCapturedAt;
    private final String finalCapturedAt;

    public BingoCharacterCheckStatus(String status, String nextPhase,
        int checkpointCount, String baselineCapturedAt, String finalCapturedAt)
    {
        this.status = status;
        this.nextPhase = nextPhase;
        this.checkpointCount = checkpointCount;
        this.baselineCapturedAt = baselineCapturedAt;
        this.finalCapturedAt = finalCapturedAt;
    }

    public static BingoCharacterCheckStatus empty()
    {
        return new BingoCharacterCheckStatus(
            "NOT_SUBMITTED", "BASELINE", 0, null, null);
    }

    public String getStatus() { return status; }
    public String getNextPhase() { return nextPhase; }
    public int getCheckpointCount() { return checkpointCount; }
    public String getBaselineCapturedAt() { return baselineCapturedAt; }
    public String getFinalCapturedAt() { return finalCapturedAt; }

    public String getDisplayStatus()
    {
        switch (status)
        {
            case "BASELINE_CAPTURED": return "Baseline captured";
            case "CHECKPOINT_CAPTURED":
                return "Checkpoint captured (" + checkpointCount + ")";
            case "FINALIZED": return "Finalized";
            default: return "Not submitted";
        }
    }

    public String getButtonLabel()
    {
        switch (nextPhase)
        {
            case "BASELINE": return "Submit Pre-Bingo Check";
            case "CHECKPOINT": return "Submit Checkpoint";
            case "FINAL": return "Submit Final Check";
            default: return "Character Submit";
        }
    }

    public boolean canSubmit()
    {
        return !"COMPLETE".equals(nextPhase) && !"CLOSED".equals(nextPhase);
    }
}

package com.clanhq.verifier.bingo.model;

import com.clanhq.verifier.model.VerificationSnapshot;
import java.time.Instant;
import java.util.Objects;
import java.util.UUID;

public final class BingoCharacterSubmission
{
    private final String submissionId;
    private final String eventId;
    private final Instant capturedAt;
    private final VerificationSnapshot snapshot;

    public BingoCharacterSubmission(String eventId,
        VerificationSnapshot snapshot)
    {
        this(UUID.randomUUID().toString(), eventId, Instant.now(), snapshot);
    }

    BingoCharacterSubmission(String submissionId, String eventId,
        Instant capturedAt, VerificationSnapshot snapshot)
    {
        this.submissionId = Objects.requireNonNull(submissionId);
        this.eventId = Objects.requireNonNull(eventId);
        this.capturedAt = Objects.requireNonNull(capturedAt);
        this.snapshot = Objects.requireNonNull(snapshot);
    }

    public String getSubmissionId() { return submissionId; }
    public String getEventId() { return eventId; }
