package com.clanhq.verifier.bingo.model;

import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import java.time.Instant;
import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Optional;

public final class BingoManifest
{
    private final String eventId;
    private final String name;
    private final Instant startsAt;
    private final Instant endsAt;
    private final List<BingoItem> items;
    private final Map<Integer, BingoItem> itemsById;
    private final BingoCharacterCheckStatus characterCheck;
    private final String serverName;
    private final String siteUrl;
    private final boolean joined;
    private final String teamName;
    private final String eventPassword;
    private final String challengePassword;

    public BingoManifest(String eventId, String name, Instant startsAt,
        Instant endsAt, List<BingoItem> items)
    {
        this(eventId, name, startsAt, endsAt, items,
            BingoCharacterCheckStatus.empty(), "ClanHQ", null, false, null);
    }

    public BingoManifest(String eventId, String name, Instant startsAt,
        Instant endsAt, List<BingoItem> items,
        BingoCharacterCheckStatus characterCheck)
    {
        this(eventId, name, startsAt, endsAt, items, characterCheck, "ClanHQ");
    }

    public BingoManifest(String eventId, String name, Instant startsAt,
        Instant endsAt, List<BingoItem> items,
        BingoCharacterCheckStatus characterCheck, String serverName)
    {
        this(eventId, name, startsAt, endsAt, items, characterCheck,
            serverName, null, false, null);
    }

    public BingoManifest(String eventId, String name, Instant startsAt,
        Instant endsAt, List<BingoItem> items,
        BingoCharacterCheckStatus characterCheck, String serverName,
        boolean joined, String teamName)
    {
        this(eventId, name, startsAt, endsAt, items, characterCheck,
            serverName, null, joined, teamName);
    }

    public BingoManifest(String eventId, String name, Instant startsAt,
        Instant endsAt, List<BingoItem> items,
        BingoCharacterCheckStatus characterCheck, String serverName,
        String siteUrl,
        boolean joined, String teamName)
    {
        this(eventId, name, startsAt, endsAt, items, characterCheck,
            serverName, siteUrl, joined, teamName, null, null);
    }

    public BingoManifest(String eventId, String name, Instant startsAt,
        Instant endsAt, List<BingoItem> items,
        BingoCharacterCheckStatus characterCheck, String serverName,
        String siteUrl,
        boolean joined, String teamName,
        String eventPassword, String challengePassword)
    {
        this.eventId = eventId;
        this.name = name;
        this.startsAt = startsAt;
        this.endsAt = endsAt;
        this.items = Collections.unmodifiableList(new ArrayList<>(items));
        this.characterCheck = characterCheck;
        this.serverName = serverName == null || serverName.trim().isEmpty()
            ? "ClanHQ" : serverName.trim();
        this.siteUrl = siteUrl == null || siteUrl.trim().isEmpty()
            ? null : siteUrl.trim();
        this.joined = joined;
        this.teamName = teamName == null || teamName.trim().isEmpty()
            ? null : teamName.trim();
        this.eventPassword = eventPassword == null || eventPassword.trim().isEmpty()
            ? null : eventPassword.trim();
        this.challengePassword = challengePassword == null
            || challengePassword.trim().isEmpty()
            ? null : challengePassword.trim();
        Map<Integer, BingoItem> indexed = new LinkedHashMap<>();
        for (BingoItem item : items)
        {
            indexed.put(item.getItemId(), item);
        }
        this.itemsById = Collections.unmodifiableMap(indexed);
    }

    public static BingoManifest fromJson(String json)
    {
        JsonObject root = new JsonParser().parse(json).getAsJsonObject();
        if (integer(root, "schema_version") != 1)
        {
            throw new IllegalArgumentException("Unsupported Bingo manifest");
        }
        JsonArray rawItems = root.getAsJsonArray("items");
        if (rawItems == null || rawItems.size() == 0)
        {
            throw new IllegalArgumentException("Bingo board has no items");
        }
        List<BingoItem> items = new ArrayList<>();
        for (JsonElement element : rawItems)
        {
            JsonObject item = element.getAsJsonObject();
            items.add(new BingoItem(
                integer(item, "item_id"),
                text(item, "name"),
                integer(item, "minimum_quantity"),
                integer(item, "points")));
        }
        BingoCharacterCheckStatus characterCheck =
            BingoCharacterCheckStatus.empty();
        if (root.has("character_check")
            && root.get("character_check").isJsonObject())
        {
            JsonObject check = root.getAsJsonObject("character_check");
            characterCheck = new BingoCharacterCheckStatus(
                optionalText(check, "status", "NOT_SUBMITTED"),
                optionalText(check, "next_phase", "BASELINE"),
                optionalInteger(check, "checkpoint_count", 0),
                optionalNullableText(check, "baseline_captured_at"),
                optionalNullableText(check, "final_captured_at"));
        }
        boolean joined = false;
        String teamName = null;
        if (root.has("participation")
            && root.get("participation").isJsonObject())
        {
            JsonObject participation = root.getAsJsonObject("participation");
            joined = participation.has("joined")
                && participation.get("joined").isJsonPrimitive()
                && participation.get("joined").getAsBoolean();
            teamName = optionalNullableText(participation, "team");
        }
        return new BingoManifest(
            text(root, "event_id"),
            text(root, "name"),
            Instant.parse(text(root, "starts_at")),
            Instant.parse(text(root, "ends_at")),
            items,
            characterCheck,
            root.has("server_name") ? root.get("server_name").getAsString()
                : "ClanHQ",
            optionalNullableText(root, "site_url"),
            joined,
            teamName,
            optionalNullableText(root, "event_password"),
            optionalNullableText(root, "challenge_password"));
    }

    private static String text(JsonObject value, String key)
    {
        if (!value.has(key) || !value.get(key).isJsonPrimitive())
        {
            throw new IllegalArgumentException("Missing Bingo " + key);
        }
        String result = value.get(key).getAsString().trim();
        if (result.isEmpty())
        {
            throw new IllegalArgumentException("Missing Bingo " + key);
        }
        return result;
    }

    private static int integer(JsonObject value, String key)
    {
        if (!value.has(key) || !value.get(key).isJsonPrimitive())
        {
            throw new IllegalArgumentException("Missing Bingo " + key);
        }
        return value.get(key).getAsInt();
    }

    private static String optionalText(JsonObject value, String key,
        String fallback)
    {
        String result = optionalNullableText(value, key);
        return result == null ? fallback : result;
    }

    private static String optionalNullableText(JsonObject value, String key)
    {
        if (!value.has(key) || value.get(key).isJsonNull()
            || !value.get(key).isJsonPrimitive())
        {
            return null;
        }
        String result = value.get(key).getAsString().trim();
        return result.isEmpty() ? null : result;
    }

    private static int optionalInteger(JsonObject value, String key,
        int fallback)
    {
        return value.has(key) && value.get(key).isJsonPrimitive()
            ? value.get(key).getAsInt() : fallback;
    }

    public String getEventId()
    {
        return eventId;
    }

    public String getName()
    {
        return name;
    }

    public Instant getStartsAt()
    {
        return startsAt;
    }

    public Instant getEndsAt()
    {
        return endsAt;
    }

    public List<BingoItem> getItems()
    {
        return items;
    }

    public BingoCharacterCheckStatus getCharacterCheck()
    {
        return characterCheck;
    }

    public String getServerName()
    {
        return serverName;
    }

    public String getSiteUrl()
    {
        return siteUrl;
    }

    public boolean isJoined()
    {
        return joined;
    }

    public String getTeamName()
    {
        return teamName;
    }

    /**
     * Clan-wide Bingo event password set by the event organizer, if any.
     * When present, this overrides each player's local overlay config
     * value; see {@link com.clanhq.verifier.bingo.BingoPasswordResolver}.
     */
    public String getEventPassword()
    {
        return eventPassword;
    }

    /**
     * Clan-wide Bingo challenge password set by the event organizer, if
     * any. Same override semantics as {@link #getEventPassword()}.
     */
    public String getChallengePassword()
    {
        return challengePassword;
    }

    public Optional<BingoItem> findItem(int itemId)
    {
        return Optional.ofNullable(itemsById.get(itemId));
    }
}

package com.clanhq.verifier.bingo.service;

import com.clanhq.verifier.bingo.model.BingoDrop;
import java.awt.AlphaComposite;
import java.awt.Color;
import java.awt.Font;
import java.awt.Graphics2D;
import java.awt.Image;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.time.ZoneOffset;
import java.time.format.DateTimeFormatter;
import java.util.Iterator;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.ScheduledExecutorService;
import javax.imageio.IIOImage;
import javax.imageio.ImageIO;
import javax.imageio.ImageWriteParam;
import javax.imageio.ImageWriter;
import javax.imageio.stream.ImageOutputStream;
import net.runelite.client.ui.DrawManager;

public final class BingoScreenshotService
{
    private static final int MAXIMUM_WIDTH = 1280;
    private static final int WATERMARK_HEIGHT = 112;
    private static final float JPEG_QUALITY = 0.82f;
    private static final DateTimeFormatter TIMESTAMP_FORMAT =
        DateTimeFormatter.ofPattern("uuuu-MM-dd HH:mm:ss 'UTC'")
            .withZone(ZoneOffset.UTC);
    private final DrawManager drawManager;
    private final ScheduledExecutorService executor;

    public BingoScreenshotService(
        DrawManager drawManager,
        ScheduledExecutorService executor)
    {
        this.drawManager = drawManager;
        this.executor = executor;
    }

    public CompletableFuture<byte[]> capture(
        BingoDrop drop,
        String eventName)
    {
        CompletableFuture<byte[]> future = new CompletableFuture<>();
        drawManager.requestNextFrameListener(image -> executor.execute(() ->
        {
            try
            {
                future.complete(render(image, drop, eventName));
            }
            catch (RuntimeException | IOException exception)
            {
                future.completeExceptionally(exception);
            }
        }));
        return future;
    }

    byte[] render(Image image, BingoDrop drop, String eventName)
        throws IOException
    {
        int sourceWidth = image.getWidth(null);
        int sourceHeight = image.getHeight(null);
        if (sourceWidth <= 0 || sourceHeight <= 0)
        {
            throw new IOException("RuneLite screenshot was unavailable");
        }
        double scale = Math.min(1.0, (double) MAXIMUM_WIDTH / sourceWidth);
        int width = Math.max(1, (int) Math.round(sourceWidth * scale));
        int height = Math.max(1, (int) Math.round(sourceHeight * scale));
        BufferedImage screenshot = new BufferedImage(
            width,
            height,
            BufferedImage.TYPE_INT_RGB);
        Graphics2D graphics = screenshot.createGraphics();
        graphics.setRenderingHint(
            RenderingHints.KEY_INTERPOLATION,
            RenderingHints.VALUE_INTERPOLATION_BILINEAR);
        graphics.drawImage(image, 0, 0, width, height, null);
        addWatermark(graphics, width, height, drop, eventName);
        graphics.dispose();
        return encodeJpeg(screenshot);
    }

    private static void addWatermark(
        Graphics2D graphics,
        int width,
        int height,
        BingoDrop drop,
        String eventName)
    {
        int top = Math.max(0, height - WATERMARK_HEIGHT);
        graphics.setComposite(AlphaComposite.SrcOver.derive(0.78f));
        graphics.setColor(Color.BLACK);
        graphics.fillRect(0, top, width, WATERMARK_HEIGHT);
        graphics.setComposite(AlphaComposite.SrcOver);
        graphics.setFont(new Font(Font.SANS_SERIF, Font.BOLD, 17));
        graphics.setColor(new Color(212, 175, 55));
        graphics.drawString("ClanHQ • " + eventName, 16, top + 24);
        graphics.setFont(new Font(Font.SANS_SERIF, Font.PLAIN, 15));
        graphics.setColor(Color.WHITE);
        graphics.drawString("RSN: " + drop.getRsn(), 16, top + 48);
        graphics.drawString(
            "Drop: " + drop.getItem().getName() + " × " + drop.getQuantity(),
            16,
            top + 70);
        graphics.drawString(
            "UTC: " + TIMESTAMP_FORMAT.format(drop.getOccurredAt()),
            16,
            top + 92);
        graphics.drawString(
            "Event: " + drop.getEventId(),
            Math.max(16, width - 260),
            top + 92);
    }

    private static byte[] encodeJpeg(BufferedImage image) throws IOException
    {
        Iterator<ImageWriter> writers = ImageIO.getImageWritersByFormatName("jpg");
        if (!writers.hasNext())
        {
            throw new IOException("JPEG encoder is unavailable");
        }
        ImageWriter writer = writers.next();
        ImageWriteParam parameters = writer.getDefaultWriteParam();
        parameters.setCompressionMode(ImageWriteParam.MODE_EXPLICIT);
        parameters.setCompressionQuality(JPEG_QUALITY);
        try (ByteArrayOutputStream output = new ByteArrayOutputStream();
             ImageOutputStream imageOutput = ImageIO.createImageOutputStream(output))
        {
            writer.setOutput(imageOutput);
            writer.write(null, new IIOImage(image, null, null), parameters);
            imageOutput.flush();
            return output.toByteArray();
        }
        finally
        {
            writer.dispose();
        }
    }
}

package com.clanhq.verifier.bingo.transport;

import com.clanhq.verifier.ClanHQVerifierConfig;
import com.clanhq.verifier.bingo.model.BingoDrop;
import com.clanhq.verifier.bingo.model.BingoCharacterSubmission;
import com.clanhq.verifier.bingo.model.BingoManifest;
import com.clanhq.verifier.service.ApiDestinationService;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import java.io.IOException;
import java.util.concurrent.CompletableFuture;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.MediaType;
import okhttp3.MultipartBody;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;
import okhttp3.Response;

public final class BingoApiClient
{
    private static final MediaType JSON =
        MediaType.parse("application/json; charset=utf-8");
    private static final MediaType JPEG = MediaType.parse("image/jpeg");
    private final OkHttpClient httpClient;
    private final ClanHQVerifierConfig config;
    private final ApiDestinationService destinationService;

    public BingoApiClient(OkHttpClient httpClient,
        ClanHQVerifierConfig config,
        ApiDestinationService destinationService)
    {
        this.httpClient = httpClient;
        this.config = config;
        this.destinationService = destinationService;
    }

    public CompletableFuture<BingoManifestResult> fetchManifest()
    {
        CompletableFuture<BingoManifestResult> future =
            new CompletableFuture<>();
        String baseUrl = configuredBaseUrl();
        if (baseUrl == null)
        {
            future.complete(new BingoManifestResult(null,
                "Configure the ClanHQ API URL and installation token first."));
            return future;
        }
        Request request = request(baseUrl + "/api/v1/bingo/manifest")
            .get()
            .build();
        httpClient.newCall(request).enqueue(new Callback()
        {
            @Override
            public void onFailure(Call call, IOException exception)
            {
                future.complete(new BingoManifestResult(null,
                    "ClanHQ could not be reached."));
            }

            @Override
            public void onResponse(Call call, Response response)
                throws IOException
            {
                try (Response closeable = response)
                {
                    String body = response.body() == null
                        ? "" : response.body().string();
                    if (!response.isSuccessful())
                    {
                        future.complete(new BingoManifestResult(null,
                            responseMessage(body, response.code()),
                            responseSiteUrl(body)));
                        return;
                    }
                    future.complete(new BingoManifestResult(
                        BingoManifest.fromJson(body),
                        "Bingo board loaded."));
                }
                catch (IOException | RuntimeException exception)
                {
                    future.complete(new BingoManifestResult(null,
                        "ClanHQ returned an invalid Bingo board."));
                }
            }
        });
        return future;
    }

    public CompletableFuture<BingoTransportResult> submit(BingoDrop drop)
    {
        return submit(drop, null);
    }

    public CompletableFuture<BingoTransportResult> submit(
        BingoDrop drop,
        byte[] screenshot)
    {
        CompletableFuture<BingoTransportResult> future =
            new CompletableFuture<>();
        String baseUrl = configuredBaseUrl();
        if (baseUrl == null)
        {
            future.complete(new BingoTransportResult(false,
                "Configure the ClanHQ API URL and installation token first."));
            return future;
        }
        RequestBody body = screenshot == null
            ? RequestBody.create(JSON, payload(drop).toString())
            : new MultipartBody.Builder()
                .setType(MultipartBody.FORM)
                .addFormDataPart(
                    "payload",
                    null,
                    RequestBody.create(JSON, payload(drop).toString()))
                .addFormDataPart(
                    "screenshot",
                    "bingo-drop.jpg",
                    RequestBody.create(JPEG, screenshot))
                .build();
        Request request = request(baseUrl + "/api/v1/bingo/drops")
            .post(body)
            .build();
        httpClient.newCall(request).enqueue(new Callback()
        {
            @Override
            public void onFailure(Call call, IOException exception)
            {
                future.complete(new BingoTransportResult(false,
                    "ClanHQ could not be reached."));
            }

            @Override
            public void onResponse(Call call, Response response)
                throws IOException
            {
                try (Response closeable = response)
                {
                    String body = response.body() == null
                        ? "" : response.body().string();
                    future.complete(new BingoTransportResult(
                        response.isSuccessful(),
                        responseMessage(body, response.code())));
                }
                catch (IOException | RuntimeException exception)
                {
                    future.complete(new BingoTransportResult(false,
                        "ClanHQ returned an invalid response."));
                }
            }
        });
        return future;
    }

    public CompletableFuture<BingoTransportResult> submitCharacter(
        BingoCharacterSubmission submission)
    {
        CompletableFuture<BingoTransportResult> future =
            new CompletableFuture<>();
        String baseUrl = configuredBaseUrl();
        if (baseUrl == null)
        {
            future.complete(new BingoTransportResult(false,
                "Configure the ClanHQ API URL and installation token first."));
            return future;
        }
        Request request = request(baseUrl + "/api/v1/bingo/characters")
            .post(RequestBody.create(JSON,
                BingoCharacterPayloadFactory.create(submission).toString()))
            .build();
        httpClient.newCall(request).enqueue(new Callback()
        {
            @Override
            public void onFailure(Call call, IOException exception)
            {
                future.complete(new BingoTransportResult(false,
                    "ClanHQ could not be reached."));
            }

            @Override
            public void onResponse(Call call, Response response)
                throws IOException
            {
                try (Response closeable = response)
                {
                    String body = response.body() == null
                        ? "" : response.body().string();
                    future.complete(new BingoTransportResult(
                        response.isSuccessful(),
                        responseMessage(body, response.code())));
                }
                catch (IOException | RuntimeException exception)
                {
                    future.complete(new BingoTransportResult(false,
                        "ClanHQ returned an invalid response."));
                }
            }
        });
        return future;
    }

    private Request.Builder request(String url)
    {
        return new Request.Builder()
            .url(url)
            .header("Authorization", "Bearer "
                + config.installationToken().trim());
    }

    private String configuredBaseUrl()
    {
        String baseUrl = destinationService.normalize(config.apiBaseUrl());
        String token = config.installationToken() == null
            ? "" : config.installationToken().trim();
        return baseUrl == null || token.isEmpty()
            ? null : baseUrl;
    }

    static JsonObject payload(BingoDrop drop)
    {
        JsonObject value = new JsonObject();
        value.addProperty("schema_version", 1);
        value.addProperty("submission_id", drop.getSubmissionId());
        value.addProperty("event_id", drop.getEventId());
        value.addProperty("rsn", drop.getRsn());
        value.addProperty("item_id", drop.getItem().getItemId());
        value.addProperty("item_name", drop.getItem().getName());
        value.addProperty("quantity", drop.getQuantity());
        value.addProperty("source_type", drop.getSourceType());
        value.addProperty("source_name", drop.getSourceName());
        value.addProperty("occurred_at", drop.getOccurredAt().toString());
        return value;
    }

    private static String responseMessage(String body, int status)
    {
        try
        {
            JsonObject parsed = new JsonParser().parse(body).getAsJsonObject();
            if (parsed.has("message"))
            {
                return parsed.get("message").getAsString();
            }
        }
        catch (RuntimeException ignored)
        {
            // Fall through to a stable HTTP error.
        }
        return "ClanHQ returned HTTP " + status;
    }

    private static String responseSiteUrl(String body)
    {
        try
        {
            JsonObject parsed = new JsonParser().parse(body).getAsJsonObject();
            if (parsed.has("site_url") && parsed.get("site_url").isJsonPrimitive())
            {
                String value = parsed.get("site_url").getAsString().trim();
                return value.isEmpty() ? null : value;
            }
        }
        catch (RuntimeException ignored)
        {
            // The response may be a non-JSON network error.
        }
        return null;
    }
}

package com.clanhq.verifier.bingo.transport;

import com.clanhq.verifier.bingo.model.BingoCharacterSubmission;
import com.clanhq.verifier.model.EvidenceSource;
import com.clanhq.verifier.model.ObservedItem;
import com.google.gson.JsonArray;
import com.google.gson.JsonNull;
import com.google.gson.JsonObject;
import java.util.Map;

public final class BingoCharacterPayloadFactory
{
    private BingoCharacterPayloadFactory()
    {
    }

    public static JsonObject create(BingoCharacterSubmission submission)
    {
        JsonObject payload = new JsonObject();
        payload.addProperty("schema_version", 1);
        payload.addProperty("submission_id", submission.getSubmissionId());
        payload.addProperty("event_id", submission.getEventId());
        payload.addProperty("rsn", submission.getSnapshot().getRsn());
        payload.addProperty("captured_at", submission.getCapturedAt().toString());

        JsonObject evidence = new JsonObject();
        evidence.addProperty("total_level",
            submission.getSnapshot().getTotalLevel());
        evidence.addProperty("combat_level",
            submission.getSnapshot().getCombatLevel());
        JsonObject metrics = new JsonObject();
        submission.getSnapshot().getAccountMetrics().forEach(
            metrics::addProperty);
        evidence.add("metrics", metrics);
        payload.add("evidence", evidence);

        payload.add("bank", items(submission, EvidenceSource.BANK));
        payload.add("inventory", items(submission, EvidenceSource.INVENTORY));
        payload.add("equipment", items(submission, EvidenceSource.EQUIPMENT));
        return payload;
    }

    private static JsonArray items(BingoCharacterSubmission submission,
        EvidenceSource source)
    {
        JsonArray values = new JsonArray();
        for (ObservedItem item : submission.getSnapshot().getItems())
        {
            if (item.getSource() != source)
            {
                continue;
            }
            JsonObject value = new JsonObject();
            value.addProperty("item_id", item.getItemId());
            value.addProperty("name", item.getName());
            value.addProperty("quantity", item.getQuantity());
            if (!item.getEquipment().isEmpty())
            {
                JsonObject equipment = new JsonObject();
                for (Map.Entry<String, Object> entry
                    : item.getEquipment().entrySet())
                {
                    Object metadata = entry.getValue();
                    if (metadata == null)
                    {
                        equipment.add(entry.getKey(), JsonNull.INSTANCE);
                    }
                    else if (metadata instanceof Number)
                    {
                        equipment.addProperty(entry.getKey(), (Number) metadata);
                    }
                    else if (metadata instanceof Boolean)
                    {
                        equipment.addProperty(entry.getKey(), (Boolean) metadata);
                    }
                    else
                    {
                        equipment.addProperty(entry.getKey(),
                            String.valueOf(metadata));
                    }
                }
                value.add("equipment", equipment);
            }
            values.add(value);
        }
        return values;
    }
}

