package com.clanhq.verifier.character;

import com.clanhq.verifier.ClanHQVerifierConfig;
import com.clanhq.verifier.bingo.model.BingoCharacterSubmission;
import com.clanhq.verifier.bingo.transport.BingoCharacterPayloadFactory;
import com.clanhq.verifier.service.ApiDestinationService;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import java.io.IOException;
import java.util.concurrent.CompletableFuture;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.MediaType;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;
import okhttp3.Response;

public final class CharacterSyncApiClient
{
    private static final MediaType JSON =
        MediaType.parse("application/json; charset=utf-8");
    private final OkHttpClient httpClient;
    private final ClanHQVerifierConfig config;
    private final ApiDestinationService destinationService;

    public CharacterSyncApiClient(OkHttpClient httpClient,
        ClanHQVerifierConfig config, ApiDestinationService destinationService)
    {
        this.httpClient = httpClient;
        this.config = config;
        this.destinationService = destinationService;
    }

    public CompletableFuture<CharacterSyncResult> submit(
        BingoCharacterSubmission submission)
    {
        CompletableFuture<CharacterSyncResult> future = new CompletableFuture<>();
        String baseUrl = destinationService.normalize(config.apiBaseUrl());
        String token = normalized(config.installationToken());
        if (baseUrl == null || token.isEmpty())
        {
            future.complete(new CharacterSyncResult(false,
                "Pair this RuneLite installation first."));
            return future;
        }
        Request request = new Request.Builder()
            .url(baseUrl + "/api/v1/characters")
            .header("Authorization", "Bearer " + token)
            .post(RequestBody.create(JSON,
                BingoCharacterPayloadFactory.create(submission).toString()))
            .build();
        httpClient.newCall(request).enqueue(new Callback()
        {
            @Override
            public void onFailure(Call call, IOException exception)
            {
                future.complete(new CharacterSyncResult(false,
                    "ClanHQ could not be reached."));
            }

            @Override
            public void onResponse(Call call, Response response)
                throws IOException
            {
                try (Response closeable = response)
                {
                    String body = response.body() == null
                        ? "" : response.body().string();
                    future.complete(new CharacterSyncResult(
                        response.isSuccessful(),
                        responseMessage(body, response.code())));
                }
                catch (IOException | RuntimeException exception)
                {
                    future.complete(new CharacterSyncResult(false,
                        "ClanHQ returned an invalid response."));
                }
            }
        });
        return future;
    }

    private static String responseMessage(String body, int status)
    {
        try
        {
            JsonObject value = new JsonParser().parse(body).getAsJsonObject();
            if (value.has("message"))
            {
                return value.get("message").getAsString();
            }
        }
        catch (RuntimeException ignored)
        {
        }
        return "ClanHQ returned HTTP " + status;
    }

    private static String normalized(String value)
    {
        return value == null ? "" : value.trim();
    }
}

package com.clanhq.verifier.character;

import com.clanhq.verifier.bingo.model.BingoCharacterSubmission;
import com.clanhq.verifier.feature.ClanHQFeature;
import com.clanhq.verifier.service.LocalPlayerSnapshotService;
import com.clanhq.verifier.service.SubmissionConsentService;
import javax.swing.JComponent;
import javax.swing.SwingUtilities;
import net.runelite.client.callback.ClientThread;

public final class CharacterSyncFeature implements ClanHQFeature
{
    private final CharacterSyncApiClient apiClient;
    private final LocalPlayerSnapshotService snapshotService;
    private final ClientThread clientThread;
    private final SubmissionConsentService consentService;
    private final CharacterSyncPanel panel;
    private volatile boolean running;
    private volatile BingoCharacterSubmission pending;

    public CharacterSyncFeature(CharacterSyncApiClient apiClient,
        LocalPlayerSnapshotService snapshotService, ClientThread clientThread,
        SubmissionConsentService consentService)
    {
        this.apiClient = apiClient;
        this.snapshotService = snapshotService;
        this.clientThread = clientThread;
        this.consentService = consentService;
        this.panel = new CharacterSyncPanel(this::submit);
    }

    public String getId() { return "character"; }
    public String getDisplayName() { return "Character"; }
    public String getNavigationIconResource()
    {
        return "/com/clanhq/verifier/icons/character.png";
    }
    public String getDescription() { return "Synchronize complete character item data."; }
    public JComponent getPanel() { return panel; }
    public void addBelow(JComponent component) { panel.addBelow(component); }
    public void startUp() { running = true; }
    public void shutDown() { running = false; pending = null; }

    public void submit()
    {
        if (!running) { return; }
        if (!consentService.confirm(panel, "character synchronization"))
        {
            panel.showCancelled();
            return;
        }
        panel.setSubmitting();
        if (pending != null)
        {
            deliver(pending);
            return;
        }
        clientThread.invokeLater(() ->
        {
            try
            {
                pending = new BingoCharacterSubmission(
                    "CHARACTER-SYNC",
                    snapshotService.captureCompleteItemsEvidence());
                deliver(pending);
            }
            catch (RuntimeException exception)
            {
                SwingUtilities.invokeLater(() -> panel.showResult(
                    false, exception.getMessage()));
            }
        });
    }

    private void deliver(BingoCharacterSubmission submission)
    {
        apiClient.submit(submission).thenAccept(result ->
            SwingUtilities.invokeLater(() ->
            {
                if (!running) { return; }
                if (result.isSuccessful()) { pending = null; }
                if (result.isSuccessful())
                {
                    panel.showSynced();
                }
                else
                {
                    panel.showResult(false, result.getMessage());
                }
            }));
    }
}

package com.clanhq.verifier.character;

import java.awt.BorderLayout;
import java.awt.Dimension;
import javax.swing.BorderFactory;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.JButton;
import javax.swing.JComponent;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JSeparator;
import net.runelite.client.ui.ColorScheme;

final class CharacterSyncPanel extends JPanel
{
    private final JButton submit = new JButton("Sync Character Data");
    private final JLabel status = new JLabel();

    CharacterSyncPanel(Runnable submitAction)
    {
        setLayout(new BorderLayout());
        setBorder(BorderFactory.createEmptyBorder(10, 10, 10, 10));
        setBackground(ColorScheme.DARK_GRAY_COLOR);
        JPanel content = new JPanel();
        content.setLayout(new BoxLayout(content, BoxLayout.Y_AXIS));
        content.setBackground(ColorScheme.DARK_GRAY_COLOR);
        content.add(new JLabel("Character Sync"));
        content.add(Box.createRigidArea(new Dimension(0, 8)));
        content.add(new JLabel("<html>Send your complete bank, inventory, and "
            + "equipped item IDs and quantities to ClanHQ for server-side "
            + "verification. You will confirm the destination before each "
            + "submission.</html>"));
        content.add(Box.createRigidArea(new Dimension(0, 10)));
        submit.addActionListener(event -> submitAction.run());
        content.add(submit);
        content.add(Box.createRigidArea(new Dimension(0, 8)));
        content.add(status);
        add(content, BorderLayout.NORTH);
        showResult(true, "Open your bank before synchronizing.");
    }

    void setSubmitting()
    {
        submit.setEnabled(false);
        status.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
        showStatus("Syncing...");
    }

    void showResult(boolean successful, String message)
    {
        submit.setEnabled(true);
        showStatus((successful ? "" : "Sync failed. ") + message);
        status.setForeground(successful
            ? ColorScheme.LIGHT_GRAY_COLOR : new java.awt.Color(0xD95C5C));
    }

    void showSynced()
    {
        submit.setEnabled(true);
        status.setForeground(new java.awt.Color(0x70C090));
        status.setText("✓ Synced");
    }

    void showCancelled()
    {
        submit.setEnabled(true);
        status.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
        showStatus("Sync cancelled.");
    }

    private void showStatus(String message)
    {
        status.setText("<html><body style='width: 190px'>"
            + message.replace("&", "&amp;").replace("<", "&lt;")
                .replace(">", "&gt;")
            + "</body></html>");
    }
    void addBelow(JComponent component)
    {
        JPanel section = new JPanel();
        section.setLayout(new BoxLayout(section, BoxLayout.Y_AXIS));
        section.setBackground(ColorScheme.DARK_GRAY_COLOR);
        JSeparator divider = new JSeparator();
        divider.setAlignmentX(LEFT_ALIGNMENT);
        section.add(divider);
        section.add(Box.createRigidArea(new Dimension(0, 6)));
        component.setAlignmentX(LEFT_ALIGNMENT);
        section.add(component);
        add(section, BorderLayout.CENTER);
        revalidate();
        repaint();
    }
}

