import java.util.Locale;
import net.runelite.api.Skill;
import net.runelite.api.SpriteID;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.SkillIconManager;
import net.runelite.client.game.SpriteManager;
import net.runelite.client.ui.overlay.infobox.InfoBox;
import net.runelite.client.ui.overlay.infobox.InfoBoxManager;

final class DailyTaskIconFactory
{
    private static final int FALLBACK_ICON_SIZE = 15;

    private DailyTaskIconFactory()
    {
    }

    static BufferedImage get(DailyTaskSummary task, ItemManager itemManager,
        SkillIconManager skillIconManager, SpriteManager spriteManager)
    {
        String category = task.getCategory();
        if (spriteManager != null && "ACTIVITIES".equalsIgnoreCase(category))
        {
            BufferedImage image = spriteManager.getSprite(
                SpriteID.QUESTS_PAGE_ICON_RED_MINIGAMES, 0);
            if (image != null)
            {
                return image;
            }
        }
        if (spriteManager != null && "PVM".equalsIgnoreCase(category))
        {
            BufferedImage image = spriteManager.getSprite(SpriteID.TAB_COMBAT, 0);
            if (image != null)
            {
                return image;
            }
        }
        if (spriteManager != null && "DROP".equalsIgnoreCase(category))
        {
            BufferedImage image = spriteManager.getSprite(SpriteID.TAB_INVENTORY, 0);
            if (image != null)
            {
                return image;
            }
        }
        if (skillIconManager != null && "SKILLING".equalsIgnoreCase(category))
        {
            Skill skill = findSkill(task.getName());
            if (skill != null)
            {
                BufferedImage image = skillIconManager.getSkillImage(skill);
                if (image != null)
                {
                    return image;
                }
            }
        }
        Integer itemId = task.getVerificationItemId();
        if (itemId == null && task.getVerificationItemIds() != null
            && !task.getVerificationItemIds().isEmpty())
        {
            itemId = task.getVerificationItemIds().get(0);
        }
        if (itemManager != null && itemId != null)
        {
            BufferedImage image = itemManager.getImage(itemId);
            if (image != null)
            {
                return image;
            }
        }
        return fallbackIcon(category);
    }

    static BufferedImage getInfoBoxIcon(DailyTaskSummary task,
        ItemManager itemManager, SkillIconManager skillIconManager)
    {
        String category = task.getCategory();
        if (skillIconManager != null && "SKILLING".equalsIgnoreCase(category))
        {
            Skill skill = findSkill(task.getName());
            if (skill != null)
            {
                BufferedImage image = skillIconManager.getSkillImage(skill);
                if (image != null)
                {
                    return image;
                }
            }
        }

        Integer itemId = task.getVerificationItemId();
        if (itemId == null && task.getVerificationItemIds() != null
            && !task.getVerificationItemIds().isEmpty())
        {
            itemId = task.getVerificationItemIds().get(0);
        }
        if (itemManager != null && itemId != null)
        {
            BufferedImage image = itemManager.getImage(itemId);
            if (image != null)
            {
                return image;
            }
        }
        return fallbackIcon(category);
    }

    static void loadInfoBoxIcon(DailyTaskSummary task, InfoBox infoBox,
        InfoBoxManager infoBoxManager, SpriteManager spriteManager)
    {
        if (spriteManager == null || infoBoxManager == null)
        {
            return;
        }

        String category = task.getCategory();
        int spriteId;
        if ("ACTIVITIES".equalsIgnoreCase(category))
        {
            spriteId = SpriteID.QUESTS_PAGE_ICON_RED_MINIGAMES;
        }
        else if ("PVM".equalsIgnoreCase(category))
        {
            spriteId = SpriteID.TAB_COMBAT;
        }
        else if ("DROP".equalsIgnoreCase(category))
        {
            spriteId = SpriteID.TAB_INVENTORY;
        }
        else
        {
            return;
        }

        spriteManager.getSpriteAsync(spriteId, 0, image ->
        {
            infoBox.setImage(image);
            infoBoxManager.updateInfoBoxImage(infoBox);
        });
    }

    private static BufferedImage fallbackIcon(String category)
    {
        BufferedImage image = new BufferedImage(FALLBACK_ICON_SIZE,
            FALLBACK_ICON_SIZE, BufferedImage.TYPE_INT_ARGB);
        Graphics2D graphics = image.createGraphics();
        graphics.setColor("PVM".equalsIgnoreCase(category)
            ? new Color(220, 92, 92) : "ACTIVITIES".equalsIgnoreCase(category)
                ? new Color(230, 180, 70) : new Color(108, 190, 102));
        graphics.fillOval(3, 3, 9, 9);
        graphics.dispose();
        return image;
    }

    private static Skill findSkill(String taskName)
    {
        String normalized = taskName == null ? ""
            : taskName.toLowerCase(Locale.ROOT);
        for (Skill skill : Skill.values())
        {
            if (normalized.contains(skill.getName().toLowerCase(Locale.ROOT)))
            {
                return skill;
            }
        }
        return null;
    }
}

package com.clanhq.verifier.daily;

import com.clanhq.verifier.daily.model.DailyTaskSummary;
import java.awt.Color;
import java.text.NumberFormat;
import java.util.Locale;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.SkillIconManager;
import net.runelite.client.game.SpriteManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.ui.overlay.infobox.InfoBox;
import net.runelite.client.ui.overlay.infobox.InfoBoxManager;

final class DailyTaskInfoBox extends InfoBox
{
    private static final NumberFormat NUMBERS =
        NumberFormat.getIntegerInstance(Locale.US);

    private DailyTaskSummary task;
    private int progress;

    DailyTaskInfoBox(DailyTaskSummary task, int progress, Plugin plugin,
        ItemManager itemManager, SkillIconManager skillIconManager,
        SpriteManager spriteManager, InfoBoxManager infoBoxManager)
    {
        super(DailyTaskIconFactory.getInfoBoxIcon(task, itemManager,
            skillIconManager), plugin);
        update(task, progress);
        DailyTaskIconFactory.loadInfoBoxIcon(task, this, infoBoxManager,
            spriteManager);
    }

    void update(DailyTaskSummary task, int progress)
    {
        this.task = task;
        this.progress = progress;
        setTooltip(tooltip(task, progress));
    }

    @Override
    public String getText()
    {
        return isComplete() ? "\u2713" : compact(progress);
    }

    @Override
    public Color getTextColor()
    {
        return isComplete() ? new Color(67, 190, 117) : Color.WHITE;
    }

    private boolean isComplete()
    {
        return task.isCompleted() || progress >= task.getTarget();
    }

    private static String tooltip(DailyTaskSummary task, int progress)
    {
        String name = task.getName() == null ? "" : task.getName();
        String category = titleCase(task.getCategory());
        String tier = task.isDailyDrop() && task.getTier() != null
            && !task.getTier().trim().isEmpty() ? titleCase(task.getTier()) : "";
        String status = task.isCompleted() || progress >= task.getTarget()
            ? "Complete" : NUMBERS.format(progress) + " / "
                + NUMBERS.format(task.getTarget());
        String prefix = tier.isEmpty() ? category : tier + " " + category;
        return prefix + " - " + name + " - " + status;
    }

    private static String compact(int value)
    {
        if (value >= 1_000_000)
        {
            return String.format(Locale.US, "%.1fM", value / 1_000_000.0)
                .replace(".0M", "M");
        }
        if (value >= 1_000)
        {
            return String.format(Locale.US, "%.1fK", value / 1_000.0)
                .replace(".0K", "K");
        }
        return NUMBERS.format(value);
    }

    private static String titleCase(String value)
    {
        if (value == null || value.isEmpty())
        {
            return "Task";
        }
        String lower = value.toLowerCase(Locale.ROOT);
        return Character.toUpperCase(lower.charAt(0)) + lower.substring(1);
    }

}

package com.clanhq.verifier.daily;

import com.clanhq.verifier.daily.model.DailyTaskSummary;
import java.util.Locale;
import net.runelite.api.Skill;

/** Resolves a daily skilling task to one RuneLite skill without substring collisions. */
final class DailyTaskSkillMatcher
{
    private DailyTaskSkillMatcher()
    {
    }

    static boolean matches(DailyTaskSummary task, String observedSkillName)
    {
        Skill expected = findTaskSkill(task);
        Skill observed = findBestSkill(observedSkillName);
        return expected != null && expected == observed;
    }

    static Skill findTaskSkill(DailyTaskSummary task)
    {
        if (task == null)
        {
            return null;
        }
        return findBestSkill(task.getName() + " " + task.getDescription());
    }

    private static Skill findBestSkill(String value)
    {
        String normalized = normalize(value);
        Skill best = null;
        int bestLength = -1;
        for (Skill skill : Skill.values())
        {
            String candidate = normalize(skill.getName());
            if (!candidate.isEmpty() && normalized.contains(candidate)
                && candidate.length() > bestLength)
            {
                best = skill;
                bestLength = candidate.length();
            }
        }
        return best;
    }

    private static String normalize(String value)
    {
        return value == null ? ""
            : value.replace('_', ' ').trim().toLowerCase(Locale.ENGLISH);
    }
}

