            ? "DAILY" : snapshot.getContext().getTitle();
        String contextType = snapshot.getContext() == null
            ? "daily" : snapshot.getContext().getType();
        if (isLegacyDailyTaskContext(snapshot))
        {
            contextTitle = "DAILY";
            contextType = "daily";
        }
        refreshButton.setEnabled(true);
        setClaimButtons(true);
        clearTasks();
        updateTitle(contextTitle.isEmpty() ? "DAILY" : contextTitle,
            contextType);
        boolean unsupported = false;
        for (DailyTaskSummary task : snapshot.getTasks())
        {
            TaskCard card = new TaskCard(task.getId(), "Claim Task",
                () -> claimAction.accept(task.getCategory()), task.getCategory(),
                skillIconManager);
            cards.add(card);
            taskCards.add(card);
            if (taskCards.getComponentCount() > 1)
            {
                taskCards.add(Box.createRigidArea(new Dimension(0, 6)),
                    taskCards.getComponentCount() - 1);
            }
            card.showTask(task, snapshot.getCurrencyName(),
                snapshot.getCurrencySymbol());
            card.setEnabled(!task.isCompleted() && task.getProgress() >= task.getTarget());
            if (requiresNewerPlugin(snapshot, task))
            {
                unsupported = true;
            }
        }
        updateSummary();
        resetLabel.setText(resetText(snapshot));
        showStatus(unsupported
            ? "A task requires a newer ClanHQ plugin."
            : (isNormalLoadMessage(message) ? "" : message));
        revalidate();
        repaint();
    }

    /**
     * Update the rendered progress for a task from the local RuneLite event
     * stream. The server snapshot remains authoritative for claim state; this
     * only keeps the panel in step with the live overlay between refreshes.
     */
    void updateLiveProgress(String assignmentId, int progress)
    {
        TaskCard card = cardForAssignment(assignmentId);
        if (card == null)
        {
            return;
        }
        card.updateLiveProgress(progress);
        updateSummary();
        revalidate();
        repaint();
    }

    void showError(String message, boolean paired)
    {
        if (!paired)
        {
            showUnpaired(message);
            return;
        }
        refreshButton.setEnabled(true);
        setClaimButtons(true);
        showStatus(message);
    }

    void setClaiming(String category)
    {
        TaskCard card = cardForCategory(category);
        if (card != null)
        {
            card.setClaiming();
        }
    }

    void setPending(String category)
    {
        TaskCard card = cardForCategory(category);
        if (card != null)
        {
            card.setPending();
        }
        showStatus("Claim saved; syncing with ClanHQ automatically.");
    }

    void restoreClaim(String category)
    {
        TaskCard card = cardForCategory(category);
        if (card != null)
        {
            card.restoreClaim();
        }
    }

    private TaskCard cardForCategory(String category)
    {
        for (TaskCard card : cards)
        {
            if (category != null && card.category.equals(category))
            {
                return card;
            }
        }
        return null;
    }

    private TaskCard cardForAssignment(String assignmentId)
    {
        if (assignmentId == null)
        {
            return null;
        }
        for (TaskCard card : cards)
        {
            if (assignmentId.equals(card.assignmentId))
            {
                return card;
            }
        }
        return null;
    }

    private void clearTasks()
    {
        updateTitle("DAILY", "daily");
        summaryLabel.setText("0 / 0 Complete");
        cards.clear();
        taskCards.removeAll();
        resetLabel.setText("");
    }

    private void updateSummary()
    {
        int completed = 0;
        int claimed = 0;
        int earned = 0;
        for (TaskCard card : cards)
        {
            if (card.isCompleteForSummary())
            {
                completed++;
            }
            if (card.isServerCompleted())
            {
                claimed++;
                earned += Math.max(0, card.getAwarded());
            }
        }
        String summary = completed + " / " + cards.size() + " Complete"
            + (claimed > 0 ? "   •   " + claimed + " Claimed" : "")
            + (earned > 0 ? "<br>" + NUMBERS.format(earned) + " 💧 earned" : "");
        summaryLabel.setText("<html><body style='width: " + CONTENT_WIDTH
            + "px'>" + summary + "</body></html>");
    }

    private void updateTitle()
    {
        updateTitle("DAILY", "daily");
    }

    /**
     * Legacy Daily Tasks use WOM/claim-time verification even when their
     * generic metadata names an observation type that this client does not
     * implement. Only explicitly generic task contexts are gated by the
     * live-observation capability list.
     */
    private static boolean requiresNewerPlugin(DailyTasksSnapshot snapshot,
        DailyTaskSummary task)
    {
        if (isLegacyDailyTaskContext(snapshot))
        {
            return false;
        }
        VerificationType type = task.getVerificationType();
        return type != VerificationType.SKILL_XP
            && type != VerificationType.NPC_KILL
            && type != VerificationType.ITEM_DROP;
    }

    private static boolean isLegacyDailyTaskContext(DailyTasksSnapshot snapshot)
    {
        if (snapshot.getContext() == null)
        {
            return true;
        }
        String type = snapshot.getContext().getType();
        return type == null || type.trim().isEmpty()
            || "daily".equalsIgnoreCase(type)
            || "daily_tasks".equalsIgnoreCase(type);
    }

    static String resetText(DailyTasksSnapshot snapshot)
    {
        String nextReset = RESET_FORMAT.format(rotationEnd(snapshot));
        String type = snapshot.getContext() == null ? "" : snapshot.getContext().getType();
        if ("DROP_RUSH".equalsIgnoreCase(type) || "DRIP_RUSH".equalsIgnoreCase(type))
        {
            String end = snapshot.getContext().getEndsAt() == null ? ""
                : "<br>Rush ends: " + RESET_FORMAT.format(snapshot.getContext().getEndsAt());
            return "<html>Tasks reset: " + nextReset + end + "</html>";
        }
        return "Resets at: " + nextReset;
    }

    private static java.time.Instant rotationEnd(DailyTasksSnapshot snapshot)
    {
        return snapshot.getContext() != null
            && snapshot.getContext().getRotationEndsAt() != null
            ? snapshot.getContext().getRotationEndsAt()
            : snapshot.getResetAt();
    }

    private void updateTitle(String contextTitle, String contextType)
    {
        Color color = "DROP_RUSH".equalsIgnoreCase(contextType)
            ? DROP_RUSH_RED
            : ("DRIP_RUSH".equalsIgnoreCase(contextType)
                ? DRIP_RUSH_BLUE : DAILY_GREEN);
        titleLabel.setForeground(color);
        titleLabel.setText("<html><div style='width: " + CONTENT_WIDTH
            + "px'><b>" + escapeHtml(contextTitle.toUpperCase(Locale.ROOT))
            + "</b></div></html>");
    }

    private void updateTitle(String contextTitle)
    {
        updateTitle(contextTitle, "daily");
    }

    private void showStatus(String message)
    {
        statusLabel.setText(html(message));
    }

    private static boolean isNormalLoadMessage(String message)
    {
        return message != null
            && message.toLowerCase(Locale.ROOT).contains("tasks loaded");
    }

    private void setClaimButtons(boolean enabled)
    {
        for (TaskCard card : cards)
        {
            card.setEnabled(enabled);
        }
    }

    private static String html(String text)
    {
        return "<html><body style='width: " + CONTENT_WIDTH + "px'>"
            + escapeHtml(text) + "</body></html>";
    }

    private static String escapeHtml(String text)
    {
        return text.replace("&", "&amp;")
            .replace("<", "&lt;")
            .replace(">", "&gt;");
    }

    private static final class TaskCard extends JPanel
    {
        private final String assignmentId;
        private final JButton claimButton;
        private final JLabel details = new JLabel();
        private final JLabel progressValue = new JLabel();
        private final JLabel reward = new JLabel();
        private final JLabel claimed = new JLabel();
        private final JLabel icon = new JLabel();
        private final String category;
        private final SkillIconManager skillIconManager;
        private final JProgressBar progress = new JProgressBar();
        private int target = 1;
        private int currentProgress;
        private int awarded;
        private boolean serverCompleted;

        private TaskCard(String assignmentId, String buttonText, Runnable action, String category,
            SkillIconManager skillIconManager)
        {
            this.assignmentId = assignmentId;
            this.category = category;
            this.skillIconManager = skillIconManager;
            setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
            setBackground(ColorScheme.DARKER_GRAY_COLOR);
            setAlignmentX(LEFT_ALIGNMENT);
            setBorder(BorderFactory.createCompoundBorder(
                BorderFactory.createLineBorder(ColorScheme.MEDIUM_GRAY_COLOR),
                BorderFactory.createEmptyBorder(6, 7, 6, 7)));
            claimButton = new JButton(buttonText);
            claimButton.addActionListener(event -> action.run());
            JPanel taskRow = new JPanel(new BorderLayout(6, 0));
            taskRow.setOpaque(false);
            icon.setVerticalAlignment(JLabel.TOP);
            details.setVerticalAlignment(JLabel.TOP);
            taskRow.add(icon, BorderLayout.WEST);
            taskRow.add(details, BorderLayout.CENTER);
            add(taskRow);
            JPanel progressRow = new JPanel(new BorderLayout());
            progressRow.setOpaque(false);
            progressRow.setBorder(BorderFactory.createEmptyBorder(0, 0, 0, 4));
            progressValue.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
            reward.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
            progressRow.add(progressValue, BorderLayout.WEST);
            progressRow.add(reward, BorderLayout.EAST);
            add(Box.createRigidArea(new Dimension(0, 4)));
            add(progressRow);
            progress.setPreferredSize(new Dimension(0, 8));
            progress.setMaximumSize(new Dimension(Integer.MAX_VALUE, 8));
            progress.setBorderPainted(false);
            progress.setBackground(new Color(0x3B3B3B));
            add(Box.createRigidArea(new Dimension(0, 3)));
            add(progress);
            add(Box.createRigidArea(new Dimension(0, 3)));
            add(claimed);
            JPanel claimRow = new JPanel(new FlowLayout(FlowLayout.RIGHT, 0, 0));
            claimRow.setOpaque(false);
            claimRow.setAlignmentX(LEFT_ALIGNMENT);
            claimRow.setMaximumSize(new Dimension(Integer.MAX_VALUE, 25));
            claimButton.setPreferredSize(new Dimension(104, 25));
            claimButton.setMinimumSize(new Dimension(104, 25));
            claimButton.setMaximumSize(new Dimension(104, 25));
            claimRow.add(claimButton);
            add(claimRow);
            clear();
        }

        private void showTask(DailyTaskSummary task, String currencyName,
            String currencySymbol)
        {
            updateIcon(task);
            target = Math.max(1, task.getTarget());
            currentProgress = Math.min(target, Math.max(0, task.getProgress()));
            awarded = task.getAwarded();
            serverCompleted = task.isCompleted();
            progress.setMaximum(target);
            progress.setValue(currentProgress);
            progress.setForeground(task.isCompleted()
                ? new Color(0x70C090) : new Color(0xC88A3D));
            claimText = "Claim " + NUMBERS.format(task.getReward())
                + (currencySymbol.isEmpty() ? "" : " " + currencySymbol);
            claimButton.setText(claimText);
            // Keep the action available for unclaimed tasks. The server combines
            // the latest RuneLite progress with WOM data when validating a claim.
            claimButton.setVisible(!task.isCompleted());
            StringBuilder value = new StringBuilder("<html><body style='width: ")
                .append(CONTENT_WIDTH).append("px'>")
                .append(task.isDailyDrop() ? "<b>DAILY DROP</b> • " : "");
            if (task.isDailyDrop() && hasTier(task))
            {
                value.append("<font color='#B8B8B8'>[")
                    .append(escapeHtml(task.getTier())).append("]</font><br>");
            }
            else
            {
                value.append("<br>");
            }
            value.append("<b>").append(escapeHtml(task.getName())).append("</b><br>")
                .append("<font color='#B8B8B8'>")
                .append(escapeHtml(task.getDescription()
                    .replace(" experience", " XP"))).append("</font></body></html>");
            progressValue.setText(compact(currentProgress) + " / "
                + compact(target));
            reward.setText(NUMBERS.format(task.getReward())
                + (currencySymbol.isEmpty() ? " " + currencyName
                    : " " + currencySymbol));
            claimed.setVisible(task.isCompleted());
            claimed.setForeground(new Color(0x70C090));
            if (task.isCompleted())
            {
                claimed.setText("✓ Claimed • " + NUMBERS.format(task.getAwarded())
                    + (currencySymbol.isEmpty() ? " " + currencyName
                        : " " + currencySymbol));
                if (task.getPlacement() != null)
                {
                    claimed.setText(claimed.getText() + " (place "
                        + task.getPlacement() + ")");
                }
            }
            details.setText(value.toString());
            revalidate();
            repaint();
        }

        private static boolean hasTier(DailyTaskSummary task)
        {
            return task.getTier() != null && !task.getTier().trim().isEmpty();
        }

        private void updateLiveProgress(int value)
        {
            currentProgress = Math.max(currentProgress,
                Math.min(target, Math.max(0, value)));
            progress.setValue(currentProgress);
            if (currentProgress >= target)
            {
                progress.setForeground(DAILY_GREEN);
                if (!serverCompleted && !pending)
                {
                    claimButton.setEnabled(true);
                }
            }
            progressValue.setText(compact(currentProgress) + " / "
                + compact(target));
            repaint();
        }

        private boolean isCompleteForSummary()
        {
            return serverCompleted || currentProgress >= target;
        }

        private boolean isServerCompleted()
        {
            return serverCompleted;
        }

        private int getAwarded()
        {
            return awarded;
        }

        private void setClaiming()
        {
            claimButton.setText("Claiming...");
            claimButton.setEnabled(false);
        }

        private boolean pending;

        private void setPending()
        {
            pending = true;
            claimButton.setText("Syncing...");
            claimButton.setEnabled(false);
        }

        private void restoreClaim()
        {
            pending = false;
            claimButton.setText(claimText);
            claimButton.setEnabled(!serverCompleted && currentProgress >= target);
        }

        private String claimText = "Claim";

        private void clear()
        {
            pending = false;
            icon.setIcon(null);
            icon.setText(defaultIcon());
            progress.setValue(0);
            target = 1;
            currentProgress = 0;
            awarded = 0;
            serverCompleted = false;
            progressValue.setText("");
            reward.setText("");
            claimed.setText("");
            claimed.setVisible(false);
            claimButton.setVisible(false);
            details.setText(html("Task unavailable."));
        }

        private void updateIcon(DailyTaskSummary task)
        {
            if (!category.equals("SKILLING") || skillIconManager == null)
            {
                icon.setText(defaultIcon());
                icon.setIcon(null);
                return;
            }
            Skill skill = findSkill(task.getName());
            BufferedImage image = skill == null
                ? null : skillIconManager.getSkillImage(skill);
            if (image == null)
            {
                icon.setText("🪓");
                icon.setIcon(null);
            }
            else
            {
                icon.setText("");
                icon.setIcon(new ImageIcon(image));
            }
        }

        private String defaultIcon()
        {
            if (category.equals("PVM"))
            {
                return "⚔";
            }
            if (category.equals("DROP"))
            {
                return "⬇";
            }
            return category.equals("SKILLING") ? "⚒" : "🎮";
        }

        private static String compact(int value)
        {
            if (value >= 1_000_000)
            {
                return String.format(Locale.US, "%.1fM", value / 1_000_000.0)
                    .replace(".0M", "M");
            }
            if (value >= 1_000)
            {
                return String.format(Locale.US, "%.1fK", value / 1_000.0)
                    .replace(".0K", "K");
            }
            return NUMBERS.format(value);
        }

        private static Skill findSkill(String taskName)
        {
            String normalized = taskName == null ? ""
                : taskName.toLowerCase(Locale.ROOT);
            for (Skill skill : Skill.values())
            {
                String name = skill.getName().toLowerCase(Locale.ROOT);
                if (normalized.contains(name))
                {
                    return skill;
                }
            }
            return null;
        }

        @Override
        public void setEnabled(boolean enabled)
        {
            super.setEnabled(enabled);
            if (claimButton != null)
            {
                claimButton.setEnabled(enabled && !pending && !serverCompleted
                    && currentProgress >= target);
            }
        }
    }
}

package com.clanhq.verifier.daily;

import com.clanhq.verifier.daily.model.DailyTaskSummary;
import com.clanhq.verifier.daily.model.DailyTasksSnapshot;
import com.clanhq.verifier.loot.ObservedDrop;
import com.clanhq.verifier.task.VerificationType;
import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.ItemStack;
import java.util.function.IntUnaryOperator;

/** The single ITEM_DROP matching implementation shared by panel and overlay. */
final class ItemDropMatcher
{
    static final class Match
    {
        private final int canonicalItemId;
        private final int quantity;

        Match(int canonicalItemId, int quantity)
        {
            this.canonicalItemId = canonicalItemId;
            this.quantity = quantity;
        }

        int getCanonicalItemId() { return canonicalItemId; }
        int getQuantity() { return quantity; }
    }

    private ItemDropMatcher() { }

    static Map<String, Match> findMatches(DailyTasksSnapshot snapshot,
        ObservedDrop drop, ItemManager itemManager)
    {
        return findMatches(snapshot, drop, itemManager == null
            ? itemId -> itemId : itemManager::canonicalize);
    }

    static Map<String, Match> findMatches(DailyTasksSnapshot snapshot,
        ObservedDrop drop, IntUnaryOperator canonicalizer)
    {
        if (snapshot == null || drop == null || drop.getItems() == null)
        {
            return Collections.emptyMap();
        }
        Map<String, Match> matches = new HashMap<>();
        for (ItemStack item : drop.getItems())
        {
            int canonicalItemId = canonicalizer.applyAsInt(item.getId());
            int quantity = Math.max(0, item.getQuantity());
            if (quantity <= 0)
            {
                continue;
            }
            for (DailyTaskSummary task : snapshot.getTasks())
            {
                if (task.getId() == null || task.getId().trim().isEmpty()
                    || task.getVerificationType() != VerificationType.ITEM_DROP
                    || !task.getVerificationItemIds().contains(canonicalItemId))
                {
                    continue;
                }
                Match previous = matches.get(task.getId());
                matches.put(task.getId(), new Match(canonicalItemId,
                    (previous == null ? 0 : previous.getQuantity()) + quantity));
            }
        }
        return matches;
    }
}

package com.clanhq.verifier.daily;

import com.clanhq.verifier.ClanHQVerifierConfig;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import java.util.ArrayList;
import java.util.List;
import java.util.UUID;
import java.util.function.Consumer;
import java.util.function.Supplier;
import net.runelite.client.config.ConfigManager;

/** Locally durable, installation-scoped claims created only by a Claim click. */
final class PendingClaimStore
{
    private static final String KEY = "dailyTasksPendingClaims";
    private final Consumer<String> save;
    private final List<JsonObject> claims = new ArrayList<>();

    PendingClaimStore(ConfigManager config)
    {
        this(() -> config.getConfiguration(ClanHQVerifierConfig.GROUP, KEY),
            value -> config.setConfiguration(ClanHQVerifierConfig.GROUP, KEY, value));
    }

    PendingClaimStore(Supplier<String> load, Consumer<String> save)
    {
        this.save = save;
        String raw = load.get();
        if (raw == null || raw.trim().isEmpty()) { return; }
        try
        {
            for (JsonElement value : new JsonParser().parse(raw).getAsJsonArray())
            {
                JsonObject claim = value.getAsJsonObject();
                if (claim.has("claim_id") && claim.has("scope")
                    && claim.has("period_date") && claim.has("reset_at")
                    && claim.has("category") && claim.has("client_progress"))
                {
                    claims.add(claim);
                }
            }
        }
        catch (RuntimeException error)
        {
            // Preserve malformed data for support rather than silently deleting it.
            claims.clear();
        }
    }

    synchronized JsonObject enqueue(String scope, String periodDate,
        String resetAt, String clickedAt, String contextId, String category, String taskId,
        JsonArray progress)
    {
        JsonObject existing = find(scope, periodDate, resetAt, contextId, category);
        if (existing != null) { return existing.deepCopy(); }
        JsonObject claim = new JsonObject();
        claim.addProperty("claim_id", UUID.randomUUID().toString());
        claim.addProperty("scope", scope);
        claim.addProperty("period_date", periodDate);
        claim.addProperty("reset_at", resetAt);
        claim.addProperty("clicked_at", clickedAt);
        claim.addProperty("context_id", contextId);
        claim.addProperty("category", category);
        claim.addProperty("task_id", taskId);
        claim.add("client_progress", progress.deepCopy());
        claims.add(claim);
        persist();
        return claim.deepCopy();
    }

    synchronized JsonObject find(String scope, String periodDate,
        String resetAt, String contextId, String category)
    {
        for (JsonObject claim : claims)
        {
            if (scope.equals(string(claim, "scope"))
                && periodDate.equals(string(claim, "period_date"))
                && resetAt.equals(string(claim, "reset_at"))
                && contextId.equals(string(claim, "context_id"))
                && category.equals(string(claim, "category")))
            {
                return claim.deepCopy();
            }
        }
        return null;
    }

    synchronized List<JsonObject> forScope(String scope)
    {
        List<JsonObject> result = new ArrayList<>();
        for (JsonObject claim : claims)
        {
            if (scope.equals(string(claim, "scope")))
            {
                result.add(claim.deepCopy());
            }
        }
        return result;
    }

    synchronized void acknowledge(String claimId)
    {
        if (claims.removeIf(claim -> claimId.equals(string(claim, "claim_id"))))
        {
            persist();
        }
    }

    private void persist()
    {
        JsonArray values = new JsonArray();
        claims.forEach(values::add);
        save.accept(values.toString());
    }

    static String string(JsonObject value, String key)
    {
        return value.has(key) && !value.get(key).isJsonNull()
            ? value.get(key).getAsString() : "";
    }
}

package com.clanhq.verifier.daily;

import java.util.concurrent.CompletableFuture;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.TimeoutException;
import java.util.function.BiConsumer;
import java.util.function.Consumer;
import java.util.function.Supplier;

/** Single-flight authoritative reads, with a trailing refresh and independent recovery timer. */
final class ReconciliationLoop<T>
{
    static final int INTERVAL_SECONDS = 30;
    static final int TIMEOUT_SECONDS = 20;
    private final ScheduledExecutorService executor;
    private final Consumer<Runnable> dispatch;
    private final Supplier<CompletableFuture<T>> fetch;
    private final BiConsumer<T, Throwable> receive;
    private ScheduledFuture<?> periodic;
    private ScheduledFuture<?> timeout;
    private boolean running;
    private boolean busy;
    private boolean pending;
    private long generation;

    ReconciliationLoop(ScheduledExecutorService executor, Consumer<Runnable> dispatch,
        Supplier<CompletableFuture<T>> fetch, BiConsumer<T, Throwable> receive)
    {
        this.executor = executor;
        this.dispatch = dispatch;
        this.fetch = fetch;
        this.receive = receive;
    }

    synchronized void start()
    {
        stop();
        running = true;
        if (executor != null)
        {
            periodic = executor.scheduleWithFixedDelay(this::refresh,
                INTERVAL_SECONDS, INTERVAL_SECONDS, TimeUnit.SECONDS);
        }
        refresh();
    }

    synchronized void stop()
    {
        running = false;
        generation++;
        busy = false;
        pending = false;
        if (periodic != null) { periodic.cancel(false); }
        if (timeout != null) { timeout.cancel(false); }
    }

    synchronized void refresh()
    {
        if (!running) { return; }
        if (busy)
        {
            pending = true;
            return;
        }
        busy = true;
        long request = ++generation;
        if (executor != null)
        {
            timeout = executor.schedule(() -> complete(request, null,
                new TimeoutException("Authoritative refresh timed out")),
                TIMEOUT_SECONDS, TimeUnit.SECONDS);
        }
        try
        {
            fetch.get().whenComplete((value, error) -> complete(request, value, error));
        }
        catch (RuntimeException error)
        {
            complete(request, null, error);
        }
    }

    private void complete(long request, T value, Throwable error)
    {
        dispatch.accept(() -> {
            synchronized (this)
            {
                if (!running || !busy || request != generation) { return; }
                if (timeout != null) { timeout.cancel(false); }
                busy = false;
                // Retire this request even if a late response arrives after timeout.
                generation++;
                try
                {
                    receive.accept(value, error);
                }
                finally
                {
                    if (pending)
                    {
                        pending = false;
                        refresh();
                    }
                }
            }
        });
    }
}

package com.clanhq.verifier.daily.model;

import com.clanhq.verifier.task.VerificationType;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

public final class DailyTaskSummary
{
    private final String id;
    private final String category;
    private final String name;
    private final String description;
    private final int target;
    private final int progress;
    private final int reward;
    private final boolean completed;
    private final int awarded;
    private final Integer placement;
    private final VerificationType verificationType;
    private final Integer verificationItemId;
    private final List<Integer> verificationItemIds;
    private final String tier;
    private final String taskType;

    public DailyTaskSummary(String category, String name, String description,
        int target, int progress, int reward, boolean completed, int awarded,
        Integer placement)
    {
        this(null, category, name, description, target, progress, reward,
            completed, awarded, placement, VerificationType.UNKNOWN, null, null, null, "NORMAL");
    }

    public DailyTaskSummary(String category, String name, String description,
        int target, int progress, int reward, boolean completed, int awarded,
        Integer placement, VerificationType verificationType)
    {
        this(null, category, name, description, target, progress, reward,
            completed, awarded, placement, verificationType, null, null, null, "NORMAL");
    }

    public DailyTaskSummary(String id, String category, String name,
        String description,
        int target, int progress, int reward, boolean completed, int awarded,
        Integer placement, VerificationType verificationType,
        Integer verificationItemId)
    {
        this(id, category, name, description, target, progress, reward, completed,
            awarded, placement, verificationType, verificationItemId, null, null, "NORMAL");
    }

    public DailyTaskSummary(String id, String category, String name, String description,
        int target, int progress, int reward, boolean completed, int awarded,
        Integer placement, VerificationType verificationType, Integer verificationItemId,
        List<Integer> verificationItemIds, String tier, String taskType)
    {
        this.id = id;
        this.category = category;
        this.name = name;
        this.description = description;
        this.target = target;
        this.progress = progress;
        this.reward = reward;
        this.completed = completed;
        this.awarded = awarded;
        this.placement = placement;
        this.verificationType = verificationType;
        this.verificationItemId = verificationItemId;
        List<Integer> ids = verificationItemIds == null
            ? new ArrayList<>() : new ArrayList<>(verificationItemIds);
        if (verificationItemId != null && !ids.contains(verificationItemId))
        {
            ids.add(verificationItemId);
        }
        this.verificationItemIds = Collections.unmodifiableList(ids);
        this.tier = tier;
        this.taskType = taskType == null ? "NORMAL" : taskType;
    }

    public String getId() { return id; }
    public String getCategory() { return category; }
    public String getName() { return name; }
    public String getDescription() { return description; }
    public int getTarget() { return target; }
    public int getProgress() { return progress; }
    public int getReward() { return reward; }
    public boolean isCompleted() { return completed; }
    public int getAwarded() { return awarded; }
    public Integer getPlacement() { return placement; }
    public VerificationType getVerificationType() { return verificationType; }
    public Integer getVerificationItemId() { return verificationItemId; }
    public List<Integer> getVerificationItemIds() { return verificationItemIds; }
    public String getTier() { return tier; }
    public String getTaskType() { return taskType; }
    public boolean isDailyDrop() { return "DAILY_DROP".equalsIgnoreCase(taskType); }
}

package com.clanhq.verifier.daily.model;

import com.clanhq.verifier.task.VerificationType;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import java.time.Instant;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

public final class DailyTasksSnapshot
{
    private final Instant resetAt;
    private final String periodDate;
    private final List<DailyTaskSummary> tasks;
    private final int balance;
    private final String currencyName;
    private final String currencySymbol;
    private final String serverName;
    private final TaskContext context;

    private DailyTasksSnapshot(String periodDate, Instant resetAt,
        List<DailyTaskSummary> tasks,
        int balance, String currencyName, String currencySymbol,
        String serverName, TaskContext context)
    {
        this.periodDate = periodDate;
        this.resetAt = resetAt;
        this.tasks = Collections.unmodifiableList(new ArrayList<>(tasks));
        this.balance = balance;
        this.currencyName = currencyName;
        this.currencySymbol = currencySymbol;
        this.serverName = serverName;
        this.context = context;
    }

    public static DailyTasksSnapshot fromJson(String json)
    {
        JsonObject root = new JsonParser().parse(json).getAsJsonObject();
        JsonObject contextValue = object(root, "context");
        String periodDate = root.has("period_date")
            ? root.get("period_date").getAsString() : "";
        Instant resetAt = instant(root, "reset_at");
        if (resetAt == null)
        {
            resetAt = instant(contextValue, "ends_at");
        }
        if (resetAt == null)
        {
            throw new IllegalArgumentException("Tasks response has no end time");
        }
        TaskContext context = new TaskContext(
            string(contextValue, "id", root, "period_date"),
            string(contextValue, "type", null, null),
            string(contextValue, "title", null, null),
            nullableString(contextValue, "description"),
            instant(contextValue, "starts_at"),
            instant(contextValue, "ends_at"),
            instant(contextValue, "rotation_ends_at"));
        JsonArray values = root.getAsJsonArray("tasks");
        List<DailyTaskSummary> tasks = new ArrayList<>();
        for (JsonElement element : values)
        {
            JsonObject value = element.getAsJsonObject();
            JsonObject display = object(value, "display");
            JsonObject progressState = value.has("progress_state")
                ? object(value, "progress_state") : object(value, "progress");
            JsonObject rewardState = value.has("reward_state")
                ? object(value, "reward_state") : object(value, "reward");
            JsonObject state = object(value, "state");
            JsonObject verification = object(value, "verification");
            String name = string(display, "name", value, "name");
            String description = string(display, "description", value, "description");
            int target = integer(progressState, "target", value, "target");
            int progress = integer(progressState, "current", value, "progress");
            int reward = integer(rewardState, "amount", value, "reward");
            boolean claimed = bool(state, "claimed", value, "completed");
            int awarded = integer(value, "awarded", null, null);
            if (state.has("awarded") && !state.get("awarded").isJsonNull())
            {
                awarded = state.get("awarded").getAsInt();
            }
            String verificationName = verification.has("type")
                ? verification.get("type").getAsString() : null;
            Integer verificationItemId = verification.has("item_id")
                && !verification.get("item_id").isJsonNull()
                    ? verification.get("item_id").getAsInt() : null;
            List<Integer> verificationItemIds = new ArrayList<>();
            String itemIdsKey = verification.has("item_ids") ? "item_ids" : "acceptable_item_ids";
            if (verification.has(itemIdsKey) && verification.get(itemIdsKey).isJsonArray())
            {
                for (JsonElement item : verification.getAsJsonArray(itemIdsKey))
                {
                    verificationItemIds.add(item.getAsInt());
                }
            }
            String category = value.has("category")
                ? value.get("category").getAsString()
                : categoryFor(VerificationType.from(verificationName));
            // MINIGAME is a persisted/API compatibility value only.  Never
            // expose it in the current overlay or panel UI.
            if ("MINIGAME".equalsIgnoreCase(category.trim()))
            {
                category = "ACTIVITIES";
            }
            else if ("DAILY_DROP".equalsIgnoreCase(category.trim()))
            {
                category = "DROP";
            }
            String taskType = value.has("task_type")
                ? value.get("task_type").getAsString() : "NORMAL";
            String tier = value.has("tier") && !value.get("tier").isJsonNull()
                ? value.get("tier").getAsString() : null;
            tasks.add(new DailyTaskSummary(
                value.has("id") && !value.get("id").isJsonNull()
                    ? value.get("id").getAsString() : null,
                category,
                name,
                description,
                target,
                progress > 0 ? progress : (claimed ? target : 0),
                reward,
                claimed,
                awarded,
                value.has("placement") && !value.get("placement").isJsonNull()
                    ? value.get("placement").getAsInt() : null,
                VerificationType.from(verificationName), verificationItemId,
                verificationItemIds,
                tier,
                taskType));
        }
        return new DailyTasksSnapshot(
            periodDate,
            resetAt,
            tasks,
            root.has("balance") ? root.get("balance").getAsInt() : 0,
            root.has("currency_name")
                ? root.get("currency_name").getAsString() : "Currency",
            root.has("currency_symbol")
                ? root.get("currency_symbol").getAsString() : "",
            root.has("server_name") ? root.get("server_name").getAsString()
                : "ClanHQ",
            context);
    }

    public Instant getResetAt() { return resetAt; }
    public String getPeriodDate() { return periodDate; }
    public List<DailyTaskSummary> getTasks() { return tasks; }
    public int getBalance() { return balance; }
    public String getCurrencyName() { return currencyName; }
    public String getCurrencySymbol() { return currencySymbol; }
    public String getServerName() { return serverName; }
    public TaskContext getContext() { return context; }

    private static String categoryFor(VerificationType type)
    {
        switch (type)
        {
            case SKILL_XP:
                return "SKILLING";
            case NPC_KILL:
                return "PVM";
            case MINIGAME_SCORE:
            case ITEM_DROP:
            case CLUE_COMPLETE:
            case ACTIVITY_TELEMETRY:
                return "ACTIVITIES";
            default:
                return "UNKNOWN";
        }
    }

    private static JsonObject object(JsonObject parent, String key)
    {
        return parent.has(key) && parent.get(key).isJsonObject()
            ? parent.getAsJsonObject(key) : new JsonObject();
    }

    private static Instant instant(JsonObject parent, String key)
    {
        if (parent == null || !parent.has(key) || parent.get(key).isJsonNull())
        {
            return null;
        }
        try
        {
            return Instant.parse(parent.get(key).getAsString());
        }
        catch (RuntimeException exception)
        {
            return null;
        }
    }

    private static String nullableString(JsonObject parent, String key)
    {
        return parent.has(key) && !parent.get(key).isJsonNull()
            ? parent.get(key).getAsString() : null;
    }

    private static String string(JsonObject preferred, String preferredKey,
        JsonObject fallback, String fallbackKey)
    {
        if (preferred.has(preferredKey) && !preferred.get(preferredKey).isJsonNull())
        {
            return preferred.get(preferredKey).getAsString();
        }
        return fallback != null && fallbackKey != null
            && fallback.has(fallbackKey) && !fallback.get(fallbackKey).isJsonNull()
            ? fallback.get(fallbackKey).getAsString() : "";
    }

    private static int integer(JsonObject preferred, String preferredKey,
        JsonObject fallback, String fallbackKey)
    {
        if (preferred.has(preferredKey) && !preferred.get(preferredKey).isJsonNull())
        {
            return preferred.get(preferredKey).getAsInt();
        }
        return fallback != null && fallback.has(fallbackKey)
            && !fallback.get(fallbackKey).isJsonNull()
                ? fallback.get(fallbackKey).getAsInt() : 0;
    }

    private static boolean bool(JsonObject preferred, String preferredKey,
        JsonObject fallback, String fallbackKey)
    {
        if (preferred.has(preferredKey) && !preferred.get(preferredKey).isJsonNull())
        {
            return preferred.get(preferredKey).getAsBoolean();
        }
        return fallback.has(fallbackKey) && !fallback.get(fallbackKey).isJsonNull()
            && fallback.get(fallbackKey).getAsBoolean();
    }
}

package com.clanhq.verifier.daily.model;

import java.time.Instant;

/** Server-provided presentation and timing metadata for an active task set. */
public final class TaskContext
{
    private final String id;
    private final String type;
    private final String title;
    private final String description;
    private final Instant startsAt;
    private final Instant endsAt;
    private final Instant rotationEndsAt;

    public TaskContext(String id, String type, String title, String description,
        Instant startsAt, Instant endsAt, Instant rotationEndsAt)
    {
        this.id = id == null ? "" : id;
        this.type = type == null ? "" : type;
        this.title = title == null ? "" : title;
        this.description = description;
        this.startsAt = startsAt;
        this.endsAt = endsAt;
        this.rotationEndsAt = rotationEndsAt;
    }

    public String getId() { return id; }
    public String getType() { return type; }
    public String getTitle() { return title; }
    public String getDescription() { return description; }
    public Instant getStartsAt() { return startsAt; }
    public Instant getEndsAt() { return endsAt; }
    public Instant getRotationEndsAt() { return rotationEndsAt; }
}

