package com.clanhq.verifier.daily.transport;

import com.clanhq.verifier.ClanHQVerifierConfig;
import com.clanhq.verifier.daily.model.DailyTasksSnapshot;
import com.clanhq.verifier.loot.ObservedDrop;
import com.google.gson.JsonArray;
import com.clanhq.verifier.service.ApiDestinationService;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import java.io.IOException;
import java.util.concurrent.CompletableFuture;
import java.time.Instant;
import java.util.Map;
import java.util.UUID;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.MediaType;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;
import okhttp3.Response;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

public final class DailyTasksApiClient
{
    private static final Logger log = LoggerFactory.getLogger(DailyTasksApiClient.class);
    /** Capabilities with an implemented RuneLite observation source. */
    private static final String CAPABILITIES =
        "SKILL_XP,NPC_KILL,ITEM_DROP,ACTIVITY_TELEMETRY";
    private static final MediaType JSON =
        MediaType.parse("application/json; charset=utf-8");
    private final OkHttpClient httpClient;
    private final ClanHQVerifierConfig config;
    private final ApiDestinationService destinationService;

    public DailyTasksApiClient(OkHttpClient httpClient,
        ClanHQVerifierConfig config,
        ApiDestinationService destinationService)
    {
        this.httpClient = httpClient;
        this.config = config;
        this.destinationService = destinationService;
    }

    public CompletableFuture<DailyTasksResult> fetch()
    {
        CompletableFuture<DailyTasksResult> future = new CompletableFuture<>();
        Request request = authenticatedRequest("/api/v1/daily-tasks");
        if (request == null)
        {
            future.complete(new DailyTasksResult(null,
                "Pair this RuneLite installation to load daily tasks."));
            return future;
        }
        httpClient.newCall(request).enqueue(new Callback()
        {
            @Override
            public void onFailure(Call call, IOException exception)
            {
                log.warn("sync phase=read request_id={} status=transport_failure",
                    request.header("X-ClanHQ-Correlation-ID"));
                future.complete(new DailyTasksResult(null,
                    "ClanHQ could not be reached."));
            }

            @Override
            public void onResponse(Call call, Response response)
                throws IOException
            {
                try (Response closeable = response)
                {
                    log.debug("sync phase=read request_id={} status={}",
                        response.header("X-ClanHQ-Request-ID"), response.code());
                    String body = body(response);
                    if (!response.isSuccessful())
                    {
                        future.complete(new DailyTasksResult(null,
                            responseMessage(body, response.code())));
                        return;
                    }
                    future.complete(new DailyTasksResult(
                        DailyTasksSnapshot.fromJson(body),
                        "Daily tasks loaded."));
                }
                catch (IOException | RuntimeException exception)
                {
                    future.complete(new DailyTasksResult(null,
                        "ClanHQ returned invalid daily tasks."));
                }
            }
        });
        return future;
    }

    public CompletableFuture<DailyActionResult> claim(String category)
    {
        return claim(category, null, null);
    }

    /**
     * Submit a server-authoritative ITEM_DROP observation when the task API is
     * enabled. This is deliberately separate from claim and does not trust
     * client-supplied reward, target, or completion values.
     */
    public CompletableFuture<Boolean> submitItemDropObservation(
        String assignmentId, ObservedDrop drop, int itemId, int quantity)
    {
        CompletableFuture<Boolean> future = new CompletableFuture<>();
        Request base = authenticatedRequest(
            "/api/v1/tasks/" + normalized(assignmentId) + "/observations");
        if (base == null || normalized(assignmentId).isEmpty()
            || drop == null || quantity <= 0)
        {
            future.complete(false);
            return future;
        }
        JsonObject payload = new JsonObject();
        payload.addProperty("verification_type", "ITEM_DROP");
        payload.addProperty("item_id", itemId);
        payload.addProperty("quantity", quantity);
        payload.addProperty("source_type", drop.getSourceType());
        payload.addProperty("source_name", drop.getSourceName());
        payload.addProperty("observed_at", drop.getObservedAt() == null
            ? Instant.now().toString() : drop.getObservedAt().toString());
        Request request = base.newBuilder()
            .post(RequestBody.create(JSON, payload.toString()))
            .build();
        httpClient.newCall(request).enqueue(new Callback()
        {
            @Override
            public void onFailure(Call call, IOException exception)
            {
                future.complete(false);
            }

            @Override
            public void onResponse(Call call, Response response)
                throws IOException
            {
                try (Response closeable = response)
                {
                    future.complete(response.isSuccessful());
                }
            }
        });
        return future;
    }

    /** Submit generic gameplay telemetry; the server decides task matching. */
    public CompletableFuture<Boolean> submitActivity(
        String rsn, String activity, int quantity, Map<String, String> metadata)
    {
        CompletableFuture<Boolean> future = new CompletableFuture<>();
        Request base = authenticatedRequest("/api/v1/activities");
        if (base == null || normalized(rsn).isEmpty()
            || normalized(activity).isEmpty() || quantity <= 0)
        {
            future.complete(false);
            return future;
        }
        JsonObject payload = new JsonObject();
        payload.addProperty("schema_version", 1);
        payload.addProperty("event_id", UUID.randomUUID().toString());
        payload.addProperty("rsn", rsn.trim());
        payload.addProperty("activity", activity.trim());
        payload.addProperty("quantity", quantity);
        JsonObject values = new JsonObject();
        if (metadata != null)
        {
            metadata.forEach((key, value) -> values.addProperty(key, value));
        }
        payload.add("metadata", values);
        payload.addProperty("observed_at", Instant.now().toString());
        Request request = base.newBuilder()
            .post(RequestBody.create(JSON, payload.toString()))
            .build();
        httpClient.newCall(request).enqueue(new Callback()
        {
            @Override
            public void onFailure(Call call, IOException exception)
            {
                future.complete(false);
            }

            @Override
            public void onResponse(Call call, Response response)
                throws IOException
            {
                try (Response closeable = response)
                {
                    future.complete(response.isSuccessful());
                }
            }
        });
        return future;
    }

    public CompletableFuture<DailyActionResult> claim(
        String category,
        String periodDate,
        JsonArray clientProgress)
    {
        return claim(category, periodDate, clientProgress, null);
    }

    public CompletableFuture<DailyActionResult> claim(
        String category,
        String periodDate,
        JsonArray clientProgress,
        String claimId)
    {
        return claim(category, periodDate, clientProgress, claimId, null, null, null);
    }

    public CompletableFuture<DailyActionResult> claim(
        String category, String periodDate, JsonArray clientProgress,
        String claimId, String clickedAt, String resetAt, String contextId)
    {
        CompletableFuture<DailyActionResult> future = new CompletableFuture<>();
        Request base = authenticatedRequest("/api/v1/daily-tasks/claim");
        if (base == null)
        {
            future.complete(new DailyActionResult(false,
                "Pair this RuneLite installation before claiming.", 0,
                "Currency", ""));
            return future;
        }
        JsonObject payload = new JsonObject();
        payload.addProperty("category", category);
        if (claimId != null)
        {
            payload.addProperty("claim_id", claimId);
            payload.addProperty("clicked_at", clickedAt);
            payload.addProperty("reset_at", resetAt);
            payload.addProperty("context_id", contextId);
        }
        if (periodDate != null && clientProgress != null)
        {
            payload.addProperty("period_date", periodDate);
            payload.add("client_progress", clientProgress);
        }
        Request request = base.newBuilder()
            .post(RequestBody.create(JSON, payload.toString()))
            .build();
        sendAction(request, future, "ClanHQ could not verify daily tasks.",
            null);
        return future;
    }

    private void sendAction(Request request,
        CompletableFuture<DailyActionResult> future,
        String failureMessage,
        String rewardField)
    {
        log.info("sync phase=mutation request_id={} path={} status=sent",
            request.header("X-ClanHQ-Correlation-ID"), request.url().encodedPath());
        httpClient.newCall(request).enqueue(new Callback()
        {
            @Override
            public void onFailure(Call call, IOException exception)
            {
                log.warn("sync phase=mutation request_id={} status=unconfirmed",
                    request.header("X-ClanHQ-Correlation-ID"));
                future.complete(new DailyActionResult(
                    false, failureMessage + " " + transportFailure(exception, call.isCanceled())
                        + " Refresh daily tasks before trying Claim again; the outcome is unconfirmed.",
                    0, "Currency", ""));
            }

            @Override
            public void onResponse(Call call, Response response)
                throws IOException
            {
                try (Response closeable = response)
                {
                    log.info("sync phase=mutation request_id={} status={}",
                        response.header("X-ClanHQ-Request-ID"), response.code());
                    String body = body(response);
                    int reward = response.isSuccessful()
                        ? rewardAmount(body, rewardField) : 0;
                    JsonObject value = response.isSuccessful()
                        ? parse(body) : new JsonObject();
                    future.complete(new DailyActionResult(
                        response.isSuccessful(),
                        responseMessage(body, response.code()),
                        reward,
                        value.has("currency_name")
                            ? value.get("currency_name").getAsString()
                            : "Currency",
                        value.has("currency_symbol")
                            ? value.get("currency_symbol").getAsString()
                            : ""));
                }
                catch (IOException | RuntimeException exception)
                {
                    future.complete(new DailyActionResult(false,
                        "ClanHQ returned an invalid response.", 0,
                        "Currency", ""));
                }
            }
        });
    }

    private Request authenticatedRequest(String path)
    {
        String baseUrl = destinationService.normalize(config.apiBaseUrl());
        String token = normalized(config.installationToken());
        if (baseUrl == null || token.isEmpty())
        {
            return null;
        }
        return new Request.Builder()
            .url(baseUrl + path)
            .header("Authorization", "Bearer " + token)
            .header("X-ClanHQ-Correlation-ID", UUID.randomUUID().toString().replace("-", ""))
            .header("X-ClanHQ-Plugin-Version", "1")
            .header("X-ClanHQ-Plugin-Capabilities", CAPABILITIES)
            .get()
            .build();
    }

    private static int rewardAmount(String body, String rewardField)
    {
        JsonObject value = parse(body);
        if (rewardField != null)
        {
            return value.has(rewardField) ? value.get(rewardField).getAsInt() : 0;
        }
        int total = 0;
        JsonArray tasks = value.has("tasks")
            ? value.getAsJsonArray("tasks") : new JsonArray();
        for (JsonElement element : tasks)
        {
            total += element.getAsJsonObject().get("awarded").getAsInt();
        }
        if (value.has("completion") && !value.get("completion").isJsonNull())
        {
            total += value.getAsJsonObject("completion")
                .get("awarded").getAsInt();
        }
        return total;
    }

    static String transportFailure(IOException exception, boolean cancelled)
    {
        if (cancelled)
        {
            return "The request was cancelled [CANCELLED].";
        }
        if (exception instanceof java.net.UnknownHostException)
        {
            return "The server address could not be resolved [DNS_FAILURE].";
        }
        if (exception instanceof javax.net.ssl.SSLException)
        {
            return "A secure connection could not be established [TLS_FAILURE].";
        }
        if (exception instanceof java.net.ConnectException)
        {
            return "A connection to the server could not be established [CONNECT_FAILURE].";
        }
        if (exception instanceof java.io.InterruptedIOException)
        {
            return "The request timed out or was interrupted [TIMEOUT_OR_INTERRUPTED].";
        }
        if (exception instanceof java.net.SocketException || exception instanceof java.io.EOFException)
        {
            return "The connection closed before a response arrived [CONNECTION_LOST].";
        }
        // Do not expose exception messages: they can contain URLs or credentials.
        return "A network I/O error prevented a response [NETWORK_IO].";
    }

    private static String responseMessage(String body, int status)
    {
        try
        {
            JsonObject value = parse(body);
            if (value.has("message"))
            {
                return value.get("message").getAsString();
            }
        }
        catch (RuntimeException ignored)
        {
            // Fall through to a stable HTTP status message.
        }
        return "ClanHQ returned HTTP " + status;
    }

    private static JsonObject parse(String body)
    {
        return new JsonParser().parse(body).getAsJsonObject();
    }

    private static String body(Response response) throws IOException
    {
        return response.body() == null ? "" : response.body().string();
    }

    private static String normalized(String value)
    {
        return value == null ? "" : value.trim();
    }
}

