package com.clanhq.verifier.event;

import com.clanhq.verifier.event.model.ClanEventSummary;
import com.clanhq.verifier.event.model.ClanEventsSnapshot;
import com.clanhq.verifier.event.transport.EventApiClient;
import com.clanhq.verifier.feature.ClanHQFeature;
import com.clanhq.verifier.task.VerificationType;
import java.time.Duration;
import java.time.Instant;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.function.Supplier;
import java.util.concurrent.atomic.AtomicBoolean;
import javax.swing.JComponent;
import javax.swing.SwingUtilities;

public final class EventFeature implements ClanHQFeature
{
    private static final Duration SKILL_SUBMISSION_INTERVAL =
        Duration.ofSeconds(60);
    private final EventApiClient apiClient;
    private final EventPanel panel;
    private final Supplier<String> rsnSupplier;
    private volatile boolean running;
    private volatile List<ClanEventSummary> currentEvents =
        Collections.emptyList();
    private final Map<Long, Instant> lastSkillSubmissions = new HashMap<>();
    private final AtomicBoolean refreshInFlight = new AtomicBoolean();

    public EventFeature(EventApiClient apiClient, Supplier<String> rsnSupplier)
    {
        this.apiClient = apiClient;
        this.rsnSupplier = rsnSupplier;
        this.panel = new EventPanel(this::refresh);
    }

    @Override
    public String getId() { return "events"; }

    @Override
    public String getDisplayName() { return "Events"; }

    @Override
    public String getNavigationIconResource()
    {
        return "/com/clanhq/verifier/icons/events.png";
    }

    @Override
    public String getDescription()
    {
        return "View current ClanHQ events.";
    }

    @Override
    public JComponent getPanel() { return panel; }

    @Override
    public void startUp()
    {
        running = true;
        refresh();
    }

    @Override
    public void shutDown()
    {
        running = false;
        currentEvents = Collections.emptyList();
        synchronized (lastSkillSubmissions)
        {
            lastSkillSubmissions.clear();
        }
    }

    public void refresh()
    {
        if (!running || !refreshInFlight.compareAndSet(false, true))
        {
            return;
        }
        panel.setLoading();
        apiClient.fetchEvents().thenAccept(result ->
            SwingUtilities.invokeLater(() ->
            {
                refreshInFlight.set(false);
                if (!running)
                {
                    return;
                }
                result.getSnapshot().ifPresentOrElse(
                    this::showEvents,
                    () -> panel.showError(result.getMessage()));
            }));
    }

    private void showEvents(ClanEventsSnapshot snapshot)
    {
        currentEvents = snapshot.getEvents();
        panel.showEvents(snapshot.getServerName(), currentEvents);
    }

    public void onSkillExperience(String skillName, int experience)
    {
        if (skillName == null || experience <= 0)
        {
            return;
        }
        Instant now = Instant.now();
        for (ClanEventSummary event : currentEvents)
        {
            boolean skillVerification = event.getVerificationType()
                == VerificationType.SKILL_XP
                || (event.getVerificationType() == VerificationType.UNKNOWN
                    && event.isSkillEvent());
            if (!event.isActive()
                || !skillVerification
                || !matches(event.getTarget(), skillName)
                || !skillSubmissionAllowed(event.getEventId(), now))
            {
                continue;
            }
            synchronized (lastSkillSubmissions)
            {
                lastSkillSubmissions.put(event.getEventId(), now);
            }
            submitObservation(event, "SKILL_XP", event.getTarget(), experience);
        }
    }

    public void onLoot(String sourceName)
    {
        if (sourceName == null || sourceName.trim().isEmpty())
        {
            return;
        }
        for (ClanEventSummary event : currentEvents)
        {
            boolean bossVerification = event.getVerificationType()
                == VerificationType.NPC_KILL
                || (event.getVerificationType() == VerificationType.UNKNOWN
                    && event.isBossEvent());
            if (event.isActive()
                && bossVerification
                && matches(event.getTarget(), sourceName))
            {
                submitObservation(event, "BOSS_KILL", event.getTarget(), 1);
            }
        }
    }

    private boolean skillSubmissionAllowed(long eventId, Instant now)
    {
        synchronized (lastSkillSubmissions)
        {
            Instant last = lastSkillSubmissions.get(eventId);
            return last == null
                || Duration.between(last, now)
                    .compareTo(SKILL_SUBMISSION_INTERVAL) >= 0;
        }
    }

    private void submitObservation(
        ClanEventSummary event,
        String metricType,
        String target,
        int value)
    {
        String rsn = rsnSupplier.get();
        if (rsn == null || rsn.trim().isEmpty())
        {
            return;
        }
        apiClient.submitObservation(
            event,
            rsn,
            metricType,
            target,
            value).thenAccept(result -> SwingUtilities.invokeLater(() ->
            {
                if (running)
                {
                    panel.showObservation(
                        result.isRecorded(),
                        event.getName(),
                        target,
                        result.getMessage());
                }
            }));
    }

    private static boolean matches(String expected, String actual)
    {
        return expected != null && actual != null
            && normalize(expected).equals(normalize(actual));
    }

    private static String normalize(String value)
    {
        return value.replace('_', ' ').trim().toLowerCase(Locale.ENGLISH);
    }
}

package com.clanhq.verifier.event;

import com.clanhq.verifier.event.model.ClanEventSummary;
import java.awt.BorderLayout;
import java.awt.Component;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.time.Instant;
import java.time.LocalDate;
import java.time.format.DateTimeFormatter;
import java.time.ZoneId;
import java.util.List;
import java.util.Locale;
import javax.swing.BorderFactory;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.JButton;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JScrollPane;
import net.runelite.client.ui.ColorScheme;

final class EventPanel extends JPanel
{
    private static final int WRAP_WIDTH = 190;
    private static final DateTimeFormatter DATE_FORMAT =
        DateTimeFormatter.ofPattern("MMM d, yyyy");
    private static final DateTimeFormatter DATE_TIME_FORMAT =
        DateTimeFormatter.ofPattern("MMM d, yyyy '@' h:mm a", Locale.ENGLISH)
            .withZone(ZoneId.systemDefault());
    private static final Color ACTIVE_COLOR = new Color(112, 194, 130);
    private static final Color SCHEDULED_COLOR = new Color(111, 166, 224);
    private static final Color BINGO_COLOR = new Color(178, 137, 224);
    private String serverName = "ClanHQ";
    private final JLabel titleLabel = new JLabel("ClanHQ Events");
    private final JLabel subtitleLabel = new JLabel();
    private final JLabel statusLabel = new JLabel();
    private final JPanel eventsPanel = verticalPanel();
    private final JButton refreshButton = new JButton("Refresh Events");

    EventPanel(Runnable refreshAction)
    {
        setLayout(new BorderLayout());
        setBorder(BorderFactory.createEmptyBorder(10, 10, 10, 10));
        setBackground(ColorScheme.DARK_GRAY_COLOR);

        JPanel content = verticalPanel();
        content.setBorder(BorderFactory.createEmptyBorder(0, 0, 4, 0));
        content.add(titleLabel);
        titleLabel.setFont(titleLabel.getFont().deriveFont(Font.BOLD, 14f));
        titleLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
        subtitleLabel.setText(html("Live events in your ClanHQ clan."));
        subtitleLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
        content.add(Box.createRigidArea(new Dimension(0, 3)));
        content.add(subtitleLabel);
        content.add(Box.createRigidArea(new Dimension(0, 12)));
        content.add(sectionLabel("CURRENT EVENTS"));
        content.add(Box.createRigidArea(new Dimension(0, 6)));
        content.add(eventsPanel);
        content.add(Box.createRigidArea(new Dimension(0, 12)));
        refreshButton.addActionListener(event -> refreshAction.run());
        refreshButton.setAlignmentX(Component.LEFT_ALIGNMENT);
        content.add(refreshButton);
        content.add(Box.createRigidArea(new Dimension(0, 10)));
        statusLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
        statusLabel.setBorder(BorderFactory.createCompoundBorder(
            BorderFactory.createMatteBorder(
                1, 0, 0, 0, ColorScheme.MEDIUM_GRAY_COLOR),
            BorderFactory.createEmptyBorder(8, 0, 0, 0)));
        content.add(statusLabel);

        JScrollPane scroll = new JScrollPane(content,
            JScrollPane.VERTICAL_SCROLLBAR_NEVER,
            JScrollPane.HORIZONTAL_SCROLLBAR_NEVER);
        scroll.setBorder(null);
        scroll.setBackground(ColorScheme.DARK_GRAY_COLOR);
        scroll.getViewport().setBackground(ColorScheme.DARK_GRAY_COLOR);
        scroll.getVerticalScrollBar().setUnitIncrement(16);
        add(scroll, BorderLayout.CENTER);
        showStatus("Loading current events...");
    }

    void setLoading()
    {
        refreshButton.setEnabled(false);
        showStatus("Loading current events...");
    }

    void showEvents(String serverName, List<ClanEventSummary> events)
    {
        if (serverName != null && !serverName.trim().isEmpty())
        {
            this.serverName = serverName.trim();
        }
        titleLabel.setText(this.serverName + " Events");
        refreshButton.setEnabled(true);
        eventsPanel.removeAll();
        if (events.isEmpty())
        {
            eventsPanel.add(emptyState("No scheduled or active events."));
        }
        else
        {
            for (ClanEventSummary event : events)
            {
                eventsPanel.add(eventPanel(event));
                eventsPanel.add(Box.createRigidArea(new Dimension(0, 9)));
            }
        }
        showStatus(events.size() + " current event"
            + (events.size() == 1 ? "" : "s") + ".");
        eventsPanel.revalidate();
        eventsPanel.repaint();
    }

    void showError(String message)
    {
        titleLabel.setText(serverName + " Events");
        refreshButton.setEnabled(true);
        eventsPanel.removeAll();
        eventsPanel.add(emptyState("Events unavailable."));
        eventsPanel.revalidate();
        eventsPanel.repaint();
        showStatus(message);
    }

    void showObservation(
        boolean recorded,
        String eventName,
        String target,
        String message)
    {
        showStatus((recorded ? "Recorded: " : "Failed: ")
            + eventName + " — " + target);
    }

    private JPanel eventPanel(ClanEventSummary event)
    {
        Color accent = accentFor(event);
        JPanel panel = new JPanel(new BorderLayout(8, 0));
        panel.setOpaque(true);
        panel.setBackground(ColorScheme.DARKER_GRAY_COLOR);
        panel.setBorder(BorderFactory.createCompoundBorder(
            BorderFactory.createLineBorder(accent, event.isActive() ? 2 : 1),
            BorderFactory.createEmptyBorder(8, 8, 8, 8)));

        JPanel details = verticalPanel(ColorScheme.DARKER_GRAY_COLOR);
        JLabel name = new JLabel(html("<b>" + escapeHtml(event.getName())
            + "</b>"));
        name.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
        details.add(name);
        details.add(Box.createRigidArea(new Dimension(0, 4)));
        JLabel status = new JLabel(displayValue(event.getStatus()));
        status.setForeground(accent);
        status.setFont(status.getFont().deriveFont(Font.BOLD, 14f));
        details.add(status);
        details.add(Box.createRigidArea(new Dimension(0, 5)));
        String target = event.getTarget() == null
            ? "No target" : event.getTarget();
        details.add(new JLabel(html("<b>Target</b><br>"
            + escapeHtml(target))));
        details.add(Box.createRigidArea(new Dimension(0, 5)));
        details.add(new JLabel(html("<b>Start</b><br>"
            + formatDateTime(event.getStartAt(), event.getStartDate()))));
        details.add(Box.createRigidArea(new Dimension(0, 5)));
        details.add(new JLabel(html("<b>End</b><br>"
            + formatDateTime(event.getEndAt(), event.getEndDate()))));
        panel.add(details, BorderLayout.CENTER);
        panel.setAlignmentX(Component.LEFT_ALIGNMENT);
        panel.setMaximumSize(new Dimension(
            WRAP_WIDTH + 20, panel.getPreferredSize().height));
        return panel;
    }

    private static JPanel emptyState(String message)
    {
        JPanel panel = new JPanel(new BorderLayout());
        panel.setBackground(ColorScheme.DARKER_GRAY_COLOR);
        panel.setBorder(BorderFactory.createCompoundBorder(
            BorderFactory.createLineBorder(ColorScheme.MEDIUM_GRAY_COLOR),
            BorderFactory.createEmptyBorder(10, 10, 10, 10)));
        JLabel label = new JLabel(html(message));
        label.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
        panel.add(label, BorderLayout.CENTER);
        return panel;
    }

    private static JLabel sectionLabel(String text)
    {
        JLabel label = new JLabel(text);
        label.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
        label.setFont(label.getFont().deriveFont(Font.BOLD, 10f));
        return label;
    }

    private static Color accentFor(ClanEventSummary event)
    {
        if ("BINGO".equals(event.getEventType()))
        {
            return BINGO_COLOR;
        }
        return event.isActive() ? ACTIVE_COLOR : SCHEDULED_COLOR;
    }

    private void showStatus(String message)
    {
        statusLabel.setText("<html><body style='width: " + WRAP_WIDTH
            + "px'>" + escapeHtml(message) + "</body></html>");
    }

    private static String displayValue(String value)
    {
        if (value == null || value.isEmpty())
        {
            return "Unknown";
        }
        String normalized = value.toLowerCase().replace('_', ' ');
        return Character.toUpperCase(normalized.charAt(0))
            + normalized.substring(1);
    }

    private static String formatDateTime(Instant instant, LocalDate fallback)
    {
        return instant == null ? DATE_FORMAT.format(fallback)
            : DATE_TIME_FORMAT.format(instant);
    }

    private static String html(String text)
    {
        return "<html><body style='width: " + WRAP_WIDTH + "px'>"
            + text + "</body></html>";
    }

    private static String escapeHtml(String text)
    {
        return text.replace("&", "&amp;")
            .replace("<", "&lt;")
            .replace(">", "&gt;");
    }

    private static JPanel verticalPanel()
    {
        return verticalPanel(ColorScheme.DARK_GRAY_COLOR);
    }

    private static JPanel verticalPanel(Color background)
    {
        JPanel panel = new JPanel();
        panel.setLayout(new BoxLayout(panel, BoxLayout.Y_AXIS));
        panel.setBackground(background);
        panel.setAlignmentX(Component.LEFT_ALIGNMENT);
        return panel;
    }
}

package com.clanhq.verifier.event.model;

import com.clanhq.verifier.task.VerificationType;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import java.time.Instant;
import java.time.LocalDate;

public final class ClanEventSummary
{
    private final long eventId;
    private final String eventType;
    private final String name;
    private final String target;
    private final LocalDate startDate;
    private final LocalDate endDate;
    private final Instant startAt;
    private final Instant endAt;
    private final String status;
    private final String eventCode;
    private final String serverName;
    private final VerificationType verificationType;

    public ClanEventSummary(long eventId, String eventType, String name,
        String target, LocalDate startDate, LocalDate endDate, String status,
        String eventCode, String serverName)
    {
        this(eventId, eventType, name, target, startDate, endDate, status,
            eventCode, null, null, serverName, null);
    }

    public ClanEventSummary(long eventId, String eventType, String name,
        String target, LocalDate startDate, LocalDate endDate, String status,
        String eventCode, Instant startAt, Instant endAt, String serverName)
    {
        this(eventId, eventType, name, target, startDate, endDate, status,
            eventCode, startAt, endAt, serverName, null);
    }

    public ClanEventSummary(long eventId, String eventType, String name,
        String target, LocalDate startDate, LocalDate endDate, String status,
        String eventCode, Instant startAt, Instant endAt, String serverName,
        VerificationType verificationType)
    {
        this.eventId = eventId;
        this.eventType = eventType;
        this.name = name;
        this.target = target;
        this.startDate = startDate;
        this.endDate = endDate;
        this.startAt = startAt;
        this.endAt = endAt;
        this.status = status;
        this.eventCode = eventCode;
        this.serverName = serverName;
        this.verificationType = verificationType == null
            ? VerificationType.UNKNOWN : verificationType;
    }

    public static ClanEventSummary fromJson(String json)
    {
        JsonObject value = new JsonParser().parse(json).getAsJsonObject();
        // The event-list envelope carries the API schema version. Older
        // servers did not repeat that field on every event, so accept both
        // shapes while still rejecting an explicitly unsupported version.
        if (value.has("schema_version")
            && !value.get("schema_version").isJsonNull()
            && value.get("schema_version").getAsInt() != 1)
        {
            throw new IllegalArgumentException("Unsupported event response");
        }
        Instant startAt = value.has("start_at")
            && !value.get("start_at").isJsonNull()
            ? Instant.parse(value.get("start_at").getAsString()) : null;
        Instant endAt = value.has("end_at")
            && !value.get("end_at").isJsonNull()
            ? Instant.parse(value.get("end_at").getAsString()) : null;
        String eventType = value.get("event_type").getAsString();
        VerificationType verificationType = value.has("verification")
            && value.get("verification").isJsonObject()
                ? VerificationType.from(value.getAsJsonObject("verification")
                    .has("type")
                        ? value.getAsJsonObject("verification").get("type")
                            .getAsString() : null)
                : VerificationType.from(eventType.startsWith("SKILL_")
                    ? "SKILL_XP" : eventType.startsWith("BOSS_")
                        ? "NPC_KILL" : null);
        return new ClanEventSummary(
            value.get("event_id").getAsLong(),
            eventType,
            value.get("name").getAsString(),
            value.has("target") && !value.get("target").isJsonNull()
                ? value.get("target").getAsString() : null,
            LocalDate.parse(value.get("start_date").getAsString()),
            LocalDate.parse(value.get("end_date").getAsString()),
            value.get("status").getAsString(),
            value.has("event_code") && !value.get("event_code").isJsonNull()
                ? value.get("event_code").getAsString() : "",
            startAt,
            endAt,
            value.has("server_name") && !value.get("server_name").isJsonNull()
                ? value.get("server_name").getAsString() : "ClanHQ",
            verificationType);
    }

    public long getEventId() { return eventId; }
    public String getEventType() { return eventType; }
    public String getName() { return name; }
    public String getTarget() { return target; }
    public LocalDate getStartDate() { return startDate; }
    public LocalDate getEndDate() { return endDate; }
    public Instant getStartAt() { return startAt; }
    public Instant getEndAt() { return endAt; }
    public String getStatus() { return status; }
    public String getEventCode() { return eventCode; }
    public String getServerName() { return serverName; }
    public VerificationType getVerificationType() { return verificationType; }

    public boolean isActive()
    {
        return "ACTIVE".equals(status);
    }

    public boolean isSkillEvent()
    {
        return eventType.startsWith("SKILL_");
    }

    public boolean isBossEvent()
    {
        return eventType.startsWith("BOSS_");
    }
}

package com.clanhq.verifier.event.model;

import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

public final class ClanEventsSnapshot
{
    private final List<ClanEventSummary> events;
    private final String serverName;

    private ClanEventsSnapshot(List<ClanEventSummary> events, String serverName)
    {
        this.events = Collections.unmodifiableList(new ArrayList<>(events));
        this.serverName = serverName;
    }

    public static ClanEventsSnapshot fromJson(String json)
    {
        JsonObject root = new JsonParser().parse(json).getAsJsonObject();
        if (!root.has("events") || !root.get("events").isJsonArray())
        {
            throw new IllegalArgumentException("Events response has no event list");
        }
        if (root.has("schema_version")
            && !root.get("schema_version").isJsonNull()
            && root.get("schema_version").getAsInt() != 1)
        {
            throw new IllegalArgumentException("Unsupported events response");
        }
        JsonArray values = root.getAsJsonArray("events");
        List<ClanEventSummary> events = new ArrayList<>();
        for (JsonElement element : values)
        {
            events.add(ClanEventSummary.fromJson(element.toString()));
        }
        return new ClanEventsSnapshot(
            events,
            root.has("server_name") && !root.get("server_name").isJsonNull()
                ? root.get("server_name").getAsString() : "ClanHQ");
    }

    public List<ClanEventSummary> getEvents() { return events; }
    public String getServerName() { return serverName; }
}

package com.clanhq.verifier.event.transport;

import com.clanhq.verifier.ClanHQVerifierConfig;
import com.clanhq.verifier.event.model.ClanEventSummary;
import com.clanhq.verifier.event.model.ClanEventsSnapshot;
import com.clanhq.verifier.service.ApiDestinationService;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import java.io.IOException;
import java.util.concurrent.CompletableFuture;
import java.time.Instant;
import java.util.UUID;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.MediaType;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;
import okhttp3.Response;

public final class EventApiClient
{
    /** Capabilities with an implemented RuneLite observation source. */
    private static final String CAPABILITIES =
        "SKILL_XP,NPC_KILL,ITEM_DROP";
    private static final MediaType JSON =
        MediaType.parse("application/json; charset=utf-8");
    private final OkHttpClient httpClient;
    private final ClanHQVerifierConfig config;
    private final ApiDestinationService destinationService;

    public EventApiClient(OkHttpClient httpClient, ClanHQVerifierConfig config,
        ApiDestinationService destinationService)
    {
        this.httpClient = httpClient;
        this.config = config;
        this.destinationService = destinationService;
    }

    public CompletableFuture<EventListResult> fetchEvents()
    {
        CompletableFuture<EventListResult> future = new CompletableFuture<>();
        String baseUrl = destinationService.normalize(config.apiBaseUrl());
        String token = normalized(config.installationToken());
        if (baseUrl == null || token.isEmpty())
        {
            future.complete(new EventListResult(null,
                "Pair this RuneLite installation to load ClanHQ events."));
            return future;
        }
        Request request = new Request.Builder()
            .url(baseUrl + "/api/v1/events")
            .header("Authorization", "Bearer " + token)
            .header("X-ClanHQ-Plugin-Version", "1")
            .header("X-ClanHQ-Plugin-Capabilities", CAPABILITIES)
            .get()
            .build();
        httpClient.newCall(request).enqueue(new Callback()
        {
            @Override
            public void onFailure(Call call, IOException exception)
            {
                future.complete(new EventListResult(null,
                    "ClanHQ could not be reached."));
            }

            @Override
            public void onResponse(Call call, Response response)
                throws IOException
            {
                try (Response closeable = response)
                {
                    String body = response.body() == null
                        ? "" : response.body().string();
                    if (!response.isSuccessful())
                    {
                        future.complete(new EventListResult(null,
                            responseMessage(body, response.code())));
                        return;
                    }
                    future.complete(new EventListResult(
                        ClanEventsSnapshot.fromJson(body),
                        "ClanHQ events loaded."));
                }
                catch (IOException | RuntimeException exception)
                {
                    future.complete(new EventListResult(null,
                        "ClanHQ returned invalid event information."));
                }
            }
        });
        return future;
    }

    public CompletableFuture<EventJoinResult> joinEvent(
        ClanEventSummary event,
        String rsn)
    {
        return joinEventCode(event.getEventCode(), rsn);
    }

    public CompletableFuture<EventJoinResult> joinEventCode(
        String eventCode,
        String rsn)
    {
        CompletableFuture<EventJoinResult> future = new CompletableFuture<>();
        String baseUrl = destinationService.normalize(config.apiBaseUrl());
        String token = normalized(config.installationToken());
        if (baseUrl == null || token.isEmpty() || normalized(rsn).isEmpty())
        {
            future.complete(new EventJoinResult(false,
                "Log in and configure the ClanHQ connection first.", null));
            return future;
        }
        JsonObject payload = new JsonObject();
        payload.addProperty("event_code", eventCode);
        payload.addProperty("rsn", rsn.trim());
        Request request = new Request.Builder()
            .url(baseUrl + "/api/v1/events/join")
            .header("Authorization", "Bearer " + token)
            .header("X-ClanHQ-Plugin-Version", "1")
            .header("X-ClanHQ-Plugin-Capabilities", CAPABILITIES)
            .post(RequestBody.create(JSON, payload.toString()))
            .build();
        httpClient.newCall(request).enqueue(new Callback()
        {
            @Override
            public void onFailure(Call call, IOException exception)
            {
                future.complete(new EventJoinResult(false,
                    "ClanHQ could not register event participation.", null));
            }

            @Override
            public void onResponse(Call call, Response response)
                throws IOException
            {
                try (Response closeable = response)
                {
                    String body = response.body() == null
                        ? "" : response.body().string();
                    JsonObject value = parseObject(body);
                    String team = value != null && value.has("team")
                        && !value.get("team").isJsonNull()
                            ? value.get("team").getAsString() : null;
                    future.complete(new EventJoinResult(
                        response.isSuccessful(),
                        responseMessage(body, response.code()),
                        team));
                }
                catch (IOException | RuntimeException exception)
                {
                    future.complete(new EventJoinResult(false,
                        "ClanHQ returned an invalid join response.", null));
                }
            }
        });
        return future;
    }

    public CompletableFuture<EventObservationResult> submitObservation(
        ClanEventSummary event,
        String rsn,
        String metricType,
        String target,
        int value)
    {
        CompletableFuture<EventObservationResult> future =
            new CompletableFuture<>();
        String baseUrl = destinationService.normalize(config.apiBaseUrl());
        String token = normalized(config.installationToken());
        if (baseUrl == null || token.isEmpty() || normalized(rsn).isEmpty())
        {
            future.complete(new EventObservationResult(false,
                "ClanHQ connection is not ready."));
            return future;
        }
        JsonObject payload = new JsonObject();
        payload.addProperty("schema_version", 1);
        payload.addProperty("submission_id", UUID.randomUUID().toString());
        payload.addProperty("event_code", event.getEventCode());
        payload.addProperty("rsn", rsn.trim());
        payload.addProperty("metric_type", metricType);
        payload.addProperty("target", target);
        payload.addProperty("value", value);
        payload.addProperty("observed_at", Instant.now().toString());
        Request request = new Request.Builder()
            .url(baseUrl + "/api/v1/events/observations")
            .header("Authorization", "Bearer " + token)
            .header("X-ClanHQ-Plugin-Version", "1")
            .header("X-ClanHQ-Plugin-Capabilities", CAPABILITIES)
            .post(RequestBody.create(JSON, payload.toString()))
            .build();
        httpClient.newCall(request).enqueue(new Callback()
        {
            @Override
            public void onFailure(Call call, IOException exception)
            {
                future.complete(new EventObservationResult(false,
                    "ClanHQ could not record event progress."));
            }

            @Override
            public void onResponse(Call call, Response response)
                throws IOException
            {
                try (Response closeable = response)
                {
                    String body = response.body() == null
                        ? "" : response.body().string();
                    future.complete(new EventObservationResult(
                        response.isSuccessful(),
                        responseMessage(body, response.code())));
                }
                catch (IOException | RuntimeException exception)
                {
                    future.complete(new EventObservationResult(false,
                        "ClanHQ returned an invalid progress response."));
                }
            }
        });
        return future;
    }

    private static String normalized(String value)
    {
        return value == null ? "" : value.trim();
    }

    private static String responseMessage(String body, int status)
    {
        try
        {
            JsonObject value = new JsonParser().parse(body).getAsJsonObject();
            if (value.has("message"))
            {
                return value.get("message").getAsString();
            }
        }
        catch (RuntimeException ignored)
        {
            // Use the stable HTTP fallback below.
        }
        return "ClanHQ returned HTTP " + status;
    }

    private static JsonObject parseObject(String body)
    {
        try
        {
            return new JsonParser().parse(body).getAsJsonObject();
        }
        catch (RuntimeException exception)
        {
            return null;
        }
    }
}

