import java.util.Locale;
import java.util.Objects;

public final class BoatConfiguration
{
    private final int slot;
    private final String type;
    private final String hull;
    private final String sail;
    private final String steering;
    private final String keel;

    public BoatConfiguration(int slot, String type, String hull, String sail,
        String steering, String keel)
    {
        this.slot = slot;
        this.type = Objects.requireNonNull(type);
        this.hull = Objects.requireNonNull(hull);
        this.sail = Objects.requireNonNull(sail);
        this.steering = Objects.requireNonNull(steering);
        this.keel = Objects.requireNonNull(keel);
    }

    public int getSlot() { return slot; }
    public String getType() { return type; }
    public String getHull() { return hull; }
    public String getSail() { return sail; }
    public String getSteering() { return steering; }
    public String getKeel() { return keel; }

    public boolean isType(String expected)
    {
        return normalize(type).contains(normalize(expected));
    }

    public boolean isMaxedCore()
    {
        return normalize(hull).contains("rosewood")
            && normalize(sail).contains("rosewood")
            && normalize(steering).contains("dragon")
            && normalize(keel).contains("dragon");
    }

    public List<String> getMissingMaxedComponents()
    {
        List<String> missing = new ArrayList<>();
        addIfMissing(missing, "hull", hull, "rosewood");
        addIfMissing(missing, "mast and sails", sail, "rosewood");
        addIfMissing(missing, "helm", steering, "dragon");
        addIfMissing(missing, "keel", keel, "dragon");
        return missing;
    }

    public String toSummary()
    {
        return type + " (slot " + slot + "): hull=" + hull
            + ", mast/sails=" + sail + ", helm=" + steering
            + ", keel=" + keel;
    }

    private static void addIfMissing(List<String> missing, String label,
        String actual, String required)
    {
        if (!normalize(actual).contains(required))
        {
            missing.add(label + "=" + actual);
        }
    }

    private static String normalize(String value)
    {
        return value.toLowerCase(Locale.ENGLISH);
    }
}

package com.clanhq.verifier.model;

import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.Set;

public final class BoatEvidence
{
    private final Set<String> boatTypes;
    private final List<BoatConfiguration> configurations;
    private final List<String> visibleDetails;
    private final boolean captured;

    public BoatEvidence(Set<String> boatTypes, List<String> visibleDetails)
    {
        this(boatTypes, Collections.emptyList(), visibleDetails);
    }

    public BoatEvidence(Set<String> boatTypes,
        List<BoatConfiguration> configurations, List<String> visibleDetails)
    {
        this(boatTypes, configurations, visibleDetails, true);
    }

    private BoatEvidence(Set<String> boatTypes,
        List<BoatConfiguration> configurations, List<String> visibleDetails,
        boolean captured)
    {
        Set<String> types = new LinkedHashSet<>(
            Objects.requireNonNull(boatTypes));
        Objects.requireNonNull(configurations).stream()
            .map(BoatConfiguration::getType).forEach(types::add);
        this.boatTypes = Collections.unmodifiableSet(types);
        this.configurations = Collections.unmodifiableList(
            new ArrayList<>(configurations));
        this.visibleDetails = Collections.unmodifiableList(
            new ArrayList<>(Objects.requireNonNull(visibleDetails)));
        this.captured = captured;
    }

    public static BoatEvidence notCaptured()
    {
        return new BoatEvidence(Collections.emptySet(), Collections.emptyList(),
            Collections.emptyList(), false);
    }

    public static BoatEvidence capturedEmpty()
    {
        return new BoatEvidence(Collections.emptySet(), Collections.emptyList(),
            Collections.emptyList(), true);
    }

    public Set<String> getBoatTypes()
    {
        return boatTypes;
    }

    public List<BoatConfiguration> getConfigurations()
    {
        return configurations;
    }

    public List<String> getVisibleDetails()
    {
        return visibleDetails;
    }

    public boolean isCaptured()
    {
        return captured;
    }

    public boolean hasSkiffAndSloop()
    {
        return boatTypes.contains("Skiff") && boatTypes.contains("Sloop");
    }

    public boolean hasStructuredConfigurations()
    {
        return !configurations.isEmpty();
    }

    public boolean hasMaxedBoat(String type)
    {
        return configurations.stream()
            .anyMatch(boat -> boat.isType(type) && boat.isMaxedCore());
    }

    public BoatEvidence merge(BoatEvidence other)
    {
        Set<String> types = new LinkedHashSet<>(boatTypes);
        types.addAll(other.boatTypes);
        Map<Integer, BoatConfiguration> boats = new LinkedHashMap<>();
        configurations.forEach(boat -> boats.put(boat.getSlot(), boat));
        other.configurations.forEach(boat -> boats.put(boat.getSlot(), boat));
        Set<String> details = new LinkedHashSet<>(visibleDetails);
        details.addAll(other.visibleDetails);
        return new BoatEvidence(types, new ArrayList<>(boats.values()),
            new ArrayList<>(details), captured || other.captured);
    }

    public String toSummary()
    {
        if (!isCaptured())
        {
            return "Not captured";
        }
        if (configurations.isEmpty() && visibleDetails.isEmpty())
        {
            return "No owned boats found";
        }
        if (!configurations.isEmpty())
        {
            return configurations.stream().map(BoatConfiguration::toSummary)
                .collect(java.util.stream.Collectors.joining("; "));
        }
        String boats = boatTypes.isEmpty() ? "boat type not identified"
            : String.join(", ", boatTypes);
        return boats + "; " + visibleDetails.size() + " visible details";
    }
}

package com.clanhq.verifier.model;

import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.Locale;
import java.util.Map;

public final class CollectionLogEvidence
{
    private final Map<String, CollectionLogPageEvidence> pages;
    private final Integer obtainedSlotCount;

    public CollectionLogEvidence(Map<String, Map<String, Integer>> legacyPages)
    {
        Map<String, CollectionLogPageEvidence> converted = new LinkedHashMap<>();
        legacyPages.forEach((title, items) -> converted.put(title,
            new CollectionLogPageEvidence(title, items, items.size(), items.size())));
        this.pages = Collections.unmodifiableMap(converted);
        this.obtainedSlotCount = null;
    }

    private CollectionLogEvidence(Map<String, CollectionLogPageEvidence> pages,
        Integer obtainedSlotCount)
    {
        this.pages = Collections.unmodifiableMap(new LinkedHashMap<>(pages));
        this.obtainedSlotCount = obtainedSlotCount;
    }

    public static CollectionLogEvidence empty()
    {
        return new CollectionLogEvidence(Collections.emptyMap(), null);
    }

    public static CollectionLogEvidence page(String title,
        Map<String, Integer> acquiredItems, int acquiredSlots, int totalSlots)
    {
        CollectionLogPageEvidence page = new CollectionLogPageEvidence(
            title, acquiredItems, acquiredSlots, totalSlots);
        return new CollectionLogEvidence(Collections.singletonMap(title, page),
            null);
    }

    public static CollectionLogEvidence slotCount(int obtainedSlots)
    {
        return new CollectionLogEvidence(Collections.emptyMap(), obtainedSlots);
    }

    public CollectionLogEvidence merge(CollectionLogEvidence other)
    {
        Map<String, CollectionLogPageEvidence> merged = new LinkedHashMap<>(pages);
        merged.putAll(other.pages);
        return new CollectionLogEvidence(merged,
            other.obtainedSlotCount == null ? obtainedSlotCount
                : other.obtainedSlotCount);
    }

    public Integer getObtainedSlotCount() { return obtainedSlotCount; }
    public boolean isCaptured()
    {
        return !pages.isEmpty() || obtainedSlotCount != null;
    }

    public boolean hasPage(String pageFragment)
    {
        return findPage(pageFragment) != null;
    }

    public boolean isPageGreenLogged(String pageFragment)
    {
        CollectionLogPageEvidence page = findPage(pageFragment);
        return page != null && page.isGreenLogged();
    }

    public CollectionLogPageEvidence getPage(String pageFragment)
    {
        return findPage(pageFragment);
    }

    public boolean hasAcquiredItem(String pageFragment, String itemFragment)
    {
        CollectionLogPageEvidence page = findPage(pageFragment);
        return page != null && hasName(page.getAcquiredItems(), itemFragment);
    }

    public boolean hasDoomUniques()
    {
        CollectionLogPageEvidence page = findPage("doom");
        return page != null
            && hasName(page.getAcquiredItems(), "cloth")
            && (hasName(page.getAcquiredItems(), "boots")
                || hasName(page.getAcquiredItems(), "treads"))
            && hasName(page.getAcquiredItems(), "eye");
    }

    public String toSummary()
    {
        StringBuilder summary = new StringBuilder();
        if (obtainedSlotCount != null)
        {
            appendSeparator(summary);
            summary.append(obtainedSlotCount).append(" slots");
        }
        for (CollectionLogPageEvidence page : pages.values())
        {
            appendSeparator(summary);
            summary.append(page.toSummary());
        }
        return summary.length() == 0 ? "No Collection Log evidence" : summary.toString();
    }

    private CollectionLogPageEvidence findPage(String fragment)
    {
        String expected = normalize(fragment);
        return pages.entrySet().stream()
            .filter(entry -> normalize(entry.getKey()).contains(expected))
            .map(Map.Entry::getValue)
            .findFirst().orElse(null);
    }

    private static boolean hasName(Map<String, Integer> items, String fragment)
    {
        String expected = normalize(fragment);
        return items.entrySet().stream().anyMatch(entry -> entry.getValue() > 0
            && normalize(entry.getKey()).contains(expected));
    }

    private static void appendSeparator(StringBuilder summary)
    {
        if (summary.length() > 0)
        {
            summary.append("; ");
        }
    }

    private static String normalize(String value)
    {
        return value.toLowerCase(Locale.ENGLISH);
    }
}

