package com.clanhq.verifier.service;

import java.net.URI;
import java.net.URISyntaxException;
import java.util.Locale;
import javax.inject.Inject;

public final class ApiDestinationService
{
    @Inject
    public ApiDestinationService()
    {
    }

    public String describe(String configuredUrl)
    {
        String normalized = normalize(configuredUrl);
        if (normalized == null)
        {
            return configuredUrl == null || configuredUrl.trim().isEmpty()
                ? "API: Not configured"
                : "API: Invalid destination";
        }
        try
        {
            URI uri = new URI(normalized);
            String destination = uri.getHost();
            if (uri.getPort() >= 0)
            {
                destination += ":" + uri.getPort();
            }
            return "Submits to: " + destination;
        }
        catch (URISyntaxException exception)
        {
            return "API: Invalid destination";
        }
    }

    public String normalize(String configuredUrl)
    {
        if (configuredUrl == null || configuredUrl.trim().isEmpty())
        {
            return null;
        }
        try
        {
            URI uri = new URI(configuredUrl.trim());
            String scheme = uri.getScheme() == null ? ""
                : uri.getScheme().toLowerCase(Locale.ENGLISH);
            String host = uri.getHost();
            if (host == null || uri.getUserInfo() != null
                || uri.getQuery() != null || uri.getFragment() != null)
            {
                return null;
            }
            boolean localhost = host.equalsIgnoreCase("localhost")
                || host.equals("127.0.0.1") || host.equals("::1");
            if (!scheme.equals("https") && !(scheme.equals("http") && localhost))
            {
                return null;
            }
            String normalized = uri.toString();
            while (normalized.endsWith("/"))
            {
                normalized = normalized.substring(0, normalized.length() - 1);
            }
            return normalized;
        }
        catch (URISyntaxException exception)
        {
            return null;
        }
    }
}

package com.clanhq.verifier.service;

import com.clanhq.verifier.model.BoatEvidence;
import com.clanhq.verifier.model.BoatConfiguration;
import java.util.ArrayList;
import java.util.Collections;
import java.util.IdentityHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Locale;
import java.util.Set;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.DBTableID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.widgets.Widget;

public final class BoatCaptureService
{
    private static final int[] OWNED = {VarbitID.SAILING_BOAT_1_OWNED,
        VarbitID.SAILING_BOAT_2_OWNED, VarbitID.SAILING_BOAT_3_OWNED,
        VarbitID.SAILING_BOAT_4_OWNED, VarbitID.SAILING_BOAT_5_OWNED};
    private static final int[] TYPES = {VarbitID.SAILING_BOAT_1_TYPE,
        VarbitID.SAILING_BOAT_2_TYPE, VarbitID.SAILING_BOAT_3_TYPE,
        VarbitID.SAILING_BOAT_4_TYPE, VarbitID.SAILING_BOAT_5_TYPE};
    private static final int[] HULLS = {VarbitID.SAILING_BOAT_1_HULL,
        VarbitID.SAILING_BOAT_2_HULL, VarbitID.SAILING_BOAT_3_HULL,
        VarbitID.SAILING_BOAT_4_HULL, VarbitID.SAILING_BOAT_5_HULL};
    private static final int[] SAILS = {VarbitID.SAILING_BOAT_1_SAIL,
        VarbitID.SAILING_BOAT_2_SAIL, VarbitID.SAILING_BOAT_3_SAIL,
        VarbitID.SAILING_BOAT_4_SAIL, VarbitID.SAILING_BOAT_5_SAIL};
    private static final int[] STEERING = {VarbitID.SAILING_BOAT_1_STEERING,
        VarbitID.SAILING_BOAT_2_STEERING, VarbitID.SAILING_BOAT_3_STEERING,
        VarbitID.SAILING_BOAT_4_STEERING, VarbitID.SAILING_BOAT_5_STEERING};
    private static final int[] KEELS = {VarbitID.SAILING_BOAT_1_KEEL,
        VarbitID.SAILING_BOAT_2_KEEL, VarbitID.SAILING_BOAT_3_KEEL,
        VarbitID.SAILING_BOAT_4_KEEL, VarbitID.SAILING_BOAT_5_KEEL};
    private final Client client;

    @Inject
    public BoatCaptureService(Client client)
    {
        this.client = client;
    }

    public BoatEvidence captureVisiblePanel()
    {
        Set<String> text = new LinkedHashSet<>();
        Set<Widget> visited = Collections.newSetFromMap(new IdentityHashMap<>());
        collectVisibleInterface(
            client.getWidget(InterfaceID.SailingBoatSelection.FRAME),
            visited, text);
        collectVisibleInterface(
            client.getWidget(InterfaceID.SailingCustomisation.FRAME),
            visited, text);
        List<BoatConfiguration> configurations = captureOwnedBoats();
        if (text.isEmpty() && configurations.isEmpty())
        {
            throw new IllegalStateException(
                "No owned Sailing boat records were available. Open Boat "
                    + "Customisation and try again.");
        }

        return new BoatEvidence(inferBoatTypes(text), configurations,
            new ArrayList<>(text));
    }

    public BoatEvidence captureStoredEvidence()
    {
        List<BoatConfiguration> configurations = captureOwnedBoats();
        return configurations.isEmpty()
            ? BoatEvidence.capturedEmpty()
            : new BoatEvidence(Collections.emptySet(), configurations,
                Collections.emptyList());
    }

    private List<BoatConfiguration> captureOwnedBoats()
    {
        List<BoatConfiguration> boats = new ArrayList<>();
        for (int index = 0; index < OWNED.length; index++)
        {
            if (client.getVarbitValue(OWNED[index]) <= 0)
            {
                continue;
            }
            boats.add(new BoatConfiguration(index + 1,
                readBoatType(client.getVarbitValue(TYPES[index])),
                readComponent(client.getVarbitValue(HULLS[index]),
                    DBTableID.SailingBoatHull.ID,
                    DBTableID.SailingBoatHull.COL_NAME, "hull"),
                readComponent(client.getVarbitValue(SAILS[index]),
                    DBTableID.SailingBoatSail.ID,
                    DBTableID.SailingBoatSail.COL_NAME, "mast and sails"),
                readComponent(client.getVarbitValue(STEERING[index]),
                    DBTableID.SailingBoatSteering.ID,
                    DBTableID.SailingBoatSteering.COL_NAME, "helm"),
                readComponent(client.getVarbitValue(KEELS[index]),
                    DBTableID.SailingBoatKeel.ID,
                    DBTableID.SailingBoatKeel.COL_NAME, "keel")));
        }
        return boats;
    }

    private String readBoatType(int rowId)
    {
        List<Integer> rows;
        try
        {
            rows = client.getDBRowsByValue(DBTableID.SailingBoat.ID,
                DBTableID.SailingBoat.COL_TYPE_ID, 0, rowId);
        }
        catch (RuntimeException exception)
        {
            rows = Collections.emptyList();
        }
        int resolvedRow = rows == null || rows.isEmpty() ? rowId : rows.get(0);
        String name = readDatabaseName(resolvedRow,
            DBTableID.SailingBoat.COL_DISPLAYNAME);
        if (name == null)
        {
            name = readDatabaseName(resolvedRow,
                DBTableID.SailingBoat.COL_NAME);
        }
        return name == null ? "Unknown boat row " + rowId : name;
    }

    private String readComponent(int encodedValue, int tableId,
        int nameColumn, String label)
    {
        String name = null;
        List<Integer> rows;
        try
        {
            rows = client.getDBTableRows(tableId);
        }
        catch (RuntimeException exception)
        {
            rows = Collections.emptyList();
        }
        if (rows != null && encodedValue >= 0 && encodedValue < rows.size())
        {
            name = readDatabaseName(rows.get(encodedValue), nameColumn);
        }
        if (name == null)
        {
            name = readDatabaseName(encodedValue, nameColumn);
        }
        return name == null ? "Unknown " + label + " value " + encodedValue
            : name;
    }

    private String readDatabaseName(int rowId, int nameColumn)
    {
        Object[] values;
        try
        {
            values = client.getDBTableField(rowId, nameColumn, 0);
        }
        catch (RuntimeException exception)
        {
            return null;
        }
        if (values == null)
        {
            return null;
        }
        for (Object value : values)
        {
            if (value instanceof String && !((String) value).trim().isEmpty())
            {
                return ((String) value).replaceAll("<[^>]*>", "").trim();
            }
        }
        return null;
    }

    static Set<String> inferBoatTypes(Iterable<String> text)
    {
        Set<String> types = new LinkedHashSet<>();
        for (String line : text)
        {
            String normalized = line.toLowerCase(Locale.ENGLISH);
            if (normalized.contains("skiff")
                || normalized.matches(".*boat size:\\s*small(?:\\s|\\().*"))
            {
                types.add("Skiff");
            }
            if (normalized.contains("sloop")
                || normalized.matches(".*boat size:\\s*medium(?:\\s|\\().*"))
            {
                types.add("Sloop");
            }
        }
        return types;
    }

    private void collectVisibleInterface(Widget root, Set<Widget> visited,
        Set<String> text)
    {
        if (root == null || root.isHidden())
        {
            return;
        }
        collectText(root, visited, text);
    }

    private void collectText(Widget widget, Set<Widget> visited, Set<String> text)
    {
        if (widget == null || widget.isHidden() || !visited.add(widget))
        {
            return;
        }
        addText(text, widget.getText());
        addText(text, widget.getName());
        collectChildren(widget.getChildren(), visited, text);
        collectChildren(widget.getDynamicChildren(), visited, text);
        collectChildren(widget.getStaticChildren(), visited, text);
        collectChildren(widget.getNestedChildren(), visited, text);
    }

    private void collectChildren(Widget[] children, Set<Widget> visited,
        Set<String> text)
    {
        if (children == null)
        {
            return;
        }
        for (Widget child : children)
        {
            collectText(child, visited, text);
        }
    }

    private static void addText(Set<String> text, String value)
    {
        String clean = value == null ? ""
            : value.replaceAll("<[^>]*>", "").trim();
        if (!clean.isEmpty() && !clean.equalsIgnoreCase("null"))
        {
            text.add(clean);
        }
    }
}

package com.clanhq.verifier.service;

import com.clanhq.verifier.model.CollectionLogEvidence;
import java.util.Collections;
import java.util.IdentityHashMap;
import java.util.LinkedHashMap;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;

public final class CollectionLogCaptureService
{
    private static final Pattern SLOT_FRACTION = Pattern.compile(
        "([0-9][0-9,]*)\\s*(?:/|of)\\s*[0-9][0-9,]*",
        Pattern.CASE_INSENSITIVE);
    private final Client client;

    @Inject
    public CollectionLogCaptureService(Client client)
    {
        this.client = client;
    }

    public CollectionLogEvidence capturePage(String expectedPageTitle)
    {
        Widget frame = client.getWidget(InterfaceID.Collection.FRAME);
        Widget header = client.getWidget(InterfaceID.Collection.HEADER_TEXT);
        Widget headerContainer = client.getWidget(InterfaceID.Collection.HEADER);
        Widget main = client.getWidget(InterfaceID.Collection.MAIN);
        Widget itemsContainer = client.getWidget(
            InterfaceID.Collection.ITEMS_CONTENTS);
        Widget items = client.getWidget(InterfaceID.Collection.ITEMS);
        if (frame == null || frame.isHidden()
            || (itemsContainer == null && items == null))
        {
            throw new IllegalStateException(
                "Open the Collection Log to the required page before capturing.");
        }
        String pageTitle = firstKnownPageTitle(header, headerContainer, main);
        if (pageTitle == null)
        {
            throw new IllegalStateException(
                "Open a supported Doom or raid Collection Log page.");
        }
        if (!pageTitle.equals(expectedPageTitle))
        {
            throw new IllegalStateException("Open the " + expectedPageTitle
                + " Collection Log page before capturing.");
        }

        PageScan scan = new PageScan();
        Set<Widget> visited = Collections.newSetFromMap(new IdentityHashMap<>());
        scan(itemsContainer, visited, scan);
        scan(items, visited, scan);
        if (scan.visibleItemCount == 0)
        {
            throw new IllegalStateException(
                "The Collection Log page has not finished loading.");
        }
        CollectionLogEvidence page = CollectionLogEvidence.page(pageTitle,
            scan.items, scan.acquiredSlotCount, scan.visibleItemCount);
        Integer obtainedSlots = parseObtainedSlots(readVisibleText(frame));
        return obtainedSlots == null ? page : page.merge(
            CollectionLogEvidence.slotCount(obtainedSlots));
    }

    private String firstKnownPageTitle(Widget... candidates)
    {
        for (Widget candidate : candidates)
        {
            if (candidate == null || candidate.isHidden())
            {
                continue;
            }
            String title = knownPageTitle(readVisibleText(candidate));
            if (title != null)
            {
                return title;
            }
        }
        return null;
    }

    private String readVisibleText(Widget root)
    {
        StringBuilder text = new StringBuilder();
        Set<Widget> visited = Collections.newSetFromMap(new IdentityHashMap<>());
        appendVisibleText(root, visited, text);
        return text.toString();
    }

    private void appendVisibleText(Widget widget, Set<Widget> visited,
        StringBuilder text)
    {
        if (widget == null || widget.isHidden() || !visited.add(widget))
        {
            return;
        }
        text.append(' ').append(clean(widget.getText()));
        text.append(' ').append(clean(widget.getName()));
        appendChildrenText(widget.getChildren(), visited, text);
        appendChildrenText(widget.getDynamicChildren(), visited, text);
        appendChildrenText(widget.getStaticChildren(), visited, text);
        appendChildrenText(widget.getNestedChildren(), visited, text);
    }

    private void appendChildrenText(Widget[] children, Set<Widget> visited,
        StringBuilder text)
    {
        if (children == null)
        {
            return;
        }
        for (Widget child : children)
        {
            appendVisibleText(child, visited, text);
        }
    }

    private void scan(Widget widget, Set<Widget> visited, PageScan scan)
    {
        if (widget == null || widget.isHidden() || !visited.add(widget))
        {
            return;
        }
        if (widget.getItemId() > 0)
        {
            String name = client.getItemDefinition(widget.getItemId()).getName();
            if (!isExcludedGreenLogSlot(name))
            {
                scan.visibleItemCount++;
                int quantity = Math.max(widget.getItemQuantity(), 0);
                if (quantity > 0 && widget.getOpacity() < 100)
                {
                    scan.acquiredSlotCount++;
                    scan.items.merge(name, quantity, Math::max);
                }
            }
        }
        scanChildren(widget.getChildren(), visited, scan);
        scanChildren(widget.getDynamicChildren(), visited, scan);
        scanChildren(widget.getStaticChildren(), visited, scan);
        scanChildren(widget.getNestedChildren(), visited, scan);
    }

    private void scanChildren(Widget[] children, Set<Widget> visited, PageScan scan)
    {
        if (children == null) return;
        for (Widget child : children) scan(child, visited, scan);
    }

    static String knownPageTitle(String text)
    {
        String normalized = text.toLowerCase(Locale.ENGLISH);
        if (normalized.contains("doom of mokhaiotl"))
        {
            return "Doom of Mokhaiotl";
        }
        if (normalized.contains("yama"))
        {
            return "Yama";
        }
        if (normalized.contains("chambers of xeric"))
        {
            return "Chambers of Xeric";
        }
        if (normalized.contains("theatre of blood"))
        {
            return "Theatre of Blood";
        }
        if (normalized.contains("tombs of amascut"))
        {
            return "Tombs of Amascut";
        }
        return null;
    }

    static Integer parseObtainedSlots(String text)
    {
        Matcher matcher = SLOT_FRACTION.matcher(text);
        Integer largest = null;
        while (matcher.find())
        {
            int value = Integer.parseInt(matcher.group(1).replace(",", ""));
            if (largest == null || value > largest)
            {
                largest = value;
            }
        }
        return largest;
    }

    static boolean isExcludedGreenLogSlot(String itemName)
    {
        String normalized = itemName.toLowerCase(Locale.ENGLISH);
        return normalized.contains("shroud")
            || normalized.startsWith("xeric's ");
    }

    private static String clean(String text)
    {
        return text == null ? "" : text.replaceAll("<[^>]*>", "").trim();
    }

    private static final class PageScan
    {
        private int visibleItemCount;
        private int acquiredSlotCount;
        private final Map<String, Integer> items = new LinkedHashMap<>();
    }
}

package com.clanhq.verifier.service;

import com.clanhq.verifier.model.EvidenceSource;
import com.clanhq.verifier.model.DiaryProgress;
import com.clanhq.verifier.model.ObservedItem;
import com.clanhq.verifier.model.VerificationSnapshot;
import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.EquipmentInventorySlot;
import net.runelite.api.GameState;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.Player;
import net.runelite.api.Quest;
import net.runelite.api.QuestState;
import net.runelite.api.Skill;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.client.game.ItemEquipmentStats;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.ItemStats;

public final class LocalPlayerSnapshotService
{
    private final Client client;
    private final ItemManager itemManager;

    @Inject
    public LocalPlayerSnapshotService(Client client, ItemManager itemManager)
    {
        this.client = client;
        this.itemManager = itemManager;
    }

    public VerificationSnapshot captureCompleteItemsEvidence()
    {
        Player player = requireLoggedInPlayer();
        net.runelite.api.widgets.Widget bankFrame = client.getWidget(
            InterfaceID.Bankmain.FRAME);
        ItemContainer bank = client.getItemContainer(InventoryID.BANK);
        if (bankFrame == null || bankFrame.isHidden() || bank == null)
        {
            throw new IllegalStateException(
                "Open your bank before capturing bank and gear evidence.");
        }

        Map<String, ObservedItem> items = new LinkedHashMap<>();
        addItems(client.getItemContainer(InventoryID.WORN),
            EvidenceSource.EQUIPMENT, items);
        addItems(client.getItemContainer(InventoryID.INV),
            EvidenceSource.INVENTORY, items);
        addItems(bank, EvidenceSource.BANK, items);

        return snapshot(player, new ArrayList<>(items.values()), true);
    }

    public VerificationSnapshot captureAccountEvidence()
    {
        Player player = requireLoggedInPlayer();
        return snapshot(player, Collections.emptyList(), false);
    }

    private VerificationSnapshot snapshot(Player player,
        List<ObservedItem> items, boolean bankCaptured)
    {
        return new VerificationSnapshot(
            player.getName(),
            client.getTotalLevel(),
            player.getCombatLevel(),
            items,
            bankCaptured,
            isPietyUnlocked(),
            client.getVarbitValue(VarbitID.PRAYER_RIGOUR_UNLOCKED) == 1,
            client.getVarbitValue(VarbitID.PRAYER_DEADEYE_UNLOCKED) == 1,
            client.getVarbitValue(VarbitID.PRAYER_MYSTIC_VIGOUR_UNLOCKED) == 1,
            client.getRealSkillLevel(Skill.HERBLORE),
            captureDiaryProgress(),
            com.clanhq.verifier.model.RaidKillCounts.unavailable("Not fetched"),
            client.getVarpValue(VarPlayerID.COLLECTION_COUNT))
            .withGrandmasterCombatAchievements(client.getVarbitValue(
                VarbitID.CA_TIER_STATUS_GRANDMASTER) > 0)
            .withAccountMetrics(captureBingoMetrics());
    }

    private Map<String, Integer> captureBingoMetrics()
    {
        Map<String, Integer> metrics = new LinkedHashMap<>();
        metrics.put("wintertodt_reward_points",
            Math.max(0, client.getVarbitValue(VarbitID.WINT_REWARD_POOL)));
        metrics.put("tempoross_reward_permits",
            Math.max(0, client.getVarbitValue(
                VarbitID.TEMPOROSS_REWARDPERMITS)));
        int elemental = Math.max(0,
            client.getVarpValue(VarPlayerID.TOTE_PRIMARY));
        int catalytic = Math.max(0,
            client.getVarpValue(VarPlayerID.TOTE_SECONDARY));
        metrics.put("gotr_reward_searches", Math.min(elemental, catalytic));
        for (Skill skill : Skill.values())
        {
            metrics.put("skill_" + skill.name().toLowerCase(),
                Math.max(1, client.getRealSkillLevel(skill)));
        }
        for (Quest quest : Quest.values())
        {
            metrics.put("quest_" + quest.name().toLowerCase(),
                quest.getState(client) == QuestState.FINISHED ? 1 : 0);
        }
        return metrics;
    }

    private boolean isPietyUnlocked()
    {
        return hasPietyUnlock(Quest.KINGS_RANSOM.getState(client),
            client.getVarbitValue(VarbitID.KR_KNIGHTWAVES_STATE));
    }

    static boolean hasPietyUnlock(QuestState kingsRansom, int knightWavesState)
    {
        return kingsRansom == QuestState.FINISHED && knightWavesState >= 8;
    }

    private Player requireLoggedInPlayer()
    {
        Player player = client.getLocalPlayer();

        if (client.getGameState() != GameState.LOGGED_IN || player == null)
        {
            throw new IllegalStateException(
                "Log into Old School RuneScape before capturing evidence.");
        }

        return player;
    }

    private void addItems(
        ItemContainer container,
        EvidenceSource source,
        Map<String, ObservedItem> observedItems)
    {
        if (container == null)
        {
            return;
        }

        for (Item item : container.getItems())
        {
            if (item.getId() <= 0)
            {
                continue;
            }

            String itemName = client.getItemDefinition(item.getId()).getName();
            Map<String, Object> equipment = equipmentMetadata(item.getId());
            ObservedItem observedItem = new ObservedItem(
                item.getId(),
                itemName,
                item.getQuantity(),
                source,
                equipment);

            String key = source.name() + ':' + item.getId();
            ObservedItem existing = observedItems.get(key);
            if (existing == null)
            {
                observedItems.put(key, observedItem);
            }
            else
            {
                observedItems.put(key, new ObservedItem(
                    item.getId(),
                    itemName,
                    existing.getQuantity() + item.getQuantity(),
                    source,
                    existing.getEquipment().isEmpty()
                        ? equipment : existing.getEquipment()));
            }
        }
    }

    private Map<String, Object> equipmentMetadata(int itemId)
    {
        if (itemManager == null)
        {
            return Collections.emptyMap();
        }
        ItemStats stats;
        try
        {
            stats = itemManager.getItemStats(itemId);
        }
        catch (RuntimeException ignored)
        {
            return Collections.emptyMap();
        }
        if (stats == null || !stats.isEquipable() || stats.getEquipment() == null)
        {
            return Collections.emptyMap();
        }
        ItemEquipmentStats equipment = stats.getEquipment();
        String slot = equipmentSlot(equipment.getSlot());
        if (slot == null)
        {
            return Collections.emptyMap();
        }
        Map<String, Object> values = new LinkedHashMap<>();
        values.put("slot", slot);
        values.put("two_handed", equipment.isTwoHanded());
        values.put("attack_stab", equipment.getAstab());
        values.put("attack_slash", equipment.getAslash());
        values.put("attack_crush", equipment.getAcrush());
        values.put("attack_magic", equipment.getAmagic());
        values.put("attack_ranged", equipment.getArange());
        values.put("defence_stab", equipment.getDstab());
        values.put("defence_slash", equipment.getDslash());
        values.put("defence_crush", equipment.getDcrush());
        values.put("defence_magic", equipment.getDmagic());
        values.put("defence_ranged", equipment.getDrange());
        values.put("strength", equipment.getStr());
        values.put("ranged_strength", equipment.getRstr());
        values.put("magic_damage", equipment.getMdmg());
        values.put("prayer", equipment.getPrayer());
        values.put("attack_speed", equipment.getAspeed());
        return values;
    }

    private static String equipmentSlot(int slot)
    {
        for (EquipmentInventorySlot value : EquipmentInventorySlot.values())
        {
            if (value.getSlotIdx() != slot)
            {
                continue;
            }
            switch (value)
            {
                case HEAD: return "HEAD";
                case CAPE: return "CAPE";
                case AMULET: return "NECK";
                case WEAPON: return "WEAPON";
                case BODY: return "BODY";
                case SHIELD: return "SHIELD";
                case LEGS: return "LEGS";
                case GLOVES: return "HANDS";
                case BOOTS: return "FEET";
                case RING: return "RING";
                case AMMO: return "AMMO";
                default: return null;
            }
        }
        return null;
    }

    private DiaryProgress captureDiaryProgress()
    {
        int[] hardFlags = {VarbitID.ARDOUGNE_DIARY_HARD_COMPLETE,
            VarbitID.FALADOR_DIARY_HARD_COMPLETE,
            VarbitID.WILDERNESS_DIARY_HARD_COMPLETE,
            VarbitID.WESTERN_DIARY_HARD_COMPLETE,
            VarbitID.KANDARIN_DIARY_HARD_COMPLETE,
            VarbitID.VARROCK_DIARY_HARD_COMPLETE,
            VarbitID.DESERT_DIARY_HARD_COMPLETE,
            VarbitID.MORYTANIA_DIARY_HARD_COMPLETE,
            VarbitID.FREMENNIK_DIARY_HARD_COMPLETE,
            VarbitID.LUMBRIDGE_DIARY_HARD_COMPLETE,
            VarbitID.KOUREND_DIARY_HARD_COMPLETE};
        int[] eliteFlags = {VarbitID.ARDOUGNE_DIARY_ELITE_COMPLETE,
            VarbitID.FALADOR_DIARY_ELITE_COMPLETE,
            VarbitID.WILDERNESS_DIARY_ELITE_COMPLETE,
            VarbitID.WESTERN_DIARY_ELITE_COMPLETE,
            VarbitID.KANDARIN_DIARY_ELITE_COMPLETE,
            VarbitID.VARROCK_DIARY_ELITE_COMPLETE,
            VarbitID.DESERT_DIARY_ELITE_COMPLETE,
            VarbitID.MORYTANIA_DIARY_ELITE_COMPLETE,
            VarbitID.FREMENNIK_DIARY_ELITE_COMPLETE,
            VarbitID.LUMBRIDGE_DIARY_ELITE_COMPLETE,
            VarbitID.KOUREND_DIARY_ELITE_COMPLETE};
        int hard = 0;
        int elite = 0;
        for (int flag : hardFlags)
        {
            hard += completed(flag);
        }
        for (int flag : eliteFlags)
        {
            elite += completed(flag);
        }
        hard += client.getVarbitValue(VarbitID.KARAMJA_HARD_COUNT) >= 10 ? 1 : 0;
        elite += completed(VarbitID.KARAMJA_DIARY_ELITE_COMPLETE);
        return new DiaryProgress(hard, elite, 12);
    }

    private int completed(int varbitId)
    {
        return client.getVarbitValue(varbitId) > 0 ? 1 : 0;
    }

}

package com.clanhq.verifier.service;

import com.clanhq.verifier.model.PohEvidence;
import java.util.LinkedHashSet;
import java.util.Locale;
import java.util.Set;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.DecorativeObject;
import net.runelite.api.GameObject;
import net.runelite.api.GroundObject;
import net.runelite.api.Scene;
import net.runelite.api.Tile;
import net.runelite.api.WallObject;
import net.runelite.api.WorldView;
import net.runelite.api.gameval.VarbitID;

public final class PohCaptureService
{
    private final Client client;

    @Inject
    public PohCaptureService(Client client)
    {
        this.client = client;
    }

    public PohEvidence capture()
    {
        if (client.getVarbitValue(VarbitID.POH_BUILDING_MODE) != 1)
        {
            throw new IllegalStateException(
                "Enter your POH in build mode.");
        }
        WorldView worldView = client.getTopLevelWorldView();
        if (worldView == null)
        {
            throw new IllegalStateException("The POH scene is not loaded.");
        }
        Scene scene = worldView.getScene();

        Set<String> facilities = new LinkedHashSet<>();
        for (Tile[][] plane : scene.getTiles())
        {
            for (Tile[] column : plane)
            {
                for (Tile tile : column)
                {
                    inspectTile(tile, facilities);
                }
            }
        }
        return new PohEvidence(true, facilities);
    }

    private void inspectTile(Tile tile, Set<String> facilities)
    {
        if (tile == null)
        {
            return;
        }
        for (GameObject object : tile.getGameObjects())
        {
            if (object != null) inspect(object.getId(), facilities);
        }
        DecorativeObject decorative = tile.getDecorativeObject();
        WallObject wall = tile.getWallObject();
        GroundObject ground = tile.getGroundObject();
        if (decorative != null) inspect(decorative.getId(), facilities);
        if (wall != null) inspect(wall.getId(), facilities);
        if (ground != null) inspect(ground.getId(), facilities);
    }

    private void inspect(int objectId, Set<String> facilities)
    {
        String name = client.getObjectDefinition(objectId).getName()
            .toLowerCase(Locale.ENGLISH);
        if (name.contains("spiritual fairy")) facilities.add(PohEvidence.SPIRITUAL_FAIRY);
        if (name.contains("ornate jewellery box")) facilities.add(PohEvidence.JEWELLERY_BOX);
        if (name.contains("occult altar")) facilities.add(PohEvidence.OCCULT_ALTAR);
        if (name.contains("crystalline portal nexus")) facilities.add(PohEvidence.PORTAL_NEXUS);
        if (name.contains("ornate rejuvenation pool")) facilities.add(PohEvidence.REJUVENATION_POOL);
    }
}

package com.clanhq.verifier.service;

import com.clanhq.verifier.model.RaidKillCounts;
import java.util.concurrent.CompletableFuture;
import javax.inject.Inject;
import net.runelite.client.hiscore.HiscoreClient;
import net.runelite.client.hiscore.HiscoreEndpoint;
import net.runelite.client.hiscore.HiscoreResult;
import net.runelite.client.hiscore.HiscoreSkill;
import net.runelite.client.hiscore.Skill;

public final class RaidKillCountService
{
    private final HiscoreClient hiscoreClient;
    private CompletableFuture<HiscoreResult> lookup;

    @Inject
    public RaidKillCountService(HiscoreClient hiscoreClient)
    {
        this.hiscoreClient = hiscoreClient;
    }

    public void startLookup(String rsn)
    {
        lookup = hiscoreClient.lookupAsync(rsn, HiscoreEndpoint.NORMAL);
    }

    public CompletableFuture<RaidKillCounts> lookupAsync(String rsn)
    {
        return hiscoreClient.lookupAsync(rsn, HiscoreEndpoint.NORMAL)
            .handle((result, error) ->
            {
                if (error != null || result == null)
                {
                    return RaidKillCounts.unavailable(
                        "RuneScape hiscores were unavailable");
                }
                return fromResult(result);
            });
    }

    public RaidKillCounts finishLookup()
    {
        if (lookup == null)
        {
            return RaidKillCounts.unavailable("Hiscore lookup was not started");
        }
        if (!lookup.isDone())
        {
            return RaidKillCounts.unavailable("Hiscore lookup did not finish during capture");
        }
        if (lookup.isCompletedExceptionally())
        {
            return RaidKillCounts.unavailable("RuneScape hiscores were unavailable");
        }

        HiscoreResult result = lookup.getNow(null);
        if (result == null)
        {
            return RaidKillCounts.unavailable("No hiscore result was returned");
        }
        return fromResult(result);
    }

    private static RaidKillCounts fromResult(HiscoreResult result)
    {
        return RaidKillCounts.available(
            count(result, HiscoreSkill.CHAMBERS_OF_XERIC),
            count(result, HiscoreSkill.CHAMBERS_OF_XERIC_CHALLENGE_MODE),
            count(result, HiscoreSkill.THEATRE_OF_BLOOD),
            count(result, HiscoreSkill.THEATRE_OF_BLOOD_HARD_MODE),
            count(result, HiscoreSkill.TOMBS_OF_AMASCUT),
            count(result, HiscoreSkill.TOMBS_OF_AMASCUT_EXPERT));
    }

    public void cancelLookup()
    {
        if (lookup != null)
        {
            lookup.cancel(true);
            lookup = null;
        }
    }

    private static int count(HiscoreResult result, HiscoreSkill activity)
    {
        Skill value = result.getSkill(activity);
        return value == null ? 0 : Math.max(value.getLevel(), 0);
    }
}

package com.clanhq.verifier.service;

import com.clanhq.verifier.ClanHQVerifierConfig;
import java.awt.Component;
import javax.swing.JOptionPane;

/** Presents the explicit disclosure required before complete character data leaves RuneLite. */
public final class SubmissionConsentService
{
    private final ClanHQVerifierConfig config;
    private final ApiDestinationService destinationService;

    public SubmissionConsentService(
        ClanHQVerifierConfig config,
        ApiDestinationService destinationService)
    {
        this.config = config;
        this.destinationService = destinationService;
    }

    public boolean confirm(Component parent, String purpose)
    {
        String destination = destinationService.describe(config.apiBaseUrl())
            .replace("Submits to: ", "");
