package com.clanhq.verifier.daily;

import com.clanhq.verifier.daily.model.DailyTasksSnapshot;
import com.clanhq.verifier.loot.ObservedDrop;
import java.time.Instant;
import java.lang.reflect.Field;
import java.util.Collections;
import java.util.List;
import java.util.Map;
import net.runelite.client.game.ItemStack;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class ItemDropMatcherTest
{
    @Test
    public void onlyMatchingAssignmentIdsReceiveQuantityIncludingNotedItems()
    {
        DailyTasksSnapshot snapshot = DailyTasksSnapshot.fromJson(
            "{\"reset_at\":\"2026-09-08T09:00:00Z\",\"tasks\":["
            + task("a", "Ensouled ogre head", 1001, 1) + ","
            + task("b", "Mithril longsword", 1002, 1) + ","
            + task("c", "Dragon bones", 1003, 10) + "]}");

        ObservedDrop oneNotedDragonBone = new ObservedDrop(
            "Tester", "PVM", "Boss", Collections.singletonList(
                new ItemStack(2003, 1)), Instant.parse("2026-09-07T10:00:00Z"));
        Map<String, ItemDropMatcher.Match> first = ItemDropMatcher.findMatches(
            snapshot, oneNotedDragonBone, itemId -> itemId == 2003 ? 1003 : itemId);
        assertFalse(first.containsKey("a"));
        assertFalse(first.containsKey("b"));
        assertEquals(1, first.get("c").getQuantity());

        ObservedDrop threeDragonBones = new ObservedDrop(
            "Tester", "PVM", "Boss", Collections.singletonList(
                new ItemStack(1003, 3)), Instant.parse("2026-09-07T10:01:00Z"));
        Map<String, ItemDropMatcher.Match> second = ItemDropMatcher.findMatches(
            snapshot, threeDragonBones, itemId -> itemId);
        assertFalse(second.containsKey("a"));
        assertFalse(second.containsKey("b"));
        assertEquals(3, second.get("c").getQuantity());

        ObservedDrop ogreHead = new ObservedDrop(
            "Tester", "PVM", "Boss", Collections.singletonList(
                new ItemStack(1001, 1)), Instant.parse("2026-09-07T10:02:00Z"));
        Map<String, ItemDropMatcher.Match> reverse = ItemDropMatcher.findMatches(
            snapshot, ogreHead, itemId -> itemId);
        assertTrue(reverse.containsKey("a"));
        assertEquals(1, reverse.get("a").getQuantity());
        assertFalse(reverse.containsKey("b"));
        assertFalse(reverse.containsKey("c"));
    }

    @Test
    public void sidebarUpdatesTheAssignmentCardInsteadOfTheFirstDropCard() throws Exception
    {
        DailyTasksSnapshot snapshot = DailyTasksSnapshot.fromJson(
            "{\"reset_at\":\"2026-09-08T09:00:00Z\",\"tasks\":["
            + task("a", "Ensouled ogre head", 1001, 1) + ","
            + task("b", "Mithril longsword", 1002, 1) + ","
            + task("c", "Dragon bones", 1003, 10) + "]}");
        DailyTasksPanel panel = new DailyTasksPanel(() -> { }, ignored -> { }, null);
        panel.showTasks(snapshot, "");

        panel.updateLiveProgress("c", 1);
        assertEquals(0, cardProgress(panel, "a"));
        assertEquals(0, cardProgress(panel, "b"));
        assertEquals(1, cardProgress(panel, "c"));

        panel.updateLiveProgress("c", 4);
        panel.updateLiveProgress("a", 1);
        assertEquals(1, cardProgress(panel, "a"));
        assertEquals(0, cardProgress(panel, "b"));
        assertEquals(4, cardProgress(panel, "c"));
    }

    private static int cardProgress(DailyTasksPanel panel, String assignmentId)
        throws Exception
    {
        Field cardsField = DailyTasksPanel.class.getDeclaredField("cards");
        cardsField.setAccessible(true);
        for (Object card : (List<?>) cardsField.get(panel))
        {
            Field id = card.getClass().getDeclaredField("assignmentId");
            id.setAccessible(true);
            if (assignmentId.equals(id.get(card)))
            {
                Field progress = card.getClass().getDeclaredField("currentProgress");
                progress.setAccessible(true);
                return progress.getInt(card);
            }
        }
        throw new AssertionError("Assignment card not found: " + assignmentId);
    }

    private static String task(String id, String name, int itemId, int target)
    {
        return "{\"id\":\"" + id + "\",\"category\":\"DROP\","
            + "\"name\":\"" + name + "\",\"description\":\"Collect\","
            + "\"target\":" + target + ",\"progress\":0,\"reward\":25,"
            + "\"verification\":{\"type\":\"ITEM_DROP\",\"item_id\":" + itemId + "}}"
            ;
    }
}

package com.clanhq.verifier.daily;

import com.google.gson.JsonArray;
import com.google.gson.JsonObject;
import java.util.concurrent.atomic.AtomicReference;
import org.junit.Test;
import static org.junit.Assert.*;

public class PendingClaimStoreTest
{
    @Test
    public void clickIsPersistedBeforeDeliveryAndRetryKeepsClaimId()
    {
        AtomicReference<String> disk = new AtomicReference<>();
        PendingClaimStore first = new PendingClaimStore(disk::get, disk::set);
        JsonArray progress = new JsonArray();
        JsonObject item = new JsonObject();
        item.addProperty("progress", 10);
        progress.add(item);
        JsonObject queued = first.enqueue("installation-a", "2026-09-29",
            "2026-09-30T00:00:00Z", "2026-09-29T23:59:59Z", "rotation-1", "SKILLING", "task-1",
            progress);
        assertNotNull(disk.get());
        progress.get(0).getAsJsonObject().addProperty("progress", 0);

        PendingClaimStore restarted = new PendingClaimStore(disk::get, disk::set);
        JsonObject retry = restarted.enqueue("installation-a", "2026-09-29",
            "2026-09-30T00:00:00Z", "2026-09-29T23:59:59Z", "rotation-1", "SKILLING", "task-1",
            progress);
        assertEquals(PendingClaimStore.string(queued, "claim_id"),
            PendingClaimStore.string(retry, "claim_id"));
        assertEquals("2026-09-29T23:59:59Z",
            PendingClaimStore.string(retry, "clicked_at"));
        assertEquals(10, retry.getAsJsonArray("client_progress")
            .get(0).getAsJsonObject().get("progress").getAsInt());
        assertEquals(0, restarted.forScope("installation-b").size());
        assertEquals(1, restarted.forScope("installation-a").size());

        restarted.acknowledge(PendingClaimStore.string(retry, "claim_id"));
        assertEquals(0, new PendingClaimStore(disk::get, disk::set)
            .forScope("installation-a").size());
    }
}

package com.clanhq.verifier.daily;

import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.Delayed;
import java.util.concurrent.FutureTask;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.ScheduledThreadPoolExecutor;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicInteger;
import org.junit.Test;
import static org.junit.Assert.*;

public class ReconciliationLoopTest
{
    private final ManualScheduler scheduler = new ManualScheduler();
    private final List<CompletableFuture<Integer>> requests = new ArrayList<>();
    private final List<Integer> applied = new ArrayList<>();
    private final List<Throwable> errors = new ArrayList<>();
    private final ReconciliationLoop<Integer> loop = new ReconciliationLoop<>(scheduler,
        Runnable::run, () -> {
            CompletableFuture<Integer> request = new CompletableFuture<>();
            requests.add(request);
            return request;
        }, (value, error) -> {
            if (error != null) { errors.add(error); }
            else { applied.add(value); }
        });

    @Test
    public void missedNotificationConvergesWhileClientRemainsOpen()
    {
        loop.start();
        requests.get(0).complete(0);
        // Backend commits; no immediate event is delivered.
        scheduler.tick();
        requests.get(1).complete(1);
        assertEquals(List.of(0, 1), applied);
    }

    @Test
    public void rapidClaimsDuringStaleReadQueueOneTrailingAuthoritativeRead()
    {
        loop.start();
        loop.refresh();
        loop.refresh();
        loop.refresh();
        assertEquals(1, requests.size());
        requests.get(0).complete(0);
        assertEquals(2, requests.size());
        requests.get(1).complete(3);
        assertEquals(List.of(0, 3), applied);
    }

    @Test
    public void offlineAndExceptionalReadRecoverOnNextTick()
    {
        loop.start();
        requests.get(0).completeExceptionally(new IllegalStateException("offline"));
        scheduler.tick();
        requests.get(1).complete(2);
        assertEquals(1, errors.size());
        assertEquals(List.of(2), applied);
    }

    @Test
    public void hungReadTimesOutAndLateResponseCannotResurrectStaleState()
    {
        loop.start();
        scheduler.expire();
        scheduler.tick();
        requests.get(1).complete(4);
        requests.get(0).complete(0);
        assertEquals(1, errors.size());
        assertEquals(List.of(4), applied);
    }

    @Test
    public void restartIgnoresPreviousSessionAndCancelsTimers()
    {
        loop.start();
        Tick oldPeriodic = scheduler.periodic;
        loop.stop();
        assertTrue(oldPeriodic.isCancelled());
        loop.start();
        requests.get(1).complete(5);
        requests.get(0).complete(0);
        assertEquals(List.of(5), applied);
        loop.stop();
        scheduler.tick();
        assertEquals(2, requests.size());
    }

    @Test
    public void synchronousFailureDoesNotWedgeRecovery()
    {
        AtomicInteger attempts = new AtomicInteger();
        ReconciliationLoop<Integer> failing = new ReconciliationLoop<>(scheduler,
            Runnable::run, () -> {
                if (attempts.getAndIncrement() == 0) { throw new IllegalStateException(); }
                return CompletableFuture.completedFuture(9);
            }, (value, error) -> { if (error == null) { applied.add(value); } });
        failing.start();
        scheduler.tick();
        assertEquals(List.of(9), applied);
    }

    private static final class ManualScheduler extends ScheduledThreadPoolExecutor
    {
        Tick periodic;
        Tick timeout;
        ManualScheduler() { super(1); }
        @Override
        public ScheduledFuture<?> scheduleWithFixedDelay(Runnable command, long initial,
            long delay, TimeUnit unit)
        {
            assertEquals(30, unit.toSeconds(delay));
            periodic = new Tick(command);
            return periodic;
        }
        @Override
        public ScheduledFuture<?> schedule(Runnable command, long delay, TimeUnit unit)
        {
            timeout = new Tick(command);
            return timeout;
        }
        void tick() { if (!periodic.isCancelled()) { periodic.command.run(); } }
        void expire() { timeout.run(); }
    }

    private static final class Tick extends FutureTask<Void> implements ScheduledFuture<Void>
    {
        final Runnable command;
        Tick(Runnable command) { super(command, null); this.command = command; }
        public long getDelay(TimeUnit unit) { return 0; }
        public int compareTo(Delayed other) { return 0; }
    }
}

